	primary key (AD_PERF_DK)
)COMMENT='재방송 광고 원천 무손실 Staging. [Grain: AD_PERF_DK (1행=1재방송광고)]. [주의: 재방송 광고 원천 21컬럼 보존(2026-09-28 원천 재편 · 사례 반복군 소멸)]. [원천: AGENCY → BRONZE_AGENCY.REBRDC_AD_CMPGN_DTLS].'
;
