create or replace TABLE GN_DW.SILVER.BIGQUERY_BASIC (
	USER_PSEUDO_ID VARCHAR(200) NOT NULL COMMENT '세션 스파인 (PK)',
	EVENT_TIMESTAMP NUMBER(38,0) NOT NULL COMMENT 'UTC microsec (PK)',
	EVENT_NAME VARCHAR(200) NOT NULL COMMENT '이벤트명 (PK)',
	EVENT_SEQ NUMBER(38,0) NOT NULL COMMENT 'EVENT_SEQ.',
	EVENT_DATE VARCHAR(8) COMMENT '원본 YYYYMMDD',
	EVENT_DT DATE NOT NULL COMMENT '업무일자 DATE.',
	EVENT_TS TIMESTAMP_NTZ(9) COMMENT '파생 TIMESTAMP',
	USER_ID VARCHAR(64) COMMENT 'BIGQUERY user_id 원본(불변 보존). USER_ID 사용.',
	ID_SCHEME VARCHAR(20) COMMENT 'ID_SCHEME.',
	BIGQUERY_SESSION_ID NUMBER(38,0) COMMENT 'BigQuery 세션ID(EP_GA_SESSION_ID TRY_CAST).',
	BIGQUERY_SESSION_NUMBER NUMBER(38,0) COMMENT 'BigQuery 세션 번호(EP_GA_SESSION_NUMBER TRY_CAST).',
	BIGQUERY_SESSION_KEY VARCHAR(16777216) COMMENT '파생 세션 자연키 = user_pseudo_id ∥ \".',
	SESSION_ENGAGED VARCHAR(5) COMMENT '세션 engaged 여부(EP_SESSION_ENGAGED).',
	ENGAGEMENT_TIME_MSEC NUMBER(38,0) COMMENT 'ENGAGEMENT_TIME_MSEC.',
	PAGE_LOCATION VARCHAR(16777216) COMMENT '페이지 URL(EP_PAGE_LOCATION)',
	PAGE_TITLE VARCHAR(16777216) COMMENT '페이지 제목(EP_PAGE_TITLE)',
	PAGE_REFERRER VARCHAR(16777216) COMMENT '리퍼러 URL(EP_PAGE_REFERRER)',
	EVENT_CATEGORY VARCHAR(16777216) COMMENT 'EVENT_CATEGORY.',
	EVENT_ACTION VARCHAR(16777216) COMMENT '이벤트 액션(EP_EVENT_ACTION, 센티넬 NULLIF).',
	EVENT_LABEL VARCHAR(16777216) COMMENT '이벤트 라벨(EP_EVENT_LABEL, 센티넬 NULLIF).',
	PERCENT_SCROLLED NUMBER(38,0) COMMENT 'PERCENT_SCROLLED.',
	LINK_URL VARCHAR(16777216) COMMENT '클릭 링크 URL(EP_LINK_URL)',
	LINK_TEXT VARCHAR(16777216) COMMENT '클릭 링크 텍스트(EP_LINK_TEXT)',
	DEVICE_TYPE VARCHAR(10) COMMENT 'DEVICE_TYPE.',
	DEVICE_CATEGORY VARCHAR(16777216) COMMENT '디바이스 카테고리(원본)',
	OS VARCHAR(16777216) COMMENT '운영체제(DEVICE_OPERATING_SYSTEM)',
	BROWSER VARCHAR(16777216) COMMENT '브라우저(DEVICE_WEB_INFO_BROWSER)',
	LANGUAGE VARCHAR(16777216) COMMENT '언어(DEVICE_LANGUAGE)',
	PLATFORM VARCHAR(50) COMMENT '플랫폼(원본)',
	IS_ACTIVE_USER BOOLEAN COMMENT '활성 사용자 여부(원본)',
	GEO_COUNTRY VARCHAR(16777216) COMMENT '국가(원본)',
	GEO_CITY VARCHAR(16777216) COMMENT '도시(원본)',
	UTM_SOURCE VARCHAR(16777216) COMMENT 'UTM_SOURCE.',
	UTM_MEDIUM VARCHAR(16777216) COMMENT 'UTM_MEDIUM.',
	UTM_CAMPAIGN VARCHAR(16777216) COMMENT 'UTM_CAMPAIGN.',
	UTM_CONTENT VARCHAR(16777216) COMMENT 'UTM content(STSLC_MC_CONTENT)',
	UTM_TERM VARCHAR(16777216) COMMENT 'UTM term(STSLC_MC_TERM)',
	SOURCE_MEDIUM VARCHAR(16777216) COMMENT 'SOURCE_MEDIUM.',
	XCHAN_SOURCE VARCHAR(16777216) COMMENT 'XCHAN_SOURCE.',
	XCHAN_MEDIUM VARCHAR(16777216) COMMENT 'XCHAN_MEDIUM.',
	XCHAN_CAMPAIGN VARCHAR(16777216) COMMENT 'XCHAN_CAMPAIGN.',
	DEFAULT_CHANNEL_GROUP VARCHAR(16777216) COMMENT 'DEFAULT_CHANNEL_GROUP.',
	GAC_AD_GROUP_ID VARCHAR(16777216) COMMENT 'GAC_AD_GROUP_ID.',
	GAC_AD_GROUP_NAME VARCHAR(16777216) COMMENT 'GAC_AD_GROUP_NAME.',
	GAC_CAMPAIGN_NAME VARCHAR(16777216) COMMENT 'GAC_CAMPAIGN_NAME.',
	BATCH_ORDERING_ID NUMBER(38,0) COMMENT 'BATCH_ORDERING_ID.',
	DW_SOURCE_SYSTEM VARCHAR(16777216) NOT NULL COMMENT '원천 시스템 식별 (공통감사)',
	DW_SOURCE_TABLE VARCHAR(16777216) COMMENT '원천 테이블 식별 (공통감사)',
	DW_LOAD_TS TIMESTAMP_NTZ(9) NOT NULL COMMENT '최초 적재 시각 (공통감사)',
	DW_UPDATE_TS TIMESTAMP_NTZ(9) COMMENT '최종 갱신 시각 (공통감사)',
	DW_BATCH_ID VARCHAR(16777216) COMMENT '적재 배치 식별자 = dbt invocation_id (공통감사)',
	primary key (USER_PSEUDO_ID, EVENT_TIMESTAMP, EVENT_NAME, EVENT_SEQ)
)COMMENT='BIGQUERY 웹/앱 이벤트 기본 Staging. [Grain: EVENT_DT × EVENT_SEQ (1행=1이벤트)]. [주의: 12컬럼 DDL 타입 캐스팅 정제]. [원천: BIGQUERY → BRONZE_BIGQUERY.EVENTS]. [적재: 롤링 윈도우 증분 — 창 [오늘-bigquery_lookback_days, 9999-12-31] 만 DELETE 후 재적재(멱등). 원천은 지연도착 종료 후 동결(freeze)돼 입고되므로 lookback 은 지연도착 방어가 아니고 실제 역할은 부분적재·중단 run 의 재처리다. 지연도착 재처리 요건이 생기면 dbt_project.yml vars.bigquery_lookback_days 값만 올려 대응 가능하다(개념 구현 상주 · 현재 3). 창보다 오래 run 을 건너뛴 구멍은 OPS.WARN_BIGQUERY_LOAD_GAP 이 감시한다].'
;
create or replace TABLE GN_DW.SILVER.BIGQUERY_DEVICE (
	DEVICE_TYPE VARCHAR(10) NOT NULL COMMENT '디바이스 유형 파생. 값 = PC / M (APP 휴면·O2).',
	PLATFORM VARCHAR(50) COMMENT '플랫폼. 값 = WEB (ANDROID/IOS 미입고). [사유:원천 미입고]',
	DEVICE_CATEGORY VARCHAR(16777216) COMMENT '디바이스 카테고리 (원본)',
	OS VARCHAR(16777216) COMMENT '운영체제',
	BROWSER VARCHAR(16777216) COMMENT '브라우저',
	LANGUAGE VARCHAR(16777216) COMMENT '언어',
	DW_SOURCE_SYSTEM VARCHAR(16777216) NOT NULL COMMENT '원천 시스템 식별 (공통감사)',
	DW_SOURCE_TABLE VARCHAR(16777216) COMMENT '원천 테이블 식별 (공통감사)',
	DW_LOAD_TS TIMESTAMP_NTZ(9) NOT NULL COMMENT '최초 적재 시각 (공통감사)',
	DW_UPDATE_TS TIMESTAMP_NTZ(9) COMMENT '최종 갱신 시각 (공통감사)',
	DW_BATCH_ID VARCHAR(16777216) COMMENT '적재 배치 식별자 = dbt invocation_id (공통감사)'
)COMMENT='BIGQUERY 디바이스 차원. [Grain: DEVICE_CATEGORY × OPERATING_SYSTEM (1행=1디바이스)]. [주의: 접속 기기 및 OS 분류]. [원천: BIGQUERY → BRONZE_BIGQUERY.EVENTS].'
;
create or replace TABLE GN_DW.SILVER.BIGQUERY_EVENT (
	USER_PSEUDO_ID VARCHAR(200) NOT NULL COMMENT '세션 스파인 (PK)',
	EVENT_TIMESTAMP NUMBER(38,0) NOT NULL COMMENT 'UTC microsec (PK)',
	EVENT_NAME VARCHAR(200) NOT NULL COMMENT '이벤트명 (PK)',
	EVENT_SEQ NUMBER(38,0) NOT NULL COMMENT '동일 3키 내 순번 .  BIGQUERY.',
	EVENT_DATE VARCHAR(8) COMMENT '원본 YYYYMMDD',
	EVENT_DT DATE NOT NULL COMMENT '파생 DATE.',
	EVENT_TS TIMESTAMP_NTZ(9) COMMENT '파생 TIMESTAMP',
	USER_ID VARCHAR(64) COMMENT 'BIGQUERY user_id 원본(불변 보존).  BIGQUERY.',
	ID_SCHEME VARCHAR(20) COMMENT 'ID_SCHEME.',
	BIGQUERY_SESSION_ID NUMBER(38,0) COMMENT 'BigQuery 세션ID',
	BIGQUERY_SESSION_NUMBER NUMBER(38,0) COMMENT 'BigQuery 세션 번호',
	BIGQUERY_SESSION_KEY VARCHAR(16777216) COMMENT '파생 세션 자연키 (복합 = pseudo ∥ \".',
	USER_ID_FILLED VARCHAR(64) COMMENT '파생 세션 전파 회원번호.  BIGQUERY.',
	ID_RESOLUTION VARCHAR(20) COMMENT 'ID_RESOLUTION.',
	SESSION_ENGAGED VARCHAR(5) COMMENT '세션 engaged 여부',
	ENGAGEMENT_TIME_MSEC NUMBER(38,0) COMMENT '참여시간 msec (비가산 raw)',
	PAGE_LOCATION VARCHAR(16777216) COMMENT '페이지 URL',
	PAGE_TITLE VARCHAR(16777216) COMMENT '페이지 제목',
	PAGE_REFERRER VARCHAR(16777216) COMMENT '리퍼러 URL',
	EVENT_CATEGORY VARCHAR(16777216) COMMENT '이벤트 카테고리',
	EVENT_ACTION VARCHAR(16777216) COMMENT '이벤트 액션',
	EVENT_LABEL VARCHAR(16777216) COMMENT '이벤트 라벨 (혼합타입)',
	PERCENT_SCROLLED NUMBER(38,0) COMMENT '스크롤 비율',
	LINK_URL VARCHAR(16777216) COMMENT '클릭 링크 URL',
	LINK_TEXT VARCHAR(16777216) COMMENT '클릭 링크 텍스트',
	DEVICE_TYPE VARCHAR(10) COMMENT '디바이스 유형 파생. 값 = M / PC / (unknown).',
	DEVICE_CATEGORY VARCHAR(16777216) COMMENT 'DEVICE_CATEGORY.',
	OS VARCHAR(16777216) COMMENT '운영체제',
	GEO_COUNTRY VARCHAR(16777216) COMMENT '국가',
	GEO_CITY VARCHAR(16777216) COMMENT '도시',
	UTM_SOURCE VARCHAR(16777216) COMMENT 'UTM source',
	UTM_MEDIUM VARCHAR(16777216) COMMENT 'UTM medium',
	UTM_CAMPAIGN VARCHAR(16777216) COMMENT 'UTM campaign',
	DEFAULT_CHANNEL_GROUP VARCHAR(16777216) COMMENT '기본 채널그룹',
	PLATFORM VARCHAR(50) COMMENT '플랫폼. 값 = WEB (ANDROID/IOS 미입고).',
	IS_ACTIVE_USER BOOLEAN COMMENT '활성 사용자 여부',
	BATCH_ORDERING_ID NUMBER(38,0) COMMENT '배치 내 정렬 ID.',
	SRC_TABLE VARCHAR(64) COMMENT '원본 일별 테이블명 계보 (기반 테이블 승계)',
	SRC_FILE_NAME VARCHAR(512) COMMENT '파일 단위 계보 (기반 테이블 승계)',
	DW_SOURCE_SYSTEM VARCHAR(16777216) NOT NULL COMMENT '원천 시스템 식별 (공통감사)',
	DW_SOURCE_TABLE VARCHAR(16777216) COMMENT '원천 테이블 식별 (공통감사)',
	DW_LOAD_TS TIMESTAMP_NTZ(9) NOT NULL COMMENT '최초 적재 시각 (공통감사)',
	DW_UPDATE_TS TIMESTAMP_NTZ(9) COMMENT '최종 갱신 시각 (공통감사)',
	DW_BATCH_ID VARCHAR(16777216) COMMENT '적재 배치 식별자 = dbt invocation_id (공통감사)',
	primary key (USER_PSEUDO_ID, EVENT_TIMESTAMP, EVENT_NAME, EVENT_SEQ)
)COMMENT='BIGQUERY 사용자 행동 팩트 소스. [Grain: EVENT_DT × EVENT_SEQ (1행=1이벤트)]. [주의: 체류시간/스크롤/이탈률 행동 지표]. [원천: BIGQUERY → BRONZE_BIGQUERY.EVENTS]. [적재: 롤링 윈도우 증분 — 창 [오늘-bigquery_lookback_days, 9999-12-31] 만 DELETE 후 재적재(멱등). 원천은 지연도착 종료 후 동결(freeze)돼 입고되므로 lookback 은 지연도착 방어가 아니고 실제 역할은 부분적재·중단 run 의 재처리다. 지연도착 재처리 요건이 생기면 dbt_project.yml vars.bigquery_lookback_days 값만 올려 대응 가능하다(개념 구현 상주 · 현재 3). 창보다 오래 run 을 건너뛴 구멍은 OPS.WARN_BIGQUERY_LOAD_GAP 이 감시한다].'
;
create or replace TABLE GN_DW.SILVER.BIGQUERY_EVENT_DIM (
	EVENT_NAME VARCHAR(200) NOT NULL COMMENT '이벤트명 (그레인 핵심키)',
	EVENT_CATEGORY VARCHAR(16777216) COMMENT '이벤트 카테고리',
	EVENT_LABEL VARCHAR(16777216) COMMENT '이벤트 라벨 (혼합타입)',
	EVENT_ACTION VARCHAR(16777216) COMMENT '이벤트 액션',
	DW_SOURCE_SYSTEM VARCHAR(16777216) NOT NULL COMMENT '원천 시스템 식별 (공통감사)',
	DW_SOURCE_TABLE VARCHAR(16777216) COMMENT '원천 테이블 식별 (공통감사)',
	DW_LOAD_TS TIMESTAMP_NTZ(9) NOT NULL COMMENT '최초 적재 시각 (공통감사)',
	DW_UPDATE_TS TIMESTAMP_NTZ(9) COMMENT '최종 갱신 시각 (공통감사)',
	DW_BATCH_ID VARCHAR(16777216) COMMENT '적재 배치 식별자 = dbt invocation_id (공통감사)'
)COMMENT='BIGQUERY 이벤트 분류 차원. [Grain: EVENT_NAME × PARAM_NAME (1행=1이벤트분류)]. [주의: 주요 웹/앱 이벤트 정의]. [원천: BIGQUERY → BRONZE_BIGQUERY.EVENTS].'
;
create or replace TABLE GN_DW.SILVER.BIGQUERY_IDENTITY (
	USER_PSEUDO_ID VARCHAR(200) NOT NULL COMMENT '세션 스파인 (PK)',
	BIGQUERY_MEMBER_ID VARCHAR(64) COMMENT 'BigQuery측 회원 식별자(=USER_ID_FILLED).',
	ID_SCHEME VARCHAR(20) NOT NULL COMMENT 'ID 체계 (PK) — MBER_NO/ONCE_MBER_NO/APP/EMAIL/INVALID/UNCLASSIFIED',
	MEMBER_TYPE VARCHAR(10) COMMENT '회원구분 ONCE(S+8자리) / FDRM(7자리).',
	MBER_NO VARCHAR(10) COMMENT '정기 회원번호. ID_SCHEME=MBER_NO 일 때만 채움.',
	ONCE_MBER_NO VARCHAR(10) COMMENT '일시 회원번호 (S+8자리)',
	ID_RESOLUTION VARCHAR(20) COMMENT 'ID_RESOLUTION.',
	DW_SOURCE_SYSTEM VARCHAR(16777216) NOT NULL COMMENT '원천 시스템 식별 (공통감사)',
	DW_SOURCE_TABLE VARCHAR(16777216) COMMENT '원천 테이블 식별 (공통감사)',
	DW_LOAD_TS TIMESTAMP_NTZ(9) NOT NULL COMMENT '최초 적재 시각 (공통감사)',
	DW_UPDATE_TS TIMESTAMP_NTZ(9) COMMENT '최종 갱신 시각 (공통감사)',
	DW_BATCH_ID VARCHAR(16777216) COMMENT '적재 배치 식별자 = dbt invocation_id (공통감사)',
	primary key (USER_PSEUDO_ID, ID_SCHEME)
)COMMENT='BIGQUERY 사용자 신원 차원. [Grain: USER_PSEUDO_ID × ID_SCHEME (1행=1사용자)]. [주의: BIGQUERY 쿠키 식별자와 CRM 회원 매핑]. [원천: BIGQUERY → BRONZE_BIGQUERY.EVENTS].'
;
