	SPONSOR_BIZ_NM VARCHAR(16777216) COMMENT '후원사업',
	CAMPAIGN_NM VARCHAR(16777216) COMMENT '캠페인 (연결키 부재 Q10)',
	TARGET_TYPE VARCHAR(16777216) COMMENT '목표 편성 차수: 당초(원천 BDGT_PRCD_NM=연사업) / 추경(추가경정) · O190 파생',
	TARGET_CNT NUMBER(18,4) COMMENT '목표값 — 단위는 GOAL_TYPE_NM 에 따른다(건·명·원·비율) · 지표사전 #152~155 · O190',
	DW_SOURCE_SYSTEM VARCHAR(16777216) NOT NULL COMMENT '원천 시스템 식별 (공통감사)',
	DW_SOURCE_TABLE VARCHAR(16777216) COMMENT '원천 테이블 식별 (공통감사)',
