	DW_UPDATE_TS TIMESTAMP_NTZ(9) COMMENT '최종 갱신 시각 (공통감사)',
	DW_BATCH_ID VARCHAR(16777216) COMMENT '적재 배치 식별자 = dbt invocation_id (공통감사)',
	GOAL_TYPE_NM VARCHAR(16777216) COMMENT '목표 지표 유형 원천 표기 그대로(O190 · 9종): 건 = 후원사업·회원개발 / 명 = 월말활동회원 / 원 = 정기회비 / 비율 = 후원사업활동율·신규기존활동율·후원사업납입율·신규기존납입율·신규기존누계납입율. 🔴 유형마다 단위가 달라 섞어 합산하지 말 것 · 후원사업과 회원개발은 같은 개발 목표의 다른 분해(문서20 N-24)',
	CPR_DIV_NM VARCHAR(16777216) COMMENT '법인구분 (사단/사복)',
	NEW_OLD_DIV_NM VARCHAR(16777216) COMMENT '신규/기존 구분 원천 표기. 🔴 비율 유형에는 소계 행(합계·신규합계)이 있다 — 신규/기존과 함께 합산하면 이중계상. 회원개발 유형은 NULL · O190',
	ORG_DIV_NM VARCHAR(16777216) COMMENT '조직구분 (본부/지부/대면 등)',
	DTL_DIV_NM VARCHAR(16777216) COMMENT '세부구분 원천 표기(채널 등 · 회원개발 유형만 · 그 외 NULL) · O190',
	BDGT_PRCD_NM VARCHAR(16777216) COMMENT '예산절차(편성 차수) 원천 표기 그대로: 연사업/추가경정 [원천 COMMENT · BRONZE_CRM.TM_CM_MBER_DVLP_GOAL_DIV: 예산절차] — TARGET_TYPE 파생 입력 · O190',
	primary key (BIZ_TARGET_DK)
)COMMENT='사업목표 마스터. [Grain: TARGET_YEAR × MONTH_NO × BDGT_PRCD_NM × GOAL_TYPE_NM × 원천 구분축(법인·신규기존·조직구분·팀·후원사업·세부구분) (1행=1목표값)]. [주의: GOAL_TYPE_NM 9종은 단위가 다르다(건·명·원·비율) — 유형 필터 필수]. [원천: CRM → BRONZE_CRM.TM_CM_MBER_DVLP_GOAL_DIV].'
;
