	BUDGET_YEAR NUMBER(4,0) COMMENT '예산연도 YYYY',
	INCOME_EXPS_DIV_NM VARCHAR(16777216) COMMENT '수입/지출 구분',
	BDGT_UNIT_NM VARCHAR(16777216) COMMENT '예산단위 (=조직명, 코드 없음)',
	JANG_NM VARCHAR(16777216) COMMENT '예산과목 1단계 장',
	KWAN_NM VARCHAR(16777216) COMMENT '예산과목 2단계 관',
	HANG_NM VARCHAR(16777216) COMMENT '예산과목 3단계 항',
	MOK_NM VARCHAR(16777216) COMMENT '예산과목 4단계 목',
	DTL_ITEM_NM VARCHAR(16777216) COMMENT '예산과목 5단계 세목',
	SUBDTL_ITEM_NM VARCHAR(16777216) COMMENT '예산과목 6단계 세세목',
	FUND_SOURCE_NM VARCHAR(16777216) COMMENT '재원',
	DW_SOURCE_SYSTEM VARCHAR(16777216) NOT NULL COMMENT '원천 시스템 식별 (공통감사)',
	DW_SOURCE_TABLE VARCHAR(16777216) COMMENT '원천 테이블 식별 (공통감사)',
	DW_LOAD_TS TIMESTAMP_NTZ(9) NOT NULL COMMENT '최초 적재 시각 (공통감사)',
	DW_UPDATE_TS TIMESTAMP_NTZ(9) COMMENT '최종 갱신 시각 (공통감사)',
	DW_BATCH_ID VARCHAR(16777216) COMMENT '적재 배치 식별자 = dbt invocation_id (공통감사)',
	primary key (BUDGET_ITEM_DK)
)COMMENT='예산 계정과목 마스터. [Grain: BDGT_ITEM_CD (1행=1예산과목)]. [주의: 장/관/항/목/세목/세세목 계층 매핑]. [원천: ERP → BRONZE_ERP.BDGT_ACMSLT_LEDGER].'
;
create or replace TABLE GN_DW.SILVER.ERP_BUDGET_YEARLY (
	BUDGET_ITEM_DK VARCHAR(16777216) NOT NULL COMMENT '불변 비즈니스 식별자',
	BUDGET_YEAR NUMBER(4,0) NOT NULL COMMENT '예산연도 YYYY . 본 테이블의 grain 은 **연**이다.',
	BUDGET_PROCEDURE VARCHAR(16777216) COMMENT '예산 편성 차수 (연사업 / 추가경정 · DEC.',
	YEAR_BDGT_TOT_AMT NUMBER(38,0) COMMENT 'YEAR_BDGT_TOT_AMT.',
	CHN_BDGT_TOT_AMT NUMBER(38,0) COMMENT '연 추경예산 총액 원단위 = 원천 CHN_BDGT_TOT_AMT.',
	ADJ_BDGT_TOT_AMT NUMBER(38,0) COMMENT '연 조정예산 총액 원단위 = 원천 ADJ_BDGT_TOT_AMT.',
	EXEC_TOT_AMT NUMBER(38,0) COMMENT '연 집행 총액 원단위 = 원천 EXEC_TOT_AMT.',
	DW_SOURCE_SYSTEM VARCHAR(16777216) NOT NULL COMMENT '원천 시스템 식별 (공통감사)',
	DW_SOURCE_TABLE VARCHAR(16777216) COMMENT '원천 테이블 식별 (공통감사)',
	DW_LOAD_TS TIMESTAMP_NTZ(9) NOT NULL COMMENT '최초 적재 시각 (공통감사)',
	DW_UPDATE_TS TIMESTAMP_NTZ(9) COMMENT '최종 갱신 시각 (공통감사)',
	DW_BATCH_ID VARCHAR(16777216) COMMENT '적재 배치 식별자 = dbt invocation_id (공통감사)',
	primary key (BUDGET_ITEM_DK, BUDGET_YEAR)
)COMMENT='연도별 예산 총액 원장. [Grain: BDGT_ITEM_CD × DEPT_ID × YEAR (1행=1연예산)]. [주의: 연 총액 편성/집행액 관리]. [원천: ERP → BRONZE_ERP.BDGT_ACMSLT_LEDGER].'
;
create or replace TABLE GN_DW.SILVER.IDENTITY_MEMBER_XREF (
	USER_PSEUDO_ID VARCHAR(200) NOT NULL COMMENT 'BigQuery 세션 스파인 (PK)',
	BIGQUERY_MEMBER_ID VARCHAR(64) COMMENT 'BigQuery측 회원 식별자(원문 보존).',
	ID_SCHEME VARCHAR(20) COMMENT 'BigQuery측 ID 체계. 매칭 분모 판정의 정본.',
	MEMBER_TYPE VARCHAR(10) COMMENT '회원구분 ONCE/FDRM. 비회원 ID 체계는 NULL.',
	MEMBER_DK VARCHAR(10) COMMENT '매칭된 CRM 불변회원키(미매칭 NULL)',
	HOMEPAGE_ID VARCHAR(16777216) COMMENT '매칭 CRM 회원의 HMPG_ID(미매칭 NULL)',
	ID_RESOLUTION VARCHAR(20) COMMENT 'GA측 신뢰도: DIRECT/SESSION_FILL',
	MATCH_METHOD VARCHAR(30) COMMENT 'MATCH_METHOD.',
	MATCH_CONFIDENCE VARCHAR(10) COMMENT '매칭신뢰도 HIGH/MEDIUM/NONE',
	DW_SOURCE_SYSTEM VARCHAR(16777216) NOT NULL COMMENT '원천 시스템 식별 (공통감사)',
	DW_SOURCE_TABLE VARCHAR(16777216) COMMENT '원천 테이블 식별 (공통감사)',
	DW_LOAD_TS TIMESTAMP_NTZ(9) NOT NULL COMMENT '최초 적재 시각 (공통감사)',
	DW_UPDATE_TS TIMESTAMP_NTZ(9) COMMENT '최종 갱신 시각 (공통감사)',
	DW_BATCH_ID VARCHAR(16777216) COMMENT '적재 배치 식별자 = dbt invocation_id (공통감사)',
	primary key (USER_PSEUDO_ID)
)COMMENT='온-오프라인 신원 연계 브릿지. [Grain: USER_PSEUDO_ID × MEMBER_DK (1행=1연계)]. [주의: BIGQUERY 사용자 식별자와 CRM 회원번호 연결]. [원천: BIGQUERY/CRM → SILVER.BIGQUERY_IDENTITY].'
;
create or replace TABLE GN_DW.SILVER.MM_SPNSR_CLS_AGGR_DATA (
	STDR_MT VARCHAR(16777216) COMMENT '기준월',
	AGGR_TY_NM VARCHAR(16777216) COMMENT '집계 유형명',
	CPR_NM VARCHAR(16777216) COMMENT '법인명',
	SPNSR_BSNS_GRP_NM VARCHAR(16777216) COMMENT '후원 사업 그룹 명',
	NEW_EXST_DIV_NM VARCHAR(16777216) COMMENT '신규기존구분명',
	HDQ_BRNCH_GRP_NM VARCHAR(16777216) COMMENT '본부 지부 그룹 명',
	VALUE1 NUMBER(38,10) COMMENT '값1',
	VALUE2 NUMBER(38,10) COMMENT '값2'
)COMMENT='회원실 회비예측 월간 후원 분류별 집계'
;
CREATE OR REPLACE PROCEDURE GN_DW.SILVER.SP_ANNUAL_DVLP_GOAL_ACMSLT_AGGR_DATA1("INPUT_YYYYMM" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS CALLER
AS '
DECLARE
    FROM_MT VARCHAR;
    TO_MT VARCHAR;
    UPDATE_SQL VARCHAR;
BEGIN
    -- 0. 파라미터
    IF (NOT REGEXP_LIKE(input_yyyymm, ''^[0-9]{6}$'')) THEN
        RETURN ''ERROR: input_yyyymm은 YYYYMM 형식이어야 합니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'') IS NULL) THEN
        RETURN ''ERROR: 유효하지 않은 년월입니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (
        TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'')
        > DATE_TRUNC(''MONTH'', CURRENT_DATE())
    ) THEN
        RETURN ''ERROR: 미래 년월은 입력할 수 없습니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    FROM_MT := input_yyyymm;
    TO_MT := FROM_MT;
    -- 1. CTE
    CREATE OR REPLACE TEMPORARY TABLE GN_DW.SILVER.RESULT_TEMP AS   
    WITH
    PARAM AS (
        SELECT
            :FROM_MT AS FROM_MT,
            :TO_MT   AS TO_MT,
    
            TO_DATE(:FROM_MT || ''01'', ''YYYYMMDD'') AS START_DE,
    
            DATEADD(
                MONTH,
                1,
                TO_DATE(:TO_MT || ''01'', ''YYYYMMDD'')
            ) AS NEXT_DE
    ),
    
    -- 1. 조회기간 개발 원천
    DVLP_SOURCE AS (
        SELECT
            LEFT(A.OCCRRNC_DE, 6) AS STRD_MT,
            A.OCCRRNC_DE,
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.SER_NO,
            A.MBER_NO,
            A.ACMSLT_DEPT_CD,
            A.SPNSR_BSNS_ID,
            A.DVLP_DIV_CD,
            CAST(A.SPNSR_AMT AS NUMBER(28, 4)) AS SPNSR_AMT
    
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_DVLP_AMT AS A
    
        CROSS JOIN PARAM AS P
    
        WHERE A.OCCRRNC_DE >= TO_CHAR(P.START_DE, ''YYYYMMDD'')
          AND A.OCCRRNC_DE <  TO_CHAR(P.NEXT_DE, ''YYYYMMDD'')
          AND A.DVLP_DIV_CD IN (''1'', ''2'', ''3'', ''4'', ''5'')
    ),
    
    -- 신규·재후원 이벤트에 등장한 후원번호·후원사업번호
    RELEVANT_SPNSR_BSNS AS (
        SELECT DISTINCT
            S.SPNSR_NO,
            S.SPNSR_BSNS_NO
    
        FROM DVLP_SOURCE AS S
    
        WHERE S.DVLP_DIV_CD IN (''1'', ''4'')
    ),
    
    -- 후원사업 월말 유지 판정용
    SPNSR_BSNS_PERIOD AS (
        SELECT
            S.SPNSR_NO,
            B.SPNSR_BSNS_NO,
    
            COALESCE(
                B.SPNSR_DSCNTC_DE,
                ''99991231''
            ) AS DSC_DE
    
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR AS S
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR_BSNS AS B
            ON S.SPNSR_NO = B.SPNSR_NO
    
        INNER JOIN RELEVANT_SPNSR_BSNS AS K
            ON B.SPNSR_NO      = K.SPNSR_NO
           AND B.SPNSR_BSNS_NO = K.SPNSR_BSNS_NO
    ),
    -- 2. 신규(1) · 재후원(4)
    NEW_RE_BASE AS (
        SELECT
            D.STRD_MT,
            D.OCCRRNC_DE,
            D.SPNSR_NO,
            D.SPNSR_BSNS_NO,
            D.SER_NO,
            D.MBER_NO,
            D.ACMSLT_DEPT_CD,
            D.SPNSR_BSNS_ID,
            D.DVLP_DIV_CD,
            D.SPNSR_AMT,
            SUM(D.SPNSR_AMT) OVER (
                PARTITION BY
                    D.SPNSR_NO,
                    D.SPNSR_BSNS_NO,
                    D.STRD_MT
            ) AS MAMT
        FROM DVLP_SOURCE AS D
        INNER JOIN SPNSR_BSNS_PERIOD AS P
            ON D.SPNSR_NO      = P.SPNSR_NO
           AND D.SPNSR_BSNS_NO = P.SPNSR_BSNS_NO
           AND P.DSC_DE > D.STRD_MT || ''31''
        WHERE D.DVLP_DIV_CD IN (''1'', ''4'')
    ),
    TRANSFORMED_NEW_RE AS (
        SELECT
            N.STRD_MT,
            N.OCCRRNC_DE,
            N.SPNSR_NO,
            N.SPNSR_BSNS_NO,
            N.SER_NO,
            N.MBER_NO,
            COALESCE(
                N.ACMSLT_DEPT_CD,
                ''Z~''
            ) AS ACMSLT_DEPT_CD,
            N.SPNSR_BSNS_ID,
            N.DVLP_DIV_CD,
            CAST(N.SPNSR_AMT AS NUMBER(28, 4)) AS SPNSR_AMT
        FROM NEW_RE_BASE AS N
        WHERE N.MAMT > 0
    ),
    -- 3. 증액(2)
    INCREASE_BASE AS (
        SELECT
            D.STRD_MT,
            D.OCCRRNC_DE,
            D.SPNSR_NO,
            D.SPNSR_BSNS_NO,
            D.SER_NO,
            D.MBER_NO,
            D.ACMSLT_DEPT_CD,
            D.SPNSR_BSNS_ID,
            D.DVLP_DIV_CD,
            D.SPNSR_AMT,
    
            SUM(
                CASE
                    WHEN D.DVLP_DIV_CD IN (''2'', ''3'')
                        THEN D.SPNSR_AMT
                    ELSE CAST(0 AS NUMBER(28, 4))
                END
            ) OVER (
                PARTITION BY
                    D.SPNSR_NO,
                    D.SPNSR_BSNS_NO,
                    D.STRD_MT
            ) AS SAMT,
    
            SUM(D.SPNSR_AMT) OVER (
                PARTITION BY
                    D.MBER_NO,
                    D.STRD_MT
            ) AS MAMT
    
        FROM DVLP_SOURCE AS D
    
        WHERE D.DVLP_DIV_CD IN (''2'', ''3'', ''5'')
    ),
    INCREASE_FILTERED AS (
        SELECT
            I.STRD_MT,
            I.OCCRRNC_DE,
            I.SPNSR_NO,
            I.SPNSR_BSNS_NO,
            I.SER_NO,
            I.MBER_NO,
            I.ACMSLT_DEPT_CD,
            I.SPNSR_BSNS_ID,
            I.DVLP_DIV_CD,
            I.SPNSR_AMT,
            I.SAMT,
            I.MAMT,
    
            SUM(
                CASE
                    WHEN I.DVLP_DIV_CD = ''3''
                        THEN I.SPNSR_AMT
                    ELSE CAST(0 AS NUMBER(28, 4))
                END
            ) OVER (
                PARTITION BY
                    I.MBER_NO,
                    I.STRD_MT
            ) AS DAMT
    
        FROM INCREASE_BASE AS I
    
        WHERE I.MAMT > 0
          AND (
                (
                    I.SAMT > 0
                    AND I.DVLP_DIV_CD = ''2''
                )
                OR
                (
                    I.SAMT < 0
                    AND I.DVLP_DIV_CD = ''3''
                )
          )
    ),
    INCREASE_ONLY2 AS (
        SELECT
            I.STRD_MT,
            I.OCCRRNC_DE,
            I.SPNSR_NO,
            I.SPNSR_BSNS_NO,
            I.SER_NO,
            I.MBER_NO,
            I.ACMSLT_DEPT_CD,
            I.SPNSR_BSNS_ID,
            I.SPNSR_AMT,
            I.SAMT,
            I.MAMT,
            I.DAMT,
    
            SUM(I.SAMT) OVER (
                PARTITION BY
                    I.MBER_NO,
                    I.STRD_MT
                ORDER BY
                    I.OCCRRNC_DE,
                    I.SER_NO
                ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
            ) AS AAMT
    
        FROM INCREASE_FILTERED AS I
    
        WHERE I.DVLP_DIV_CD = ''2''
    ),
    INCREASE_RANKED AS (
        SELECT
            I.STRD_MT,
            I.OCCRRNC_DE,
            I.SPNSR_NO,
            I.SPNSR_BSNS_NO,
            I.SER_NO,
            I.MBER_NO,
            I.ACMSLT_DEPT_CD,
            I.SPNSR_BSNS_ID,
    
            ROW_NUMBER() OVER (
                PARTITION BY
                    I.STRD_MT,
                    I.SPNSR_NO,
                    I.SPNSR_BSNS_NO
                ORDER BY
                    I.SER_NO
            ) AS RNUM,
    
            CASE
                WHEN I.MAMT <= I.SAMT
                     AND I.AAMT + I.DAMT <= I.MAMT
                    THEN I.AAMT + I.DAMT
    
                WHEN I.MAMT > I.SAMT
                     AND I.AAMT + I.DAMT <= I.SAMT
                    THEN I.AAMT + I.DAMT
    
                WHEN I.MAMT <= I.SAMT
                    THEN I.MAMT
    
                ELSE I.SAMT
            END AS RAMT
    
        FROM INCREASE_ONLY2 AS I
    
        WHERE I.AAMT - ABS(I.DAMT) > 0
    ),
    TRANSFORMED_INCREASE AS (
        SELECT
            I.STRD_MT,
            I.OCCRRNC_DE,
            I.SPNSR_NO,
            I.SPNSR_BSNS_NO,
            I.SER_NO,
            I.MBER_NO,
    
            COALESCE(
                I.ACMSLT_DEPT_CD,
                ''Z~''
            ) AS ACMSLT_DEPT_CD,
    
            I.SPNSR_BSNS_ID,
    
            ''2'' AS DVLP_DIV_CD,
    
            CAST(I.RAMT AS NUMBER(28, 4)) AS SPNSR_AMT
    
        FROM INCREASE_RANKED AS I
    
        WHERE I.RNUM = 1
    ),
    -- 신규/재후원 + 증액
    TRANSFORMED_DVLP AS (
        SELECT *
        FROM TRANSFORMED_NEW_RE
    
        UNION ALL
    
        SELECT *
        FROM TRANSFORMED_INCREASE
    ),
    -- 4. 후원사업 차원
    BUSINESS_DIM_BASE AS (
        SELECT
            CAST(B.SPNSR_BSNS_ID AS VARCHAR) AS SPNSR_BSNS_ID,
    
            COALESCE(
                CAST(B.SPNSR_BSNS_ABRV_CD AS VARCHAR),
                ''99''
            ) AS SPNSR_BSNS_ABRV_CD,
    
            CASE CAST(B.CPR_DIV_CD AS VARCHAR)
                WHEN ''1'' THEN ''I''
                WHEN ''2'' THEN ''S''
                ELSE COALESCE(
                    CAST(B.CPR_DIV_CD AS VARCHAR),
                    ''0''
                )
            END AS CPR_DIV_CD
    
        FROM GN_DW.BRONZE_CRM.TM_CM_SPNSR_BSNS_INFO AS B
    ),
    
    
    BUSINESS_DIM AS (
        SELECT
            SPNSR_BSNS_ID,
            SPNSR_BSNS_ABRV_CD,
            CPR_DIV_CD
    
        FROM BUSINESS_DIM_BASE
    
        UNION ALL
    
        SELECT
            ''99'' AS SPNSR_BSNS_ID,
            ''99'' AS SPNSR_BSNS_ABRV_CD,
            ''Z''  AS CPR_DIV_CD
    
        WHERE NOT EXISTS (
            SELECT 1
            FROM BUSINESS_DIM_BASE
            WHERE SPNSR_BSNS_ID = ''99''
        )
    ),
    
    -- 5. REPORT FACT   
    REPORT_FACT AS (
        SELECT
            T.STRD_MT,
    
            COALESCE(
                B.CPR_DIV_CD,
                ''0''
            ) AS CPR_DIV_CD,
    
            COALESCE(
                T.ACMSLT_DEPT_CD,
                ''Z~''
            ) AS ACMSLT_DEPT_CD,
    
            CASE
                WHEN LEFT(T.OCCRRNC_DE, 4)
                     =
                     LEFT(
                         TO_CHAR(M.FRST_REGIST_DT, ''YYYY-MM-DD''),
                         4
                     )
                    THEN ''1''
                ELSE ''2''
            END AS NEW_OLD_DIV_CD,
    
            COALESCE(
                B.SPNSR_BSNS_ABRV_CD,
                ''99''
            ) AS SPNSR_BSNS_ABRV_CD,
    
            T.DVLP_DIV_CD,
    
            CAST(
                CAST(T.SPNSR_AMT AS NUMBER(28, 4))
                / 10000.0
                AS NUMBER(38, 10)
            ) AS SPNSR_AMT_CNT
    
        FROM TRANSFORMED_DVLP AS T
    
        LEFT JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_INFO AS M
            ON T.MBER_NO = M.MBER_NO
    
        LEFT JOIN BUSINESS_DIM AS B
            ON CAST(T.SPNSR_BSNS_ID AS VARCHAR)
             = B.SPNSR_BSNS_ID
    
        WHERE T.DVLP_DIV_CD IN (''1'', ''2'', ''4'')
    ),
    
    
    -- 6. 최종 집계
    REPORT_AGG AS (
        SELECT
            F.CPR_DIV_CD,
            F.ACMSLT_DEPT_CD AS DEPT_ID,
            F.NEW_OLD_DIV_CD,
            F.SPNSR_BSNS_ABRV_CD,
            F.STRD_MT,
            SUM(F.SPNSR_AMT_CNT) AS WJXBFS1
    
        FROM REPORT_FACT AS F
    
        CROSS JOIN PARAM AS P
    
        WHERE F.STRD_MT >= P.FROM_MT
          AND F.STRD_MT <= P.TO_MT
          AND F.DVLP_DIV_CD IN (''1'', ''2'', ''4'')
    
        GROUP BY
            F.CPR_DIV_CD,
            F.ACMSLT_DEPT_CD,
            F.NEW_OLD_DIV_CD,
            F.SPNSR_BSNS_ABRV_CD,
            F.STRD_MT
    ),
    -- 7. 코드 차원    
    CPR_DIM AS (
        SELECT
            CAST(D.DTL_CD_ID AS VARCHAR) AS CPR_DIV_CD,
            MAX(D.DTL_CD_NM) AS CPR_DIV_NM
    
        FROM GN_DW.BRONZE_CRM.TC_CMMN_DTL_CD AS D
    
        WHERE D.CD_ID = ''CM019''
    
        GROUP BY
            CAST(D.DTL_CD_ID AS VARCHAR)
    ),
    
    
    DEPT_DIM_BASE AS (
        SELECT
            CAST(D.DEPT_ID AS VARCHAR) AS DEPT_ID,
            MAX(D.DEPT_NM) AS DEPT_NM
    
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO AS D
    
        GROUP BY
            CAST(D.DEPT_ID AS VARCHAR)
    ),
    
    
    DEPT_DIM AS (
        SELECT
            DEPT_ID,
            DEPT_NM
    
        FROM DEPT_DIM_BASE
    
        UNION ALL
    
        SELECT
            ''Z~'' AS DEPT_ID,
            ''없음'' AS DEPT_NM
    
        WHERE NOT EXISTS (
            SELECT 1
            FROM DEPT_DIM_BASE
            WHERE DEPT_ID = ''Z~''
        )
    ),
    -- 부서 계층화
    DEPT_HIERARCHY AS (
        SELECT
            E.DEPT_ID AS SOURCE_DEPT_ID,
    
            /* 기존 로직의 DEPT4 */
            B.DEPT_ID AS DEPT4_ID,
            B.DEPT_NM AS DEPT4_NM,
    
            /* 상위 조직 */
            A.DEPT_ID AS UPPER_DEPT1_ID,
            A.DEPT_NM AS UPPER_DEPT1_NM,
    
            C.DEPT_ID AS UPPER_DEPT2_ID,
            C.DEPT_NM AS DEPT_DIV_NM,
    
            D.DEPT_ID AS UPPER_DEPT3_ID,
            D.DEPT_NM AS UPPER_DEPT3_NM
    
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO A
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO B
            ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO C
            ON C.ACMSLT_UPPER_DEPT_ID = B.DEPT_ID
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO D
            ON D.ACMSLT_UPPER_DEPT_ID = C.DEPT_ID
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO E
            ON E.ACMSLT_UPPER_DEPT_ID = D.DEPT_ID
    
        WHERE A.UPPER_DEPT_ID = ''ZV000000''
          AND C.DEPT_ID <> ''ZC000029''
    
        UNION ALL
    
        /* 실적부서가 Z~인 경우 */
        SELECT
            ''Z~'' AS SOURCE_DEPT_ID,
    
            ''Z~'' AS DEPT4_ID,
            ''없음'' AS DEPT4_NM,
    
            ''Z~'' AS UPPER_DEPT1_ID,
            ''없음'' AS UPPER_DEPT1_NM,
    
            ''Z~'' AS UPPER_DEPT2_ID,
            ''없음'' AS DEPT_DIV_NM,
    
            ''Z~'' AS UPPER_DEPT3_ID,
            ''없음'' AS UPPER_DEPT3_NM
    ),
    -- 기존 DEPT4 차원   
    DEPT4_DIM AS (
        SELECT
            B.DEPT_ID AS DEPT4_ID,
            B.DEPT_NM AS DEPT4_NM,
            B.SORT_ORDR
    
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO A
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO B
            ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
    
        WHERE A.UPPER_DEPT_ID = ''ZV000000''
          AND A.USE_YN = ''Y''
    
        UNION ALL
    
        SELECT
            ''Z~'' AS DEPT4_ID,
            ''없음'' AS DEPT4_NM,
            999 AS SORT_ORDR
    ),
    
    
    ABRV_DIM AS (
        SELECT
            CAST(D.DTL_CD_ID AS VARCHAR) AS SPNSR_BSNS_ABRV_CD,
            MAX(D.DTL_CD_NM) AS SPNSR_BSNS_GRP_NM
    
        FROM GN_DW.BRONZE_CRM.TC_CMMN_DTL_CD AS D
    
        WHERE D.CD_ID = ''CM003''
    
        GROUP BY
            CAST(D.DTL_CD_ID AS VARCHAR)
    ),
    
    
    -- 8. 전체 기준월 생성 FROM_MT ~ TO_MT 까지 모든 월 생성 TO_MT 이하만 사용
    MONTH_DIM_BASE AS (
        SELECT
            TO_CHAR(
                DATEADD(
                    MONTH,
                    SEQ4(),
                    TO_DATE(:FROM_MT || ''01'', ''YYYYMMDD'')
                ),
                ''YYYYMM''
            ) AS STRD_MT
    
        FROM TABLE(
            GENERATOR(
                ROWCOUNT => 120
            )
        )
    ),
    MONTH_DIM AS (
        SELECT
            M.STRD_MT
    
        FROM MONTH_DIM_BASE AS M
    
        WHERE M.STRD_MT <= :TO_MT
    ),
    
    
    -- 최종 보고서 차원 생성
    -- 최종 DEPT_DIV_NM 후보
    REPORT_DEPT_DIM AS (
        SELECT DISTINCT
            CASE
                WHEN H.DEPT_DIV_NM IN (
                    ''회원실'',
                    ''나눔마케팅본부''
                )
                    THEN H.DEPT_DIV_NM
    
                WHEN D.DEPT_NM IN (
                    ''캠페인기획2팀'',
                    ''소셜펀딩부''
                )
                    THEN ''대면모금''
    
                ELSE H.DEPT_DIV_NM--''본부기타''
            END AS DEPT_DIV_NM
    
        FROM DEPT_DIM AS D
    
        LEFT JOIN DEPT_HIERARCHY AS H
            ON D.DEPT_ID = H.SOURCE_DEPT_ID
        WHERE H.UPPER_DEPT1_ID = ''ZA000001'' -- 사단 본부 대상
    ),
    -- 최종 신규/기존 후보
    REPORT_NEW_OLD_DIM AS (
        SELECT ''신규'' AS NEW_EXST_DIV_NM
        UNION ALL
        SELECT ''기존'' AS NEW_EXST_DIV_NM
    ),
    
    -- 최종 후원사업 후보 4개만 존재하도록 고정 1. 해외프로젝트 2. 국내 3. 결연 4. 기타
    REPORT_BSNS_DIM AS (
        SELECT ''해외프로젝트'' AS SPNSR_BSNS_GRP_NM
        UNION ALL
        SELECT ''국내''
        UNION ALL
        SELECT ''결연''
        UNION ALL
        SELECT ''기타''
    ),
    
    
    -- 최종 차원 전체 조합 실제 데이터에 존재하지 않는 조합도 생성
    REPORT_DIM AS (
        SELECT
            ''I'' AS CPR_DIV_CD,
            D.DEPT_DIV_NM,
            N.NEW_EXST_DIV_NM,
            B.SPNSR_BSNS_GRP_NM
    
        FROM REPORT_DEPT_DIM AS D
    
        CROSS JOIN REPORT_NEW_OLD_DIM AS N
    
        CROSS JOIN REPORT_BSNS_DIM AS B
    ),
    
    -- 기준월 × 최종 차원 전체 조합
    REPORT_GRID AS (
        SELECT
            M.STRD_MT,
            R.CPR_DIV_CD,
            R.DEPT_DIV_NM,
            R.NEW_EXST_DIV_NM,
            R.SPNSR_BSNS_GRP_NM
    
        FROM MONTH_DIM AS M
    
        CROSS JOIN REPORT_DIM AS R
    ),
    
    -- 10. 실제 데이터의 최종 차원별 집계
    REPORT_DIM_AGG AS (
        SELECT
            A.CPR_DIV_CD,
            CASE
                WHEN H.DEPT_DIV_NM IN (
                    ''회원실'',
                    ''나눔마케팅본부''
                )
                    THEN H.DEPT_DIV_NM
                WHEN D.DEPT_NM IN (
                    ''캠페인기획2팀'',
                    ''소셜펀딩부''
                )
                    THEN ''대면모금''
                ELSE H.DEPT_DIV_NM--''본부기타''
            END AS DEPT_DIV_NM,
            CASE A.NEW_OLD_DIV_CD
                WHEN ''1'' THEN ''신규''
                WHEN ''2'' THEN ''기존''
                ELSE ''없음''
            END AS NEW_EXST_DIV_NM,
            CASE
                WHEN B.SPNSR_BSNS_GRP_NM = ''해외구호''
                    THEN ''해외프로젝트''
    
                WHEN B.SPNSR_BSNS_GRP_NM = ''국내''
                    OR B.SPNSR_BSNS_GRP_NM = ''결연''
                    THEN B.SPNSR_BSNS_GRP_NM
    
                ELSE ''기타''
            END AS SPNSR_BSNS_GRP_NM,
    
            A.STRD_MT,
    
            SUM(A.WJXBFS1) AS VALUE
    
        FROM REPORT_AGG AS A
    
        /* 현재 부서명 */
        LEFT JOIN DEPT_DIM AS D
            ON A.DEPT_ID = D.DEPT_ID
    
        /* 실적부서 → 상위 조직 */
        LEFT JOIN DEPT_HIERARCHY AS H
            ON A.DEPT_ID = H.SOURCE_DEPT_ID
    
        /* 법인 */
        LEFT JOIN CPR_DIM AS C
            ON A.CPR_DIV_CD = C.CPR_DIV_CD
    
        /* 후원사업 */
        LEFT JOIN ABRV_DIM AS B
            ON A.SPNSR_BSNS_ABRV_CD = B.SPNSR_BSNS_ABRV_CD
    
        WHERE A.CPR_DIV_CD = ''I''
    
        GROUP BY
            A.CPR_DIV_CD,
    
            CASE
                WHEN H.DEPT_DIV_NM IN (
                    ''회원실'',
                    ''나눔마케팅본부''
                )
                    THEN H.DEPT_DIV_NM
    
                WHEN D.DEPT_NM IN (
                    ''캠페인기획2팀'',
                    ''소셜펀딩부''
                )
                    THEN ''대면모금''
    
                ELSE H.DEPT_DIV_NM--''본부기타''
            END,
    
            CASE A.NEW_OLD_DIV_CD
                WHEN ''1'' THEN ''신규''
                WHEN ''2'' THEN ''기존''
                ELSE ''없음''
            END,
    
            CASE
                WHEN B.SPNSR_BSNS_GRP_NM = ''해외구호''
                    THEN ''해외프로젝트''
    
                WHEN B.SPNSR_BSNS_GRP_NM = ''국내''
                    OR B.SPNSR_BSNS_GRP_NM = ''결연''
                    THEN B.SPNSR_BSNS_GRP_NM
    
                ELSE ''기타''
            END,
    
            A.STRD_MT
    ),
    -- 11. FINAL REPORT_GRID를 기준으로 LEFT JOIN 실제 실적이 없는 조합은 VALUE = NULL
    RESULT AS (
        SELECT
            ''실적'' AS DATA_TYPE_NM,
            LEFT(G.STRD_MT, 4) AS YEAR,
            CASE 
                WHEN G.DEPT_DIV_NM = ''회원실'' or G.DEPT_DIV_NM = ''나눔마케팅본부'' or G.DEPT_DIV_NM = ''대면모금'' THEN G.DEPT_DIV_NM
                ELSE ''기타''
            END DEPT_DIV_NM,
        
            G.NEW_EXST_DIV_NM,
        
            G.SPNSR_BSNS_GRP_NM,
        
            SUM(A.VALUE) AS VALUE
        
        FROM REPORT_GRID AS G
        LEFT JOIN REPORT_DIM_AGG AS A
            ON A.CPR_DIV_CD          = G.CPR_DIV_CD
           AND A.DEPT_DIV_NM      = G.DEPT_DIV_NM
           AND A.NEW_EXST_DIV_NM      = G.NEW_EXST_DIV_NM
           AND A.SPNSR_BSNS_GRP_NM  = G.SPNSR_BSNS_GRP_NM
           AND A.STRD_MT             = G.STRD_MT
        WHERE G.STRD_MT = :FROM_MT   
        GROUP BY 
            G.STRD_MT,
            CASE 
                WHEN G.DEPT_DIV_NM = ''회원실'' or G.DEPT_DIV_NM = ''나눔마케팅본부'' or G.DEPT_DIV_NM = ''대면모금'' THEN G.DEPT_DIV_NM
                ELSE ''기타''
            END,
            G.NEW_EXST_DIV_NM,
            G.SPNSR_BSNS_GRP_NM
        ORDER BY
            CASE 
                WHEN G.DEPT_DIV_NM = ''회원실'' or G.DEPT_DIV_NM = ''나눔마케팅본부'' or G.DEPT_DIV_NM = ''대면모금'' THEN G.DEPT_DIV_NM
                ELSE ''기타''
            END,
            G.NEW_EXST_DIV_NM,
            G.SPNSR_BSNS_GRP_NM,
            G.STRD_MT
    ) 
    SELECT * FROM RESULT;
    SET UPDATE_SQL := 
        ''UPDATE GN_DW.SILVER.ANNUAL_DVLP_GOAL_ACMSLT_AGGR_DATA AS T
         SET M'' || RIGHT(:FROM_MT, 2) || '' = COALESCE(R.VALUE, 0)
         FROM (
             SELECT
                 T2.DATA_TYPE_NM,
                 T2.YEAR,
                 T2.DEPT_DIV_NM,
                 T2.NEW_EXST_DIV_NM,
                 T2.SPNSR_BSNS_GRP_NM,
                 R.VALUE
             FROM GN_DW.SILVER.ANNUAL_DVLP_GOAL_ACMSLT_AGGR_DATA T2
             LEFT JOIN GN_DW.SILVER.RESULT_TEMP R
                 ON T2.DATA_TYPE_NM = R.DATA_TYPE_NM
                AND T2.YEAR = R.YEAR
                AND T2.DEPT_DIV_NM = R.DEPT_DIV_NM
                AND T2.NEW_EXST_DIV_NM = R.NEW_EXST_DIV_NM
                AND T2.SPNSR_BSNS_GRP_NM = R.SPNSR_BSNS_GRP_NM
             WHERE T2.DATA_TYPE_NM = ''''실적''''
         ) R
         WHERE T.DATA_TYPE_NM = R.DATA_TYPE_NM
           AND T.YEAR = R.YEAR
           AND T.DEPT_DIV_NM = R.DEPT_DIV_NM
           AND T.NEW_EXST_DIV_NM = R.NEW_EXST_DIV_NM
           AND T.SPNSR_BSNS_GRP_NM = R.SPNSR_BSNS_GRP_NM
           AND T.DEPT_DIV_NM NOT IN (''''교육기관'''', ''''지역사회'''')'';
    EXECUTE IMMEDIATE :UPDATE_SQL;
    RETURN ''SUCCESS: '' || :FROM_MT;
END;
';
CREATE OR REPLACE PROCEDURE GN_DW.SILVER.SP_ANNUAL_DVLP_GOAL_ACMSLT_AGGR_DATA2("INPUT_YYYYMM" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS CALLER
AS '
DECLARE
    FROM_MT VARCHAR;
    TO_MT VARCHAR;
    START_DE VARCHAR;
    NEXT_DE VARCHAR;
    UPDATE_SQL VARCHAR;
BEGIN
    -- 0. 파라미터
    IF (NOT REGEXP_LIKE(input_yyyymm, ''^[0-9]{6}$'')) THEN
        RETURN ''ERROR: input_yyyymm은 YYYYMM 형식이어야 합니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'') IS NULL) THEN
        RETURN ''ERROR: 유효하지 않은 년월입니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (
        TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'')
        > DATE_TRUNC(''MONTH'', CURRENT_DATE())
    ) THEN
        RETURN ''ERROR: 미래 년월은 입력할 수 없습니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
   
    FROM_MT := input_yyyymm;
    TO_MT := FROM_MT;
    START_DE := FROM_MT || ''01'';
    NEXT_DE := TO_CHAR(
        DATEADD(MONTH,1,TO_DATE(TO_MT || ''01'', ''YYYYMMDD'')),''YYYYMMDD''
    );

    -- 1. CTE
    CREATE OR REPLACE TEMPORARY TABLE GN_DW.SILVER.RESULT_TEMP AS
    WITH 
    -- 1-1. 대상 부서
    TARGET_DEPT AS
    (
        SELECT COLUMN1::VARCHAR AS DEPT_ID
        FROM VALUES
            (''D000116''),
            (''D000117''),
            (''D000118''),
            (''D000119''),
            (''D000120''),
            (''D000121''),
            (''D000123''),
            (''D000126''),
            (''D000139''),
            (''D000140''),
            (''E000029''),
            (''E000042''),
            (''E000117''),
            (''E001104''),
            (''E001105''),
            (''F001009''),
            (''E000067''),
            (''E000002'')
    ),
    
    -- 1-2. 조회기간 개발 원천
    DVLP_SOURCE AS
    (
        SELECT
            LEFT(A.OCCRRNC_DE, 6) AS STRD_MT,
            A.OCCRRNC_DE,
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.SER_NO,
            A.MBER_NO,
            A.ACMSLT_DEPT_CD,
            A.CMPGN_CD,
            A.SPNSR_BSNS_ID,
            A.DVLP_DIV_CD,
            A.SPNSR_AMT::NUMBER(28, 4) AS SPNSR_AMT
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_DVLP_AMT AS A
        WHERE A.OCCRRNC_DE >= :START_DE
          AND A.OCCRRNC_DE <  :NEXT_DE
          AND A.DVLP_DIV_CD IN (''1'', ''2'', ''3'', ''4'', ''5'')
    ),
    
    -- 1-3. 신규·재후원 대상 후원번호/후원사업
    RELEVANT_SPNSR_BSNS AS
    (
        SELECT DISTINCT
            S.SPNSR_NO,
            S.SPNSR_BSNS_NO
        FROM DVLP_SOURCE AS S
        WHERE S.DVLP_DIV_CD IN (''1'', ''4'')
    ),
    
    -- 1-4. 후원사업 기간
    SPNSR_BSNS_PERIOD AS
    (
        SELECT
            S.SPNSR_NO,
            B.SPNSR_BSNS_NO,
            COALESCE(B.SPNSR_DSCNTC_DE, ''99991231'') AS DSC_DE
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR AS S
        INNER JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR_BSNS AS B
            ON S.SPNSR_NO = B.SPNSR_NO
        INNER JOIN RELEVANT_SPNSR_BSNS AS K
            ON B.SPNSR_NO      = K.SPNSR_NO
           AND B.SPNSR_BSNS_NO = K.SPNSR_BSNS_NO
    ),
    
    -- 2. 신규(1)·재후원(4)    
    NEW_RE_BASE AS
    (
        SELECT
            D.STRD_MT,
            D.OCCRRNC_DE,
            D.SPNSR_NO,
            D.SPNSR_BSNS_NO,
            D.SER_NO,
            D.MBER_NO,
            D.ACMSLT_DEPT_CD,
            D.CMPGN_CD,
            D.SPNSR_BSNS_ID,
            D.DVLP_DIV_CD,
            D.SPNSR_AMT,
    
            SUM(D.SPNSR_AMT) OVER
            (
                PARTITION BY
                    D.SPNSR_NO,
                    D.SPNSR_BSNS_NO,
                    D.STRD_MT
            ) AS MAMT
    
        FROM DVLP_SOURCE AS D
    
        INNER JOIN SPNSR_BSNS_PERIOD AS P
            ON D.SPNSR_NO      = P.SPNSR_NO
           AND D.SPNSR_BSNS_NO = P.SPNSR_BSNS_NO
           AND P.DSC_DE > D.STRD_MT || ''31''
    
        WHERE D.DVLP_DIV_CD IN (''1'', ''4'')
    ),
    
    -- 2-1. 개발 이벤트 변환 결과
    NEW_RE_TRANSFORMED AS
    (
        SELECT
            N.STRD_MT,
            N.OCCRRNC_DE,
            N.SPNSR_NO,
            N.SPNSR_BSNS_NO,
            N.SER_NO,
            N.MBER_NO,
            COALESCE(N.ACMSLT_DEPT_CD, ''Z~'') AS ACMSLT_DEPT_CD,
            N.CMPGN_CD,
            N.SPNSR_BSNS_ID,
            N.DVLP_DIV_CD,
            N.SPNSR_AMT
        FROM NEW_RE_BASE AS N
        WHERE N.MAMT > 0
    ),
    
    -- 3. 증액(2)    
    INCREASE_BASE AS
    (
        SELECT
            D.STRD_MT,
            D.OCCRRNC_DE,
            D.SPNSR_NO,
            D.SPNSR_BSNS_NO,
            D.SER_NO,
            D.MBER_NO,
            D.ACMSLT_DEPT_CD,
            D.CMPGN_CD,
            D.SPNSR_BSNS_ID,
            D.DVLP_DIV_CD,
            D.SPNSR_AMT,
    
            SUM
            (
                CASE
                    WHEN D.DVLP_DIV_CD IN (''2'', ''3'')
                        THEN D.SPNSR_AMT
                    ELSE 0::NUMBER(28,4)
                END
            ) OVER
            (
                PARTITION BY
                    D.SPNSR_NO,
                    D.SPNSR_BSNS_NO,
                    D.STRD_MT
            ) AS SAMT,
    
            SUM(D.SPNSR_AMT) OVER
            (
                PARTITION BY
                    D.MBER_NO,
                    D.STRD_MT
            ) AS MAMT
    
        FROM DVLP_SOURCE AS D
    
        WHERE D.DVLP_DIV_CD IN (''2'', ''3'', ''5'')
    ),
    
    -- 3-2. 증액/감액 유효 행 필터
    INCREASE_FILTERED_BASE AS
    (
        SELECT
            I.*,
    
            SUM
            (
                CASE
                    WHEN I.DVLP_DIV_CD = ''3''
                        THEN I.SPNSR_AMT
                    ELSE 0::NUMBER(28,4)
                END
            ) OVER
            (
                PARTITION BY
                    I.MBER_NO,
                    I.STRD_MT
            ) AS DAMT
    
        FROM INCREASE_BASE AS I
    
        WHERE I.MAMT > 0
    
          AND
          (
               (
                    I.SAMT > 0
                AND I.DVLP_DIV_CD = ''2''
               )
            OR (
                    I.SAMT < 0
                AND I.DVLP_DIV_CD = ''3''
               )
          )
    ),
    
    -- 3-3. 증액(2)만 추출하면서 회원·월별 증액 누계 계산
    INCREASE_ONLY2 AS
    (
        SELECT
            I.*,
    
            SUM(I.SAMT) OVER
            (
                PARTITION BY
                    I.MBER_NO,
                    I.STRD_MT
                ORDER BY
                    I.OCCRRNC_DE,
                    I.SER_NO
                ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
            ) AS AAMT
    
        FROM INCREASE_FILTERED_BASE AS I
    
        WHERE I.DVLP_DIV_CD = ''2''
    ),
    
    -- 3-4. 증액 인정금액 RAMT 계산
    INCREASE_RANKED_BASE AS
    (
        SELECT
            I.STRD_MT,
            I.OCCRRNC_DE,
            I.SPNSR_NO,
            I.SPNSR_BSNS_NO,
            I.SER_NO,
            I.MBER_NO,
            I.ACMSLT_DEPT_CD,
            I.CMPGN_CD,
            I.SPNSR_BSNS_ID,
    
            ROW_NUMBER() OVER
            (
                PARTITION BY
                    I.STRD_MT,
                    I.SPNSR_NO,
                    I.SPNSR_BSNS_NO
                ORDER BY
                    I.SER_NO
            ) AS RNUM,
    
            CASE
    
                WHEN I.MAMT <= I.SAMT
                 AND I.AAMT + I.DAMT <= I.MAMT
                    THEN I.AAMT + I.DAMT
    
                WHEN I.MAMT > I.SAMT
                 AND I.AAMT + I.DAMT <= I.SAMT
                    THEN I.AAMT + I.DAMT
    
                WHEN I.MAMT <= I.SAMT
                    THEN I.MAMT
    
                ELSE I.SAMT
    
            END AS RAMT
    
        FROM INCREASE_ONLY2 AS I
    
        WHERE I.AAMT - ABS(I.DAMT) > 0
    ),
    
    -- 3-5. 최종 증액 인정 행
    INCREASE_TRANSFORMED AS
    (
        SELECT
            I.STRD_MT,
            I.OCCRRNC_DE,
            I.SPNSR_NO,
            I.SPNSR_BSNS_NO,
            I.SER_NO,
            I.MBER_NO,
            COALESCE(I.ACMSLT_DEPT_CD, ''Z~'') AS ACMSLT_DEPT_CD,
            I.CMPGN_CD,
            I.SPNSR_BSNS_ID,
            ''2'' AS DVLP_DIV_CD,
            I.RAMT::NUMBER(28,4) AS SPNSR_AMT
    
        FROM INCREASE_RANKED_BASE AS I
    
        WHERE I.RNUM = 1
    ),
    
    -- 4. 신규/재후원 + 증액 개발 이벤트 통합
    TRANSFORMED_DVLP AS
    (
        SELECT
            STRD_MT,
            OCCRRNC_DE,
            SPNSR_NO,
            SPNSR_BSNS_NO,
            SER_NO,
            MBER_NO,
            ACMSLT_DEPT_CD,
            CMPGN_CD,
            SPNSR_BSNS_ID,
            DVLP_DIV_CD,
            SPNSR_AMT
        FROM NEW_RE_TRANSFORMED
    
        UNION ALL
    
        SELECT
            STRD_MT,
            OCCRRNC_DE,
            SPNSR_NO,
            SPNSR_BSNS_NO,
            SER_NO,
            MBER_NO,
            ACMSLT_DEPT_CD,
            CMPGN_CD,
            SPNSR_BSNS_ID,
            DVLP_DIV_CD,
            SPNSR_AMT
        FROM INCREASE_TRANSFORMED
    ),
    
    -- 5. 후원사업 차원
    BUSINESS_DIM AS
    (
        SELECT
            B.SPNSR_BSNS_ID::VARCHAR AS SPNSR_BSNS_ID,
    
            COALESCE(
                B.SPNSR_BSNS_ABRV_CD::VARCHAR,
                ''0''
            ) AS SPNSR_BSNS_ABRV_CD,
    
            CASE B.CPR_DIV_CD::VARCHAR
                WHEN ''1'' THEN ''I''
                WHEN ''2'' THEN ''S''
                ELSE COALESCE(B.CPR_DIV_CD::VARCHAR, ''0'')
            END AS CPR_DIV_CD
    
        FROM GN_DW.BRONZE_CRM.TM_CM_SPNSR_BSNS_INFO AS B
    ),
    
    -- 6. 캠페인 차원
    CAMPAIGN_DIM AS
    (
        SELECT
            C.CMPGN_CD::VARCHAR AS CMPGN_CD,
    
            COALESCE(
                C.UPPER_CMPGN_CD::VARCHAR,
                ''Z~''
            ) AS UPPER_CMPGN_CD
    
        FROM GN_DW.BRONZE_CRM.TM_CM_CMPGN_MNG AS C
    ),
    
    -- 7. F_MM_SPNSR_DVLP_SUM 보고서 사용 컬럼 재현
    REPORT_FACT AS
    (
        SELECT
            T.STRD_MT,
    
            COALESCE(
                B.CPR_DIV_CD,
                ''0''
            ) AS CPR_DIV_CD,
    
            COALESCE(
                T.ACMSLT_DEPT_CD,
                ''Z~''
            ) AS ACMSLT_DEPT_CD,
    
            COALESCE(
                C.UPPER_CMPGN_CD,
                ''Z~''
            ) AS UPPER_CMPGN_CD,
    
            CASE
                WHEN LEFT(T.OCCRRNC_DE, 4)
                   = YEAR(M.FRST_REGIST_DT)::VARCHAR
                    THEN ''1''
                ELSE ''2''
            END AS NEW_OLD_DIV_CD,
    
            COALESCE(
                B.SPNSR_BSNS_ABRV_CD,
                ''0''
            ) AS SPNSR_BSNS_ABRV_CD,
    
            T.DVLP_DIV_CD,
    
            (
                T.SPNSR_AMT::NUMBER(28,4)
                / 10000.0
            )::NUMBER(38,10) AS SPNSR_AMT_CNT
    
        FROM TRANSFORMED_DVLP AS T
    
        LEFT JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_INFO AS M
            ON T.MBER_NO = M.MBER_NO
    
        LEFT JOIN BUSINESS_DIM AS B
            ON T.SPNSR_BSNS_ID::VARCHAR = B.SPNSR_BSNS_ID
    
        LEFT JOIN CAMPAIGN_DIM AS C
            ON T.CMPGN_CD::VARCHAR = C.CMPGN_CD
    
        WHERE T.DVLP_DIV_CD IN (''1'', ''2'', ''4'')
    ),
    
    -- 8. 최종 집계   
    REPORT_AGG AS
    (
        SELECT
            F.ACMSLT_DEPT_CD AS DEPT_ID,
            F.STRD_MT,
            F.UPPER_CMPGN_CD,
            F.NEW_OLD_DIV_CD,
            F.SPNSR_BSNS_ABRV_CD,
            F.CPR_DIV_CD,
    
            SUM(F.SPNSR_AMT_CNT) AS WJXBFS1
    
        FROM REPORT_FACT AS F
    
        INNER JOIN TARGET_DEPT AS T
            ON F.ACMSLT_DEPT_CD = T.DEPT_ID
    
        WHERE F.STRD_MT >= :FROM_MT
          AND F.STRD_MT <= :TO_MT
          AND F.DVLP_DIV_CD IN (''1'', ''2'', ''4'')
    
        GROUP BY
            F.ACMSLT_DEPT_CD,
            F.STRD_MT,
            F.UPPER_CMPGN_CD,
            F.NEW_OLD_DIV_CD,
            F.SPNSR_BSNS_ABRV_CD,
            F.CPR_DIV_CD
    ),
    
    -- 9. 표시용 차원
    DEPT_DIM AS
    (
        SELECT
            D.DEPT_ID::VARCHAR AS DEPT_ID,
            MAX(D.DEPT_NM) AS DEPT_NM
    
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO AS D
    
        GROUP BY
            D.DEPT_ID::VARCHAR
    ),
    
    -- 9-1. 조직계층 원천 (SOURCE_DEPT_ID = REPORT_AGG.DEPT_ID)
    DEPT_HIERARCHY_BASE AS
    (
        SELECT
            E.DEPT_ID::VARCHAR AS SOURCE_DEPT_ID,
    
            B.DEPT_ID::VARCHAR AS DEPT4_ID,
            B.DEPT_NM AS DEPT4_NM,
    
            A.DEPT_ID::VARCHAR AS UPPER_DEPT1_ID,
            A.DEPT_NM AS UPPER_DEPT1_NM,
    
            C.DEPT_ID::VARCHAR AS UPPER_DEPT2_ID,
            C.DEPT_NM AS UPPER_DEPT2_NM,
    
            D.DEPT_ID::VARCHAR AS UPPER_DEPT3_ID,
            D.DEPT_NM AS UPPER_DEPT3_NM
    
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO AS A
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO AS B
            ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO AS C
            ON C.ACMSLT_UPPER_DEPT_ID = B.DEPT_ID
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO AS D
            ON D.ACMSLT_UPPER_DEPT_ID = C.DEPT_ID
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO AS E
            ON E.ACMSLT_UPPER_DEPT_ID = D.DEPT_ID
    
        WHERE A.UPPER_DEPT_ID = ''ZV000000''
          AND C.DEPT_ID <> ''ZC000029''
    ),
    
    -- 9-2. 조직계층 1 DEPT_ID = 1 ROW 보장
    DEPT_HIERARCHY AS
    (
        SELECT
            SOURCE_DEPT_ID,
    
            MAX(DEPT4_ID) AS DEPT4_ID,
            MAX(DEPT4_NM) AS DEPT4_NM,
    
            MAX(UPPER_DEPT1_ID) AS UPPER_DEPT1_ID,
            MAX(UPPER_DEPT1_NM) AS UPPER_DEPT1_NM,
    
            MAX(UPPER_DEPT2_ID) AS UPPER_DEPT2_ID,
            MAX(UPPER_DEPT2_NM) AS UPPER_DEPT2_NM,
    
            MAX(UPPER_DEPT3_ID) AS UPPER_DEPT3_ID,
            MAX(UPPER_DEPT3_NM) AS UPPER_DEPT3_NM
    
        FROM DEPT_HIERARCHY_BASE
    
        GROUP BY
            SOURCE_DEPT_ID
    ),
    
    --9-3. 상위 캠페인명
    UPPER_CMPGN_BASE AS
    (
        SELECT
            U.CMPGN_CD::VARCHAR AS UPPER_CMPGN_CD,
            MAX(U.CMPGN_NM) AS UPPER_CMPGN_NM
    
        FROM GN_DW.BRONZE_CRM.TM_CM_CMPGN_MNG AS U
    
        GROUP BY
            U.CMPGN_CD::VARCHAR
    ),
    
    -- 9-4. 상위 캠페인 표시 순번
    UPPER_CMPGN_DIM AS
    (
        SELECT
            U.UPPER_CMPGN_CD,
            U.UPPER_CMPGN_NM,
    
            DENSE_RANK() OVER
            (
                ORDER BY
                    CASE
                        WHEN U.UPPER_CMPGN_CD = ''Z~''
                            THEN 1
                        ELSE 0
                    END,
    
                    CASE
                        WHEN TRY_TO_NUMBER(U.UPPER_CMPGN_CD) IS NULL
                            THEN 1
                        ELSE 0
                    END,
    
                    TRY_TO_NUMBER(U.UPPER_CMPGN_CD),
    
                    U.UPPER_CMPGN_CD
            ) AS SORT_ORDR
    
        FROM UPPER_CMPGN_BASE AS U
    ),
    
    -- 9-5. 법인구분
    CPR_DIM AS
    (
        SELECT
            D.DTL_CD_ID::VARCHAR AS CPR_DIV_CD,
            MAX(D.DTL_CD_NM) AS CPR_DIV_NM
        FROM 
            GN_DW.BRONZE_CRM.TC_CMMN_DTL_CD AS D
        WHERE D.CD_ID = ''CM019''
        GROUP BY
            D.DTL_CD_ID::VARCHAR
    ),
    
    -- 9-6. 후원사업 약칭
    ABRV_DIM AS
    (
        SELECT
            D.DTL_CD_ID::VARCHAR AS SPNSR_BSNS_ABRV_CD,
            MAX(D.DTL_CD_NM) AS SPNSR_BSNS_GRP_NM
        FROM 
            GN_DW.BRONZE_CRM.TC_CMMN_DTL_CD AS D
        WHERE 
            D.CD_ID = ''CM003''
        GROUP BY
            D.DTL_CD_ID::VARCHAR
    ),
    -- 10. 최종 출력
    RESULT AS (
        SELECT
            ''실적'' AS DATA_TYPE_NM,
            LEFT(A.STRD_MT, 4) AS YEAR, 
            CASE 
                WHEN A.UPPER_CMPGN_CD IN (
                    ''U1255'', ''U1256'', ''U1257'', ''U1197'', ''U1198'',
                    ''U1199'', ''U1261''
                ) THEN ''교육기관''
                WHEN A.UPPER_CMPGN_CD IN (
                    ''U0892'', ''U0897'', ''U1105'', ''U1106'', ''U1107'',
                    ''U1204'', ''U1263'', ''U1208'', ''U1104'', ''U0243'',
                    ''U1265'', ''U1287'', ''U0893''
                ) THEN ''지역사회''
                ELSE A.UPPER_CMPGN_CD
            END AS DEPT_DIV_NM,
            CASE A.NEW_OLD_DIV_CD
                WHEN ''1'' THEN ''신규''
                WHEN ''2'' THEN ''기존''
                ELSE ''없음''
            END AS NEW_EXST_DIV_NM,
            CASE
                WHEN B.SPNSR_BSNS_GRP_NM = ''해외구호''
                    THEN ''해외프로젝트''
                WHEN B.SPNSR_BSNS_GRP_NM = ''국내'' OR B.SPNSR_BSNS_GRP_NM = ''결연''
                    THEN B.SPNSR_BSNS_GRP_NM
                ELSE ''기타''
            END AS SPNSR_BSNS_GRP_NM,
            SUM(A.WJXBFS1) AS VALUE
        FROM REPORT_AGG AS A
            LEFT JOIN DEPT_DIM AS D ON A.DEPT_ID = D.DEPT_ID
            LEFT JOIN DEPT_HIERARCHY AS H ON A.DEPT_ID = H.SOURCE_DEPT_ID
            LEFT JOIN UPPER_CMPGN_DIM AS U ON A.UPPER_CMPGN_CD = U.UPPER_CMPGN_CD
            LEFT JOIN ABRV_DIM AS B ON A.SPNSR_BSNS_ABRV_CD = B.SPNSR_BSNS_ABRV_CD
            LEFT JOIN CPR_DIM AS C ON A.CPR_DIV_CD = C.CPR_DIV_CD
        WHERE 
            A.CPR_DIV_CD = ''I''
        GROUP BY 
            A.STRD_MT,
            CASE 
                WHEN A.UPPER_CMPGN_CD IN (
                    ''U1255'', ''U1256'', ''U1257'', ''U1197'', ''U1198'',
                    ''U1199'', ''U1261''
                ) THEN ''교육기관''
                WHEN A.UPPER_CMPGN_CD IN (
                    ''U0892'', ''U0897'', ''U1105'', ''U1106'', ''U1107'',
                    ''U1204'', ''U1263'', ''U1208'', ''U1104'', ''U0243'',
                    ''U1265'', ''U1287'', ''U0893''
                ) THEN ''지역사회''
                ELSE A.UPPER_CMPGN_CD
            END,
            CASE A.NEW_OLD_DIV_CD
                WHEN ''1'' THEN ''신규''
                WHEN ''2'' THEN ''기존''
                ELSE ''없음''
            END,
        
            CASE
                WHEN B.SPNSR_BSNS_GRP_NM = ''해외구호''
                    THEN ''해외프로젝트''
                WHEN B.SPNSR_BSNS_GRP_NM = ''국내'' OR B.SPNSR_BSNS_GRP_NM = ''결연''
                    THEN B.SPNSR_BSNS_GRP_NM
                ELSE ''기타''
            END
        ORDER BY
            CASE 
                WHEN A.UPPER_CMPGN_CD IN (
                    ''U1255'', ''U1256'', ''U1257'', ''U1197'', ''U1198'',
                    ''U1199'', ''U1261'' 
                ) THEN ''교육기관''
                WHEN A.UPPER_CMPGN_CD IN (
                    ''U0892'', ''U0897'', ''U1105'', ''U1106'', ''U1107'',
                    ''U1204'', ''U1263'', ''U1208'', ''U1104'', ''U0243'',
                    ''U1265'',  ''U1287'', ''U0893''
                ) THEN ''지역사회''
                ELSE A.UPPER_CMPGN_CD
            END,
            CASE A.NEW_OLD_DIV_CD
                WHEN ''1'' THEN ''신규''
                WHEN ''2'' THEN ''기존''
                ELSE ''없음''
            END,
            CASE
                WHEN B.SPNSR_BSNS_GRP_NM = ''해외구호'' 
                    THEN ''해외프로젝트''
                WHEN B.SPNSR_BSNS_GRP_NM = ''국내'' OR B.SPNSR_BSNS_GRP_NM = ''결연'' 
                    THEN B.SPNSR_BSNS_GRP_NM
                ELSE ''기타''
            END,
        A.STRD_MT
    ) 
    SELECT * FROM RESULT;
    UPDATE_SQL := 
        ''UPDATE GN_DW.SILVER.ANNUAL_DVLP_GOAL_ACMSLT_AGGR_DATA AS T
         SET M'' || RIGHT(:FROM_MT, 2) || '' = COALESCE(R.VALUE, 0)
         FROM (
             SELECT
                 T2.DATA_TYPE_NM,
                 T2.YEAR,
                 T2.DEPT_DIV_NM,
                 T2.NEW_EXST_DIV_NM,
                 T2.SPNSR_BSNS_GRP_NM,
                 R.VALUE
             FROM GN_DW.SILVER.ANNUAL_DVLP_GOAL_ACMSLT_AGGR_DATA T2
             LEFT JOIN GN_DW.SILVER.RESULT_TEMP R
                 ON T2.DATA_TYPE_NM = R.DATA_TYPE_NM
                AND T2.YEAR = R.YEAR
                AND T2.DEPT_DIV_NM = R.DEPT_DIV_NM
                AND T2.NEW_EXST_DIV_NM = R.NEW_EXST_DIV_NM
                AND T2.SPNSR_BSNS_GRP_NM = R.SPNSR_BSNS_GRP_NM
             WHERE T2.DATA_TYPE_NM = ''''실적''''
         ) R
         WHERE T.DATA_TYPE_NM = R.DATA_TYPE_NM
           AND T.YEAR = R.YEAR
           AND T.DEPT_DIV_NM = R.DEPT_DIV_NM
           AND T.NEW_EXST_DIV_NM = R.NEW_EXST_DIV_NM
           AND T.SPNSR_BSNS_GRP_NM = R.SPNSR_BSNS_GRP_NM
           AND T.DEPT_DIV_NM IN (''''교육기관'''', ''''지역사회'''')'';
    EXECUTE IMMEDIATE :UPDATE_SQL;
    RETURN ''SUCCESS: '' || :FROM_MT;
END;
';
CREATE OR REPLACE PROCEDURE GN_DW.SILVER.SP_INSERT_ANNUAL_MBRFEE_PRDT_ACTL_DATA("INPUT_YYYYMM" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS CALLER
AS '
DECLARE
    STDR_MT VARCHAR;
    BEFORE_MT VARCHAR;
BEGIN
    -- 0. 파라미터
    IF (NOT REGEXP_LIKE(input_yyyymm, ''^[0-9]{6}$'')) THEN
        RETURN ''ERROR: input_yyyymm은 YYYYMM 형식이어야 합니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'') IS NULL) THEN
        RETURN ''ERROR: 유효하지 않은 년월입니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (
        TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'')
        > DATE_TRUNC(''MONTH'', CURRENT_DATE())
    ) THEN
        RETURN ''ERROR: 미래 년월은 입력할 수 없습니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    STDR_MT := input_yyyymm;
    BEFORE_MT := 
        TO_CHAR(
           DATEADD(MONTH, -1, TO_DATE(:STDR_MT, ''YYYYMM'')),
           ''YYYYMM''
        );
    DELETE 
    FROM GN_DW.SILVER.ANNUAL_MBRFEE_PRDT_ACTL_DATA
    WHERE DATA_TYPE_NM = ''실측''
        AND STDR_MT = :STDR_MT; 
    
    INSERT INTO GN_DW.SILVER.ANNUAL_MBRFEE_PRDT_ACTL_DATA
    WITH BASE AS (
        SELECT
            STDR_MT,
            SPNSR_BSNS_GRP_NM,
            NEW_EXST_DIV_NM,
            CASE
                WHEN NEW_EXST_DIV_NM = ''신규'' THEN HDQ_BRNCH_GRP_NM
                ELSE ''기존''
            END AS HDQ_BRNCH_GRP_NM,
            /* 개발 */
            SUM(CASE
                WHEN AGGR_TY_NM = ''개발''
                THEN VALUE1 ELSE 0
            END) AS DVLP_CNT,
    
            /* 중단 */
            SUM(CASE
                WHEN AGGR_TY_NM = ''중단''
                THEN VALUE1 ELSE 0
            END) AS ADJ_DSCNTC_CNT,
    
            /* 감액 */
            SUM(CASE
                WHEN AGGR_TY_NM = ''감액''
                THEN VALUE1 ELSE 0
            END) AS ADJ_RDCAMT_CNT,
    
            /* 활동 */
            SUM(CASE
                WHEN AGGR_TY_NM = ''활동''
                THEN VALUE1 ELSE 0
            END) AS CMLT_EOM_ACT_MBER_CNT,
    
            /* 회비 */
            SUM(CASE
                WHEN AGGR_TY_NM = ''회비''
                THEN VALUE1 ELSE 0
            END) AS ADJ_MBRFEE_AMT,
    
            /* 누계회비 */
            SUM(CASE
                WHEN AGGR_TY_NM = ''회비''
                THEN VALUE2 ELSE 0
            END) AS ADJ_CMLT_MBRFEE_AMT
        FROM GN_DW.SILVER.MM_SPNSR_CLS_AGGR_DATA
        WHERE STDR_MT = :STDR_MT
        GROUP BY
            STDR_MT,
            SPNSR_BSNS_GRP_NM,
            NEW_EXST_DIV_NM,
            CASE
                WHEN NEW_EXST_DIV_NM = ''신규'' THEN HDQ_BRNCH_GRP_NM
                ELSE ''기존''
            END
    )
        -- A는 예측치. 후원사업별로 4행씩 존재. 신규본부 / 신규지부 / 신규본부지부 / 기존통합 
        -- SCAD는 CRM데이터 기반 집계값. 후원사업별로 3행씩 존재. 신규본부 / 신규지부 / 기존기존
        -- 실측은 실측치 그대로 사용
        -- BF는 이전달 실측치
        -- 예측은 예측치 그대로 사용
        -- 계산은 계산식 필요
        -- 기준월까지는 해당 월의 예측치 명칭 사용
        SELECT 
            ''실측'' AS "생성용 예측 실측 구분 명",
            A.SPNSR_BSNS_GRP_NM AS "후원 사업 그룹 명",
            A.NEW_EXST_DIV_NM AS "신규기존구분명",
            A.HDQ_BRNCH_GRP_NM AS "본부 지부 그룹 명",
            A.STDR_MT AS "기준월",
            SCAD.DVLP_CNT AS "개발(월)", --실측. 기존 값이 다름....왜?
            CASE
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN SCAD.DVLP_CNT
                ELSE BF.CMLT_DVLP_CNT + SCAD.DVLP_CNT
            END AS "개발(누적)", --계산 1월은 실측 DVLP_CNT // 타월은 이전달 CMLT_DVLP_CNT + 실측 DVLP_CNT
            A.ADJ_DSCNTC_RT AS "중단율(월)", --예측 ADJ_DSCNTC_RT
            SCAD.ADJ_DSCNTC_CNT AS "중단건수(월)", --실측 ADJ_DSCNTC_CNT
            A.ADJ_RDCAMT_RT AS "감액율(월)", -- 예측 ADJ_DSCNTC_RT
            CASE
                WHEN SCAD.HDQ_BRNCH_GRP_NM != ''기존'' AND RIGHT(:STDR_MT, 2) = ''01'' THEN A.ADJ_DSCNTC_RT * SCAD.DVLP_CNT
                ELSE SCAD.ADJ_RDCAMT_CNT
            END AS "감액건수(월)", --1월은 예측 ADJ_DSCNTC_RT * 실측 .DVLP_CNT / 타월은 실측 ADJ_RDCAMT_CNT. 기존의 경우 실측값 그대로 사용...기존 감액건수 왜 차이남?
            CASE
                WHEN A.NEW_EXST_DIV_NM = ''기존'' THEN A.ADJ_DSCNTC_RT
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN COALESCE(SCAD.ADJ_DSCNTC_CNT / NULLIF(SCAD.DVLP_CNT, 0), 0)
                ELSE COALESCE(SCAD.ADJ_DSCNTC_CNT / NULLIF((BF.CMLT_DVLP_CNT + SCAD.DVLP_CNT), 0), 0)
            END AS "중단율 재산출", --1월은 실측 ADJ_DSCNTC_CNT / 실측 DVLP_CNT   // 타월은 실측 ADJ_DSCNTC_CNT / (이전달 CMLT_DVLP_CNT + 실측 DVLP_CNT) 기존은 예측 중단률 그대로 사용
            SCAD.ADJ_DSCNTC_CNT AS "중단건조정", --실측 ADJ_DSCNTC_CNT
            CASE
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN SCAD.ADJ_DSCNTC_CNT
                ELSE SCAD.ADJ_DSCNTC_CNT + BF.ADJ_CMLT_DSCNTC_CNT
            END AS "중단건 누계", --계산 1월은 실측 ADJ_DSCNTC_CNT / 타월은 실측 ADJ_DSCNTC_CNT + 이전달 ADJ_CMLT_DSCNTC_CNT
            CASE
                WHEN A.NEW_EXST_DIV_NM = ''기존'' THEN COALESCE(SCAD.ADJ_DSCNTC_CNT / NULLIF((BF.CMLT_EOM_ACT_MBER_CNT + SCAD.DVLP_CNT), 0), 0)
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN COALESCE(SCAD.ADJ_DSCNTC_CNT / NULLIF(SCAD.DVLP_CNT, 0), 0)
                ELSE COALESCE(SCAD.ADJ_DSCNTC_CNT / NULLIF((BF.CMLT_DVLP_CNT + SCAD.DVLP_CNT), 0), 0)
            END AS "중단율(%, 월)", 
            -- --계산 기존 1월은 중단건수(월) / (연도초활동회원...이전달 월말활동회원건수임? +  실측 개발건수)
            -- --계산 1월은 실측 DSCNTC_CNT / 실측 DVLP_CNT  // 타월은 실측 DSCNTC_CNT / (이전달  CMLT_DVLP_CNT + 실측 DVLP_CNT)
            SCAD.ADJ_DSCNTC_CNT AS "중단건수(월)", -- 실측 .DSCNTC_CNT
            CASE
                WHEN A.NEW_EXST_DIV_NM = ''기존'' THEN COALESCE((SCAD.ADJ_DSCNTC_CNT + SCAD.ADJ_RDCAMT_CNT) / NULLIF((BF.CMLT_EOM_ACT_MBER_CNT + SCAD.DVLP_CNT), 0), 0)
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN COALESCE((SCAD.DVLP_CNT - SCAD.CMLT_EOM_ACT_MBER_CNT - SCAD.ADJ_DSCNTC_CNT - SCAD.ADJ_RDCAMT_CNT + SCAD.ADJ_RDCAMT_CNT) / NULLIF(SCAD.DVLP_CNT, 0), 0)
                ELSE COALESCE((BF.CMLT_EOM_ACT_MBER_CNT + SCAD.DVLP_CNT - SCAD.CMLT_EOM_ACT_MBER_CNT - SCAD.ADJ_DSCNTC_CNT - SCAD.ADJ_RDCAMT_CNT + SCAD.ADJ_RDCAMT_CNT) / NULLIF((BF.CMLT_DVLP_CNT + SCAD.DVLP_CNT), 0), 0)
            END AS "감액율(%, 월)", 
            -- --계산 기존의 경우, (후원사업변경감소(월) + 감액(월)) / (전월 월말활동회원건수 + 실측 개발건수)
            -- --계산 (후원사업변경감소(월) + 감액(월)) / 개발(누적)
            -- --타월은 (이전달 CMLT_EOM_ACT_MBER_CNT + 실측 ADJ_RDCAMT_CNT)  / (이전달 CMLT_DVLP_CNT + 실측 DVLP_CNT)
            CASE
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN SCAD.DVLP_CNT - SCAD.CMLT_EOM_ACT_MBER_CNT - SCAD.ADJ_DSCNTC_CNT - SCAD.ADJ_RDCAMT_CNT
                ELSE BF.CMLT_EOM_ACT_MBER_CNT + SCAD.DVLP_CNT - SCAD.CMLT_EOM_ACT_MBER_CNT - SCAD.ADJ_DSCNTC_CNT - SCAD.ADJ_RDCAMT_CNT
            END AS "후원사업변경감소(월)", 
            -- --계산. 1월은 실측 DVLP_CNT - 실측 CMLT_EOM_ACT_MBER_CNT - 실측 ADJ_DSCNTC_CNT - 실측 ADJ_RDCAMT_CNT  // 
            -- -- 타월은  이전달 CMLT_EOM_ACT_MBER_CNT + 실측 DVLP_CNT - 실측 CMLT_EOM_ACT_MBER_CNT - 실측 ADJ_DSCNTC_CNT - 실즉 ADJ_RDCAMT_CNT
            SCAD.ADJ_RDCAMT_CNT AS "감액(월)", -- 실측 ADJ_RDCAMT_CNT
            SCAD.CMLT_EOM_ACT_MBER_CNT AS "월말활동회원건수", --실측 CMLT_EOM_ACT_MBER_CNT
            CASE
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN SCAD.CMLT_EOM_ACT_MBER_CNT
                ELSE BF.CMLT_ACT_MBER_CNT + SCAD.CMLT_EOM_ACT_MBER_CNT
            END AS "활동회원건수(누적)", -- 계산. 1월은 실측 CMLT_EOM_ACT_MBER_CNT  // 타월은 이전달 CMLT_ACT_MBER_CNT + 실측 CMLT_EOM_ACT_MBER_CNT
            CASE
                WHEN A.NEW_EXST_DIV_NM = ''기존'' AND RIGHT(:STDR_MT, 2) = ''01'' THEN COALESCE(SCAD.CMLT_EOM_ACT_MBER_CNT / NULLIF((BF.CMLT_EOM_ACT_MBER_CNT  + SCAD.DVLP_CNT), 0), 0)
                WHEN A.NEW_EXST_DIV_NM = ''기존'' AND RIGHT(:STDR_MT, 2) != ''01'' THEN COALESCE(SCAD.CMLT_EOM_ACT_MBER_CNT / NULLIF((BF.CMLT_EOM_ACT_MBER_CNT  + BF.CMLT_DVLP_CNT + SCAD.DVLP_CNT), 0), 0)
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN COALESCE(SCAD.CMLT_EOM_ACT_MBER_CNT / NULLIF(SCAD.DVLP_CNT, 0), 0)
                ELSE COALESCE(SCAD.CMLT_EOM_ACT_MBER_CNT / NULLIF((BF.CMLT_DVLP_CNT + SCAD.DVLP_CNT), 0), 0)
            END AS "활동율(%)",   
            -- -- 계산 기존. 실측 월말활동회원수 / (전년도 12월 월말활돌회원수 + 개발(누적))
            -- -- 계산 1월은 실측 CMLT_EOM_ACT_MBER_CNT / 실측 DVLP_CNT  // 타월은 실측 CMLT_EOM_ACT_MBER_CNT / 이전달 CMLT_DVLP_CNT + 실측 DVLP_CNT
            COALESCE(SCAD.ADJ_MBRFEE_AMT / NULLIF((SCAD.CMLT_EOM_ACT_MBER_CNT * 10000), 0), 0) AS "월납입율(%)", --계산 실측 ADJ_MBRFEE_AMT / (실측 CMLT_EOM_ACT_MBER_CNT * 10000)
            SCAD.ADJ_MBRFEE_AMT AS "회비(월)", -- 실측 ADJ_MBRFEE_AMT
            CASE
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN COALESCE(SCAD.ADJ_MBRFEE_AMT / NULLIF((SCAD.CMLT_EOM_ACT_MBER_CNT * 10000), 0), 0)
                ELSE COALESCE((SCAD.ADJ_MBRFEE_AMT + BF.CMLT_MBRFEE_AMT) / NULLIF(((BF.CMLT_ACT_MBER_CNT + SCAD.CMLT_EOM_ACT_MBER_CNT) * 10000), 0), 0)
            END AS "누계납입율", 
            -- -- 계산 누계회비 / (활동회원건수(누적) * 10000)
            -- -- 계산 1월은 실측 ADJ_MBRFEE_AMT / (실측 CMLT_EOM_ACT_MBER_CNT * 10000) 
            -- -- 타월은 (실측 ADJ_MBRFEE_AMT + 이전달 CMLT_MBRFEE_AMT ) / (이전달 CMLT_ACT_MBER_CNT + 실측 CMLT_EOM_ACT_MBER_CNT * 10000)
            CASE
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN SCAD.ADJ_MBRFEE_AMT
                ELSE SCAD.ADJ_MBRFEE_AMT + BF.CMLT_MBRFEE_AMT
            END AS "누계회비", -- 계산. 1월은 실측 ADJ_MBRFEE_AMT  //  타월은  실측 ADJ_MBRFEE_AMT + 이전달 CMLT_MBRFEE_AMT 
            CASE
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN COALESCE(SCAD.ADJ_MBRFEE_AMT / NULLIF((SCAD.CMLT_EOM_ACT_MBER_CNT * 10000), 0), 0)
                ELSE COALESCE((SCAD.ADJ_MBRFEE_AMT + BF.CMLT_MBRFEE_AMT) / NULLIF(((BF.CMLT_ACT_MBER_CNT + SCAD.CMLT_EOM_ACT_MBER_CNT) * 10000), 0), 0)
            END AS "누계납입율(%)", -- 계산 1월은 실측 ADJ_MBRFEE_AMT / (실측 CMLT_EOM_ACT_MBER_CNT * 10000) 
            --                          -- 타월은 (실측 ADJ_MBRFEE_AMT + 이전달 CMLT_MBRFEE_AMT ) / (이전달 CMLT_ACT_MBER_CNT + 실측 CMLT_EOM_ACT_MBER_CNT * 10000)
            --                          -- 즉 누계납입율 과 같음....
            CASE
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN SCAD.ADJ_MBRFEE_AMT * COALESCE((SCAD.ADJ_MBRFEE_AMT / NULLIF((SCAD.CMLT_EOM_ACT_MBER_CNT * 10000), 0)) * 10000, 0)
                ELSE (BF.CMLT_ACT_MBER_CNT + SCAD.CMLT_EOM_ACT_MBER_CNT) * COALESCE((SCAD.ADJ_MBRFEE_AMT + BF.CMLT_MBRFEE_AMT) / NULLIF((BF.CMLT_ACT_MBER_CNT + SCAD.CMLT_EOM_ACT_MBER_CNT) * 10000, 0) * 10000, 0)
            END AS "회비(누적)", 
            -- -- 계산 활동회원건수(누적) * 10000 * 누계납입율 
            CASE
                WHEN RIGHT(:STDR_MT, 2) = ''01'' THEN SCAD.ADJ_MBRFEE_AMT * COALESCE((SCAD.ADJ_MBRFEE_AMT / NULLIF((SCAD.CMLT_EOM_ACT_MBER_CNT * 10000), 0)) * 10000, 0) - 0
                ELSE (BF.CMLT_ACT_MBER_CNT + SCAD.CMLT_EOM_ACT_MBER_CNT) * COALESCE((SCAD.ADJ_MBRFEE_AMT + BF.CMLT_MBRFEE_AMT) / NULLIF((BF.CMLT_ACT_MBER_CNT + SCAD.CMLT_EOM_ACT_MBER_CNT) * 10000, 0) * 10000, 0) - 0
            END AS "회비 차액", 
            -- --계산 해당월 회비(누적) - 전년도 동월 회비(누적)
        FROM GN_DW.SILVER.ANNUAL_MBRFEE_PRDT_ACTL_DATA A
        LEFT OUTER JOIN (
            SELECT *
            FROM GN_DW.SILVER.ANNUAL_MBRFEE_PRDT_ACTL_DATA
            WHERE STDR_MT = :BEFORE_MT
            -- WHERE STDR_MT = ''202605''
            AND DATA_TYPE_NM = ''실측''
        ) BF ON A.SPNSR_BSNS_GRP_NM = BF.SPNSR_BSNS_GRP_NM AND A.NEW_EXST_DIV_NM = BF.NEW_EXST_DIV_NM AND A.HDQ_BRNCH_GRP_NM = BF.HDQ_BRNCH_GRP_NM
        LEFT OUTER JOIN (
            SELECT
                STDR_MT,
                SPNSR_BSNS_GRP_NM,
                NEW_EXST_DIV_NM,
                HDQ_BRNCH_GRP_NM,
                DVLP_CNT,
                ADJ_DSCNTC_CNT,
                ADJ_RDCAMT_CNT,
                CMLT_EOM_ACT_MBER_CNT,
                ADJ_MBRFEE_AMT,
                ADJ_CMLT_MBRFEE_AMT
            FROM BASE
            UNION ALL
            /* 신규 + 본부/지부 합계 */
            SELECT
                STDR_MT,
                SPNSR_BSNS_GRP_NM,
                ''신규'' AS NEW_EXST_DIV_NM,
                ''본부지부'' AS HDQ_BRNCH_GRP_NM,
                SUM(DVLP_CNT) AS DVLP_CNT,
                SUM(ADJ_DSCNTC_CNT) AS ADJ_DSCNTC_CNT,
                SUM(ADJ_RDCAMT_CNT) AS ADJ_RDCAMT_CNT,
                SUM(CMLT_EOM_ACT_MBER_CNT) AS CMLT_EOM_ACT_MBER_CNT,
                SUM(ADJ_MBRFEE_AMT) AS ADJ_MBRFEE_AMT,
                SUM(ADJ_CMLT_MBRFEE_AMT) AS ADJ_CMLT_MBRFEE_AMT
            FROM BASE
            WHERE NEW_EXST_DIV_NM = ''신규''
              AND HDQ_BRNCH_GRP_NM IN (''본부'', ''지부'')
            GROUP BY
                STDR_MT,
                SPNSR_BSNS_GRP_NM
        ) SCAD ON A.STDR_MT = SCAD.STDR_MT AND A.SPNSR_BSNS_GRP_NM = SCAD.SPNSR_BSNS_GRP_NM AND A.NEW_EXST_DIV_NM = SCAD.NEW_EXST_DIV_NM AND A.HDQ_BRNCH_GRP_NM = SCAD.HDQ_BRNCH_GRP_NM
    WHERE A.DATA_TYPE_NM = ''예측'' 
        AND A.STDR_MT = :STDR_MT
        -- AND A.SPNSR_BSNS_GRP_NM = ''희망학교지원사업''
    ORDER BY
        A.STDR_MT,
        A.SPNSR_BSNS_GRP_NM,
        A.NEW_EXST_DIV_NM;

    
    RETURN ''SUCCESS: '' || :STDR_MT;
END;
';
CREATE OR REPLACE PROCEDURE GN_DW.SILVER.SP_INSERT_MM_SPNSR_CLS_AGGR_DATA1("INPUT_YYYYMM" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS CALLER
AS '
DECLARE
    START_MT VARCHAR;
    END_MT VARCHAR;
    BASE_MT VARCHAR;
    AGGR_TY_NM VARCHAR;
    UPDATE_SQL VARCHAR;
BEGIN
    -- 0. 파라미터
    IF (NOT REGEXP_LIKE(input_yyyymm, ''^[0-9]{6}$'')) THEN
        RETURN ''ERROR: input_yyyymm은 YYYYMM 형식이어야 합니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'') IS NULL) THEN
        RETURN ''ERROR: 유효하지 않은 년월입니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (
        TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'')
        > DATE_TRUNC(''MONTH'', CURRENT_DATE())
    ) THEN
        RETURN ''ERROR: 미래 년월은 입력할 수 없습니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    START_MT := input_yyyymm;
    END_MT := START_MT;
    BASE_MT := LEFT(:START_MT, 4) || ''01'';
    AGGR_TY_NM := ''개발'';

    --기존 데이터 삭제
    DELETE
    FROM GN_DW.SILVER.MM_SPNSR_CLS_AGGR_DATA
    WHERE STDR_MT = :START_MT
    AND AGGR_TY_NM = :AGGR_TY_NM;

    --인입
    INSERT INTO GN_DW.SILVER.MM_SPNSR_CLS_AGGR_DATA
    WITH RECURSIVE
    -- 1. 조회월 생성 (시작연도 1월부터)
    MONTH_CTE AS (
        SELECT :BASE_MT AS STRD_MT
        UNION ALL
        SELECT TO_CHAR(
                   DATEADD(
                       MONTH,
                       1,
                       TO_DATE(STRD_MT || ''01'', ''YYYYMMDD'')
                   ),
                   ''YYYYMM''
               )
        FROM MONTH_CTE
        WHERE STRD_MT < :END_MT
    ),
    
    /* 2. 기준월 Dimension */
    STRD_MT_CD AS (
        SELECT
            STRD_MT,
            LEFT(STRD_MT, 4) || ''-'' || RIGHT(STRD_MT, 2) AS STRD_NM
        FROM MONTH_CTE
    ),
    
    /* 3. 연도 누적월 매핑 */
    STRD_ADD_MT AS (
        SELECT
            A.STRD_MT,
            B.STRD_MT AS STRD_ADD_MT
        FROM MONTH_CTE A
        JOIN MONTH_CTE B
            ON B.STRD_MT <= A.STRD_MT
           AND LEFT(B.STRD_MT, 4) = LEFT(A.STRD_MT, 4)
        WHERE A.STRD_MT BETWEEN :START_MT AND :END_MT
    ),
    
    /* 4. 공통코드 (ODS 원천 + 하드코딩) */
    CMMN_DTL_CD AS (
        SELECT DISTINCT
            B.CD_ID,
            B.DTL_CD_ID,
            B.DTL_CD_NM,
            B.SORT_ORDR,
            NVL(B.USE_YN, ''Y'') AS USE_YN
        FROM GN_DW.BRONZE_CRM.TC_CMMN_CD A
        JOIN GN_DW.BRONZE_CRM.TC_CMMN_DTL_CD B
            ON A.CD_ID = B.CD_ID
        WHERE B.CD_ID IN (''CM003'', ''CM019'', ''MM015'')
    
        UNION ALL
    
        SELECT ''DMMM07'', ''1'', ''신규'', 1, ''Y''
    
        UNION ALL
    
        SELECT ''DMMM07'', ''2'', ''기존'', 2, ''Y''
    ),
    
    /* 5. 공통코드 메타 (없음 값 생성용) */
    CMMN_DTL_META AS (
        SELECT
            CD_ID,
            MAX(OCTET_LENGTH(DTL_CD_ID)) AS MSIZE,
            MAX(DTL_CD_ID) AS MVAL
        FROM CMMN_DTL_CD
        GROUP BY CD_ID
    ),
    
    /* 6. 공통코드 + 없음 값 통합 */
    CMMN_DTL_CD_FULL AS (
        SELECT
            CD_ID,
            DTL_CD_ID,
            DTL_CD_NM,
            SORT_ORDR,
            USE_YN
        FROM CMMN_DTL_CD
    
        UNION ALL
    
        SELECT
            CD_ID,
            CASE
                WHEN MVAL > ''A'' AND MSIZE = 1 THEN ''Z''
                WHEN MVAL > ''A'' AND MSIZE > 1 THEN ''Z~''
                WHEN MVAL < ''A'' AND MSIZE = 1 THEN ''99''
                WHEN MVAL < ''A'' AND MSIZE = 2 THEN ''999''
                WHEN MVAL < ''A'' AND MSIZE = 3 THEN ''9999''
                ELSE ''99999''
            END AS DTL_CD_ID,
            ''없음'' AS DTL_CD_NM,
            999 AS SORT_ORDR,
            ''Y'' AS USE_YN
        FROM CMMN_DTL_META
    ),
    
    /* 7. Dimension: 후원사업 약칭 */
    SPNSR_BSNS_ABRV_CD_DIM AS (
        SELECT
            DTL_CD_ID AS SPNSR_BSNS_ABRV_CD,
            DTL_CD_NM AS SPNSR_BSNS_ABRV_NM,
            SORT_ORDR,
            USE_YN
        FROM CMMN_DTL_CD_FULL
        WHERE CD_ID = ''CM003''
    ),
    
    /* 8. Dimension: 법인구분 */
    CPR_DIV_CD_DIM AS (
        SELECT
            DTL_CD_ID AS CPR_DIV_CD,
            DTL_CD_NM AS CPR_DIV_NM,
            SORT_ORDR,
            USE_YN
        FROM CMMN_DTL_CD_FULL
        WHERE CD_ID = ''CM019''
    ),
    
    /* 9. Dimension: 신규/기존 */
    NEW_OLD_DIV_CD_DIM AS (
        SELECT
            DTL_CD_ID AS NEW_OLD_DIV_CD,
            DTL_CD_NM AS NEW_OLD_DIV_NM,
            SORT_ORDR,
            USE_YN
        FROM CMMN_DTL_CD_FULL
        WHERE CD_ID = ''DMMM07''
    ),
    
    /* 10. Dimension: 개발구분 */
    DVLP_DIV_CD_DIM AS (
        SELECT
            DTL_CD_ID AS DVLP_DIV_CD,
            DTL_CD_NM AS DVLP_DIV_NM,
            SORT_ORDR,
            USE_YN
        FROM CMMN_DTL_CD_FULL
        WHERE CD_ID = ''MM015''
    ),
    
    /* 11. 부서 기본정보 + Z~ 가상부서 */
    CM_DEPT_INFO AS (
        SELECT
            DEPT_ID,
            DEPT_NM,
            UPPER_DEPT_ID,
            SORT_ORDR,
            USE_YN,
            FRST_RGSTR_ID,
            FRST_REGIST_DT,
            LAST_UPDUSR_ID,
            LAST_UPDT_DT,
            ACMSLT_DEPT_YN,
            STATS_DEPT_LVL,
            ACMSLT_UPPER_DEPT_ID
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO
    
        UNION ALL
    
        SELECT
            ''Z~'',
            ''N/A'',
            ''ZV000000'',
            SORT_ORDR,
            USE_YN,
            FRST_RGSTR_ID,
            FRST_REGIST_DT,
            LAST_UPDUSR_ID,
            LAST_UPDT_DT,
            ACMSLT_DEPT_YN,
            STATS_DEPT_LVL,
            ''A000001''
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO
        WHERE DEPT_ID = ''A000000''
    ),
    
    /* 12. 실적부서 계층 */
    DEPT_CD AS (
        SELECT
            E.DEPT_ID,
            E.DEPT_NM,
            D.DEPT_ID AS DEPT2_ID,
            C.DEPT_ID AS DEPT3_ID,
            B.DEPT_ID AS DEPT4_ID,
            A.DEPT_ID AS DEPT5_ID,
            E.SORT_ORDR,
            E.USE_YN,
            E.ACMSLT_DEPT_YN
        FROM CM_DEPT_INFO A
        JOIN CM_DEPT_INFO B
            ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
        JOIN CM_DEPT_INFO C
            ON C.ACMSLT_UPPER_DEPT_ID = B.DEPT_ID
        JOIN CM_DEPT_INFO D
            ON D.ACMSLT_UPPER_DEPT_ID = C.DEPT_ID
        JOIN CM_DEPT_INFO E
            ON E.ACMSLT_UPPER_DEPT_ID = D.DEPT_ID
        WHERE A.UPPER_DEPT_ID = ''ZV000000''
          AND C.DEPT_ID <> ''ZC000029''
    
        UNION ALL
    
        SELECT
            ''Z~'',
            ''없음'',
            ''Z~'',
            ''Z~'',
            ''Z~'',
            ''Z~'',
            999,
            ''Y'',
            ''Y''
    ),
    /* 13. 후원사업 정보 */
    SPNSR_BSNS_INFO AS (
        SELECT
            SPNSR_BSNS_ID,
            SPNSR_BSNS_NM,
            SPNSR_BSNS_ABRV_CD,
            SORT_ORDR,
            CASE
                WHEN CPR_DIV_CD = ''1'' THEN ''I''
                WHEN CPR_DIV_CD = ''2'' THEN ''S''
                ELSE CPR_DIV_CD
            END AS CPR_DIV_CD
        FROM GN_DW.BRONZE_CRM.TM_CM_SPNSR_BSNS_INFO
    
        UNION ALL
    
        SELECT
            ''99'',
            ''없음'',
            ''99'',
            999,
            ''Z''
    ),
    
    /* 14. 후원사업 진행정보 */
    SPNSR_BSNS_V AS (
        SELECT
            A.SPNSR_NO,
            B.SPNSR_BSNS_NO,
            B.SPNSR_BSNS_ID,
            A.MBER_NO,
            TO_CHAR(A.FRST_REGIST_DT, ''YYYYMMDD'') AS FST_DE,
            NVL(B.SPNSR_DSCNTC_DE, ''99991231'') AS DSC_DE
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR A
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR_BSNS B
            ON A.SPNSR_NO = B.SPNSR_NO
    ),
    
    /* 15. 신규/재후원 개발내역 */
    NEW_BASE AS (
        SELECT
            LEFT(A.OCCRRNC_DE, 6) AS STRD_MT,
            A.OCCRRNC_DE,
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.SER_NO,
            A.MBER_NO,
            NVL(A.ACMSLT_DEPT_CD, ''Z~'') AS ACMSLT_DEPT_CD,
            A.SPNSR_BSNS_ID,
            A.DVLP_DIV_CD,
            A.SPNSR_AMT,
    
            SUM(A.SPNSR_AMT) OVER (
                PARTITION BY
                    A.SPNSR_NO,
                    A.SPNSR_BSNS_NO,
                    LEFT(A.OCCRRNC_DE, 6)
            ) AS MAMT
    
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_DVLP_AMT A
    
        JOIN SPNSR_BSNS_V B
            ON A.SPNSR_NO = B.SPNSR_NO
           AND A.SPNSR_BSNS_NO = B.SPNSR_BSNS_NO
           AND B.DSC_DE > LEFT(A.OCCRRNC_DE, 6) || ''31''
    
        WHERE A.DVLP_DIV_CD IN (''1'', ''4'')
          AND LEFT(A.OCCRRNC_DE, 6)
              BETWEEN :BASE_MT AND :END_MT
    ),
    
    DVLP_NEW AS (
        SELECT
            STRD_MT,
            OCCRRNC_DE,
            SPNSR_NO,
            SPNSR_BSNS_NO,
            SER_NO,
            MBER_NO,
            ACMSLT_DEPT_CD,
            SPNSR_BSNS_ID,
            DVLP_DIV_CD,
            SPNSR_AMT
        FROM NEW_BASE
        WHERE MAMT > 0
    ),
    
    /* 16. 증액 계산 1단계 */
    INC_STEP1 AS (
        SELECT
            LEFT(A.OCCRRNC_DE, 6) AS STRD_MT,
            A.OCCRRNC_DE,
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.SER_NO,
            A.MBER_NO,
            NVL(A.ACMSLT_DEPT_CD, ''Z~'') AS ACMSLT_DEPT_CD,
            A.SPNSR_BSNS_ID,
            A.DVLP_DIV_CD,
            A.SPNSR_AMT,
    
            SUM(
                CASE
                    WHEN A.DVLP_DIV_CD IN (''2'', ''3'')
                        THEN A.SPNSR_AMT
                    ELSE 0
                END
            ) OVER (
                PARTITION BY
                    A.SPNSR_NO,
                    A.SPNSR_BSNS_NO,
                    LEFT(A.OCCRRNC_DE, 6)
            ) AS SAMT,
    
            SUM(A.SPNSR_AMT) OVER (
                PARTITION BY
                    A.MBER_NO,
                    LEFT(A.OCCRRNC_DE, 6)
            ) AS MAMT
    
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_DVLP_AMT A
    
        WHERE A.DVLP_DIV_CD IN (''2'', ''3'', ''5'')
          AND LEFT(A.OCCRRNC_DE, 6)
              BETWEEN :BASE_MT AND :END_MT
    ),
    
    /* 17. 증액 계산 2단계 */
    INC_STEP2 AS (
        SELECT
            A.*,
    
            SUM(
                CASE
                    WHEN A.DVLP_DIV_CD = ''3''
                        THEN A.SPNSR_AMT
                    ELSE 0
                END
            ) OVER (
                PARTITION BY
                    A.MBER_NO,
                    A.STRD_MT
            ) AS DAMT
    
        FROM INC_STEP1 A
    
        WHERE A.MAMT > 0
          AND (
                (A.SAMT > 0 AND A.DVLP_DIV_CD = ''2'')
             OR (A.SAMT < 0 AND A.DVLP_DIV_CD = ''3'')
          )
    ),
    
    /* 18. 증액 계산 3단계 */
    INC_STEP3 AS (
        SELECT
            A.*,
    
            SUM(A.SAMT) OVER (
                PARTITION BY
                    A.MBER_NO,
                    A.STRD_MT
                ORDER BY
                    A.OCCRRNC_DE,
                    A.SER_NO
                ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
            ) AS AAMT
    
        FROM INC_STEP2 A
    
        WHERE A.DVLP_DIV_CD = ''2''
    ),
    
    /* 19. 증액 최종 */
    INC_CALC AS (
        SELECT
            A.STRD_MT,
            A.OCCRRNC_DE,
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.SER_NO,
            A.MBER_NO,
            A.ACMSLT_DEPT_CD,
            A.SPNSR_BSNS_ID,
            ''2'' AS DVLP_DIV_CD,
    
            CASE
                WHEN A.MAMT <= A.SAMT
                     AND A.AAMT + A.DAMT <= A.MAMT
                    THEN A.AAMT + A.DAMT
    
                WHEN A.MAMT > A.SAMT
                     AND A.AAMT + A.DAMT <= A.SAMT
                    THEN A.AAMT + A.DAMT
    
                WHEN A.MAMT <= A.SAMT
                    THEN A.MAMT
    
                ELSE A.SAMT
            END AS SPNSR_AMT,
    
            ROW_NUMBER() OVER (
                PARTITION BY
                    A.STRD_MT,
                    A.SPNSR_NO,
                    A.SPNSR_BSNS_NO
                ORDER BY
                    A.SER_NO
            ) AS RNUM
    
        FROM INC_STEP3 A
    
        WHERE A.AAMT - ABS(A.DAMT) > 0
    ),
    
    DVLP_INC AS (
        SELECT
            STRD_MT,
            OCCRRNC_DE,
            SPNSR_NO,
            SPNSR_BSNS_NO,
            SER_NO,
            MBER_NO,
            ACMSLT_DEPT_CD,
            SPNSR_BSNS_ID,
            DVLP_DIV_CD,
            SPNSR_AMT
        FROM INC_CALC
        WHERE RNUM = 1
    ),
    
    /* 20. 신규 + 증액 + 재후원 통합 */
    DVLP_BASE AS (
        SELECT * FROM DVLP_NEW
    
        UNION ALL
    
        SELECT * FROM DVLP_INC
    ),
    
    /* 21. Fact 생성 */
    FACT AS (
        SELECT
            A.STRD_MT,
            A.MBER_NO,
    
            NVL(B.DEPT2_ID, ''Z~'') AS ACMSLT_DEPT2_CD,
            NVL(B.DEPT3_ID, ''Z~'') AS ACMSLT_DEPT3_CD,
            NVL(B.DEPT4_ID, ''Z~'') AS ACMSLT_DEPT4_CD,
    
            A.SPNSR_BSNS_ID,
    
            NVL(F.SPNSR_BSNS_ABRV_CD, ''0'') AS SPNSR_BSNS_ABRV_CD,
            NVL(F.CPR_DIV_CD, ''0'') AS CPR_DIV_CD,
    
            A.DVLP_DIV_CD,
    
            CASE
                WHEN LEFT(A.OCCRRNC_DE, 4)
                     = TO_VARCHAR(E.FRST_REGIST_DT, ''YYYY'')
                    THEN ''1''
                ELSE ''2''
            END AS NEW_OLD_DIV_CD,
    
            A.SPNSR_AMT,
    
            CAST(
                A.SPNSR_AMT / 10000.0
                AS DECIMAL(38,6)
            ) AS SPNSR_AMT_CNT,
    
            A.OCCRRNC_DE
    
        FROM DVLP_BASE A
    
        LEFT JOIN DEPT_CD B
            ON A.ACMSLT_DEPT_CD = B.DEPT_ID
    
        LEFT JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_INFO E
            ON A.MBER_NO = E.MBER_NO
    
        LEFT JOIN SPNSR_BSNS_INFO F
            ON A.SPNSR_BSNS_ID = F.SPNSR_BSNS_ID
    
        WHERE A.STRD_MT BETWEEN :BASE_MT AND :END_MT
          AND A.DVLP_DIV_CD IN (''1'', ''2'', ''4'')
    ),
    
    /* 22. 당월 집계 */
    CURRENT_SUM AS (
        SELECT
            SPNSR_BSNS_ABRV_CD,
            SPNSR_BSNS_ID,
    
            ACMSLT_DEPT2_CD AS DEPT2_ID,
            NEW_OLD_DIV_CD,
    
            ACMSLT_DEPT3_CD AS DEPT3_ID,
            ACMSLT_DEPT4_CD AS DEPT4_ID,
    
            CPR_DIV_CD,
            STRD_MT,
            DVLP_DIV_CD,
    
            SUM(SPNSR_AMT_CNT) AS WJXBFS1,
            COUNT(DISTINCT MBER_NO) AS WJXBFS2,
            SUM(SPNSR_AMT) AS WJXBFS3
    
        FROM FACT
    
        WHERE STRD_MT BETWEEN :START_MT AND :END_MT
          AND DVLP_DIV_CD IN (''1'', ''2'', ''4'')
    
        GROUP BY
            SPNSR_BSNS_ABRV_CD,
            SPNSR_BSNS_ID,
            ACMSLT_DEPT2_CD,
            NEW_OLD_DIV_CD,
            ACMSLT_DEPT3_CD,
            ACMSLT_DEPT4_CD,
            CPR_DIV_CD,
            STRD_MT,
            DVLP_DIV_CD
    ),
    
    /* 23. 연도 누적 집계 */
    CUMULATIVE_SUM AS (
        SELECT
            A.SPNSR_BSNS_ABRV_CD,
            A.SPNSR_BSNS_ID,
    
            A.ACMSLT_DEPT2_CD AS DEPT2_ID,
            A.NEW_OLD_DIV_CD,
    
            A.ACMSLT_DEPT3_CD AS DEPT3_ID,
            A.ACMSLT_DEPT4_CD AS DEPT4_ID,
    
            A.CPR_DIV_CD,
            M.STRD_MT,
            A.DVLP_DIV_CD,
    
            SUM(A.SPNSR_AMT_CNT) AS WJXBFS1,
            COUNT(DISTINCT A.MBER_NO) AS WJXBFS2
    
        FROM FACT A
    
        JOIN STRD_ADD_MT M
            ON A.STRD_MT = M.STRD_ADD_MT
    
        WHERE M.STRD_MT BETWEEN :START_MT AND :END_MT
          AND A.DVLP_DIV_CD IN (''1'', ''2'', ''4'')
    
        GROUP BY
            A.SPNSR_BSNS_ABRV_CD,
            A.SPNSR_BSNS_ID,
            A.ACMSLT_DEPT2_CD,
            A.NEW_OLD_DIV_CD,
            A.ACMSLT_DEPT3_CD,
            A.ACMSLT_DEPT4_CD,
            A.CPR_DIV_CD,
            M.STRD_MT,
            A.DVLP_DIV_CD
    ),
    
    /* 24. 최종 집계 원천 */
    FINAL_BASE AS (
        SELECT
            COALESCE(C.STRD_MT, Y.STRD_MT) AS STRD_MT,
    
            CPR.CPR_DIV_NM AS CPR_NM,
    
            CASE
                WHEN SBI.SPNSR_BSNS_NM IN (
                    ''결식아동지원'',
                    ''국내아동권리보호사업(사단법인)'',
                    ''복지관후원'',
                    ''아동복지시설지원'',
                    ''아동학대예방'',
                    ''저소득가정지원''
                )
                    THEN ''국내(사단)''
                ELSE SBI.SPNSR_BSNS_NM
            END AS SPNSR_BSNS_GRP_NM,
    
            NOD.NEW_OLD_DIV_NM AS NEW_EXST_DIV_NM,
    
            /*
             * 기존은 본부/지부 구분 없이 하나로 통합
             * 신규만 본부/지부 구분
             */
            CASE
                WHEN NOD.NEW_OLD_DIV_NM = ''기존''
                    THEN ''기존''
    
                WHEN D4.DEPT_NM IN (''본부'', ''본부(사복)'')
                    THEN ''본부''
    
                ELSE ''지부''
            END AS HDQ_BRNCH_GRP_NM,
    
            NVL(SUM(C.WJXBFS1), 0) AS VALUE1
    
        FROM CURRENT_SUM C
    
        FULL OUTER JOIN CUMULATIVE_SUM Y
            ON C.CPR_DIV_CD = Y.CPR_DIV_CD
           AND C.DEPT2_ID = Y.DEPT2_ID
           AND C.DEPT3_ID = Y.DEPT3_ID
           AND C.DEPT4_ID = Y.DEPT4_ID
           AND C.DVLP_DIV_CD = Y.DVLP_DIV_CD
           AND C.NEW_OLD_DIV_CD = Y.NEW_OLD_DIV_CD
           AND C.SPNSR_BSNS_ABRV_CD = Y.SPNSR_BSNS_ABRV_CD
           AND C.SPNSR_BSNS_ID = Y.SPNSR_BSNS_ID
           AND C.STRD_MT = Y.STRD_MT
    
        LEFT JOIN STRD_MT_CD STM
            ON STM.STRD_MT = COALESCE(C.STRD_MT, Y.STRD_MT)
    
        LEFT JOIN CM_DEPT_INFO D4
            ON D4.DEPT_ID = COALESCE(C.DEPT4_ID, Y.DEPT4_ID)
    
        LEFT JOIN CM_DEPT_INFO D3
            ON D3.DEPT_ID = COALESCE(C.DEPT3_ID, Y.DEPT3_ID)
    
        LEFT JOIN CM_DEPT_INFO D2
            ON D2.DEPT_ID = COALESCE(C.DEPT2_ID, Y.DEPT2_ID)
    
        LEFT JOIN SPNSR_BSNS_INFO SBI
            ON SBI.SPNSR_BSNS_ID =
               COALESCE(C.SPNSR_BSNS_ID, Y.SPNSR_BSNS_ID)
    
        LEFT JOIN SPNSR_BSNS_ABRV_CD_DIM SBA
            ON SBA.SPNSR_BSNS_ABRV_CD =
               COALESCE(
                   C.SPNSR_BSNS_ABRV_CD,
                   Y.SPNSR_BSNS_ABRV_CD
               )
    
        LEFT JOIN DVLP_DIV_CD_DIM DVD
            ON DVD.DVLP_DIV_CD =
               COALESCE(C.DVLP_DIV_CD, Y.DVLP_DIV_CD)
    
        LEFT JOIN CPR_DIV_CD_DIM CPR
            ON CPR.CPR_DIV_CD =
               COALESCE(C.CPR_DIV_CD, Y.CPR_DIV_CD)
    
        LEFT JOIN NEW_OLD_DIV_CD_DIM NOD
            ON NOD.NEW_OLD_DIV_CD =
               COALESCE(
                   C.NEW_OLD_DIV_CD,
                   Y.NEW_OLD_DIV_CD
               )
    
        WHERE CPR.CPR_DIV_NM = ''사단''
    
        GROUP BY
            COALESCE(C.STRD_MT, Y.STRD_MT),
            CPR.CPR_DIV_NM,
    
            CASE
                WHEN SBI.SPNSR_BSNS_NM IN (
                    ''결식아동지원'',
                    ''국내아동권리보호사업(사단법인)'',
                    ''복지관후원'',
                    ''아동복지시설지원'',
                    ''아동학대예방'',
                    ''저소득가정지원''
                )
                    THEN ''국내(사단)''
                ELSE SBI.SPNSR_BSNS_NM
            END,
    
            NOD.NEW_OLD_DIV_NM,
    
            CASE
                WHEN NOD.NEW_OLD_DIV_NM = ''기존''
                    THEN ''기존''
    
                WHEN D4.DEPT_NM IN (''본부'', ''본부(사복)'')
                    THEN ''본부''
    
                ELSE ''지부''
            END
    ),
    
    /* 25. 후원사업별 기준 목록 */
    SPNSR_BSNS_3ROW AS (
        SELECT DISTINCT
            STRD_MT,
            CPR_NM,
            SPNSR_BSNS_GRP_NM
        FROM FINAL_BASE
    ),
    
    /* 26. 반드시 생성해야 하는 3개 행 */
    ROW_TYPE AS (
        SELECT
            ''기존'' AS NEW_EXST_DIV_NM,
            ''기존'' AS HDQ_BRNCH_GRP_NM
    
        UNION ALL
    
        SELECT
            ''신규'' AS NEW_EXST_DIV_NM,
            ''본부'' AS HDQ_BRNCH_GRP_NM
    
        UNION ALL
    
        SELECT
            ''신규'' AS NEW_EXST_DIV_NM,
            ''지부'' AS HDQ_BRNCH_GRP_NM
    ),
    
    /* 27. 후원사업별 3행 강제 생성 */
    FINAL_3ROW AS (
        SELECT
            A.STRD_MT,
            A.CPR_NM,
            A.SPNSR_BSNS_GRP_NM,
    
            B.NEW_EXST_DIV_NM,
            B.HDQ_BRNCH_GRP_NM,
    
            NVL(C.VALUE1, 0) AS VALUE1
    
        FROM SPNSR_BSNS_3ROW A
    
        CROSS JOIN ROW_TYPE B
    
        LEFT JOIN FINAL_BASE C
            ON C.STRD_MT = A.STRD_MT
           AND C.CPR_NM = A.CPR_NM
           AND C.SPNSR_BSNS_GRP_NM = A.SPNSR_BSNS_GRP_NM
           AND C.NEW_EXST_DIV_NM = B.NEW_EXST_DIV_NM
           AND C.HDQ_BRNCH_GRP_NM = B.HDQ_BRNCH_GRP_NM
    )
    
    /* 28. 최종 결과 */
    SELECT
        STRD_MT,
        :AGGR_TY_NM AS AGGR_TY_NM,
        CPR_NM,
        SPNSR_BSNS_GRP_NM,
        NEW_EXST_DIV_NM,
        HDQ_BRNCH_GRP_NM,
        VALUE1,
        NULL AS VALUE2
    
    FROM FINAL_3ROW
    
    ORDER BY
        STRD_MT,
        CPR_NM,
        SPNSR_BSNS_GRP_NM,
    
        CASE
            WHEN NEW_EXST_DIV_NM = ''기존''
                THEN 1
    
            WHEN NEW_EXST_DIV_NM = ''신규''
                 AND HDQ_BRNCH_GRP_NM = ''본부''
                THEN 2
    
            WHEN NEW_EXST_DIV_NM = ''신규''
                 AND HDQ_BRNCH_GRP_NM = ''지부''
                THEN 3
        END
    ;
    
    RETURN ''SUCCESS: '' || :START_MT;
END;
';
CREATE OR REPLACE PROCEDURE GN_DW.SILVER.SP_INSERT_MM_SPNSR_CLS_AGGR_DATA2("INPUT_YYYYMM" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS CALLER
AS '
DECLARE
    STDR_MT VARCHAR;
    AGGR_TY_NM VARCHAR;
BEGIN
    -- 0. 파라미터
    IF (NOT REGEXP_LIKE(input_yyyymm, ''^[0-9]{6}$'')) THEN
        RETURN ''ERROR: input_yyyymm은 YYYYMM 형식이어야 합니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'') IS NULL) THEN
        RETURN ''ERROR: 유효하지 않은 년월입니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (
        TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'')
        > DATE_TRUNC(''MONTH'', CURRENT_DATE())
    ) THEN
        RETURN ''ERROR: 미래 년월은 입력할 수 없습니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    STDR_MT := input_yyyymm;
    AGGR_TY_NM := ''중단'';

    DELETE
    FROM GN_DW.SILVER.MM_SPNSR_CLS_AGGR_DATA
    WHERE STDR_MT = :STDR_MT
    AND AGGR_TY_NM = :AGGR_TY_NM;
    
    INSERT INTO GN_DW.SILVER.MM_SPNSR_CLS_AGGR_DATA
    WITH
    SPNSR_BSNS_DIM AS
    (
        /* MART.D_SPNSR_BSNS_INFO 재현 */
        SELECT
            A.SPNSR_BSNS_ID,
            A.SPNSR_BSNS_NM,
            A.SORT_ORDR,
            CASE
                WHEN A.CPR_DIV_CD = ''1'' THEN ''I''
                WHEN A.CPR_DIV_CD = ''2'' THEN ''S''
                ELSE A.CPR_DIV_CD
            END AS CPR_DIV_CD
        FROM GN_DW.BRONZE_CRM.TM_CM_SPNSR_BSNS_INFO A
    
        UNION ALL
    
        SELECT
            ''99'' AS SPNSR_BSNS_ID,
            ''없음'' AS SPNSR_BSNS_NM,
            999 AS SORT_ORDR,
            ''Z'' AS CPR_DIV_CD
    ),
    
    CPR_DIV_DIM AS
    (
        /* MART.D_CPR_DIV_CD 재현 */
        SELECT DISTINCT
            B.DTL_CD_ID AS CPR_DIV_CD,
            B.DTL_CD_NM AS CPR_DIV_NM
        FROM GN_DW.BRONZE_CRM.TC_CMMN_CD A
        INNER JOIN GN_DW.BRONZE_CRM.TC_CMMN_DTL_CD B
            ON A.CD_ID = B.CD_ID
        WHERE B.CD_ID = ''CM019''
    ),
    
    DEPT_HIERARCHY AS
    (
        /*
            원천 실적부서 코드에서
            본부/지부(DEPT4) 코드를 산출
        */
        SELECT
            E.DEPT_ID AS SOURCE_DEPT_ID,
            B.DEPT_ID AS DEPT4_ID
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO A
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO B
            ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO C
            ON C.ACMSLT_UPPER_DEPT_ID = B.DEPT_ID
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO D
            ON D.ACMSLT_UPPER_DEPT_ID = C.DEPT_ID
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO E
            ON E.ACMSLT_UPPER_DEPT_ID = D.DEPT_ID
        WHERE A.UPPER_DEPT_ID = ''ZV000000''
          AND C.DEPT_ID <> ''ZC000029''
    
        UNION ALL
    
        SELECT
            ''Z~'' AS SOURCE_DEPT_ID,
            ''Z~'' AS DEPT4_ID
    ),
    
    DEPT4_DIM AS
    (
        /* MART.D_DEPT4_CD 재현 */
        SELECT
            B.DEPT_ID AS DEPT4_ID,
            B.DEPT_NM AS DEPT4_NM,
            B.SORT_ORDR
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO A
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO B
            ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
        WHERE A.UPPER_DEPT_ID = ''ZV000000''
          AND A.USE_YN = ''Y''
    
        UNION ALL
    
        SELECT
            ''Z~'' AS DEPT4_ID,
            ''없음'' AS DEPT4_NM,
            999 AS SORT_ORDR
    ),
    
    DSCNTC_KEY AS
    (
        /*
            회원번호와 중단일자가 같은 중단 이력이 여러 건이어도
            변동금액 데이터가 중복되지 않도록 키를 먼저 중복 제거
        */
        SELECT DISTINCT
            MBER_NO,
            SPNSR_DSCNTC_DE
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR_DSCNTC
        WHERE LEFT(SPNSR_DSCNTC_DE, 6) = :STDR_MT
    ),
    
    DSCNTC_RAW AS
    (
        /*
            FN_MM_SPNSR_DVLP의
            중단 데이터(DVLP_DIV_CD = ''5'') 산출 로직 재현
        */
        SELECT
            ROW_NUMBER() OVER
            (
                PARTITION BY
                    A.MBER_NO,
                    A.SPNSR_NO,
                    A.SPNSR_BSNS_NO,
                    LEFT(A.OCCRRNC_DE, 6)
                ORDER BY A.SER_NO DESC
            ) AS SNUM,
    
            SUM(
                CAST(A.SPNSR_AMT AS DECIMAL(38, 0))
            ) OVER
            (
                PARTITION BY
                    A.MBER_NO,
                    A.SPNSR_NO,
                    A.SPNSR_BSNS_NO,
                    LEFT(A.OCCRRNC_DE, 6)
            ) AS MAMT,
    
            LEFT(A.OCCRRNC_DE, 6) AS STRD_MT,
            A.OCCRRNC_DE,
            A.SER_NO,
            A.MBER_NO,
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.ACMSLT_DEPT_CD,
            A.SPNSR_BSNS_ID
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_DVLP_AMT A
        INNER JOIN DSCNTC_KEY B
            ON A.MBER_NO = B.MBER_NO
           AND A.OCCRRNC_DE = B.SPNSR_DSCNTC_DE
    
        WHERE A.DVLP_DIV_CD = ''5''
          AND LEFT(A.OCCRRNC_DE, 6) = :STDR_MT
    ),
    
    DSCNTC_MONTHLY AS
    (
        /*
            동일 회원·후원·후원사업의 월별 중단금액을 합산한 뒤
            가장 큰 SER_NO의 한 행만 유지
        */
        SELECT
            STRD_MT,
            OCCRRNC_DE,
            SER_NO,
            MBER_NO,
            SPNSR_NO,
            SPNSR_BSNS_NO,
            COALESCE(ACMSLT_DEPT_CD, ''Z~'') AS ACMSLT_DEPT_CD,
            SPNSR_BSNS_ID,
            MAMT AS SPNSR_AMT
        FROM DSCNTC_RAW
        WHERE SNUM = 1
    ),
    
    DETAIL_DATA AS
    (
        /* MART.F_MM_SPNSR_ACT 중단 데이터 생성 로직 재현 */
        SELECT
            A.STRD_MT,
    
            CASE
                WHEN S.CPR_DIV_CD = ''1'' THEN ''I''
                WHEN S.CPR_DIV_CD = ''2'' THEN ''S''
                ELSE S.CPR_DIV_CD
            END AS CPR_DIV_CD,
    
            A.SPNSR_BSNS_ID,
    
            /*
                중단 발생연도와 회원 최초등록연도가 같으면 신규,
                다르면 기존
            */
            CASE
                WHEN LEFT(A.OCCRRNC_DE, 4)
                     = TO_CHAR(M.FRST_REGIST_DT, ''YYYY'')
                THEN ''1''
                ELSE ''2''
            END AS NEW_OLD_DIV_CD,
    
            H.DEPT4_ID,
    
            /* DW의 SPNSR_AMT_CNT 산식 */
            CAST(
                CAST(A.SPNSR_AMT AS DECIMAL(38, 0)) / 10000.0
                AS DECIMAL(38, 4)
            ) AS SPNSR_AMT_CNT
    
        FROM DSCNTC_MONTHLY A
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_INFO M
            ON A.MBER_NO = M.MBER_NO
           AND TO_CHAR(M.FRST_REGIST_DT, ''YYYYMM'')
               <= :STDR_MT
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_CM_SPNSR_BSNS_INFO S
            ON A.SPNSR_BSNS_ID = S.SPNSR_BSNS_ID
    
        INNER JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR P
            ON A.MBER_NO = P.MBER_NO
           AND A.SPNSR_NO = P.SPNSR_NO
    
        LEFT JOIN DEPT_HIERARCHY H
            ON A.ACMSLT_DEPT_CD = H.SOURCE_DEPT_ID
    ),
    
    /* ============================================================
       기존/신규 + 본부/지부 기준으로 1차 집계
       기존은 여기서 HDQ_BRNCH_GRP_NM을 ''기존''으로 통합
       ============================================================ */
    FINAL_BASE AS
    (
        SELECT
            D.STRD_MT AS STDR_MT,
            C.CPR_DIV_NM AS CPR_NM,
    
            CASE
                WHEN S.SPNSR_BSNS_NM IN (
                    ''결식아동지원'',
                    ''국내아동권리보호사업(사단법인)'',
                    ''복지관후원'',
                    ''아동복지시설지원'',
                    ''아동학대예방'',
                    ''저소득가정지원''
                )
                    THEN ''국내(사단)''
                ELSE S.SPNSR_BSNS_NM
            END AS SPNSR_BSNS_GRP_NM,
    
            CASE D.NEW_OLD_DIV_CD
                WHEN ''1'' THEN ''신규''
                WHEN ''2'' THEN ''기존''
            END AS NEW_EXST_DIV_NM,
    
            CASE
                /* 기존은 본부/지부 구분 없이 한 행으로 통합 */
                WHEN D.NEW_OLD_DIV_CD = ''2''
                    THEN ''기존''
    
                /* 신규만 본부/지부 구분 */
                WHEN D4.DEPT4_NM IN (''본부'', ''본부(사복)'')
                    THEN ''본부''
    
                ELSE ''지부''
            END AS HDQ_BRNCH_GRP_NM,
    
            NVL(SUM(ABS(D.SPNSR_AMT_CNT)), 0) AS VALUE1
    
        FROM DETAIL_DATA D
    
        LEFT JOIN CPR_DIV_DIM C
            ON D.CPR_DIV_CD = C.CPR_DIV_CD
    
        LEFT JOIN SPNSR_BSNS_DIM S
            ON D.SPNSR_BSNS_ID = S.SPNSR_BSNS_ID
    
        LEFT JOIN DEPT4_DIM D4
            ON D.DEPT4_ID = D4.DEPT4_ID
    
        WHERE D.CPR_DIV_CD = ''I''
    
        GROUP BY
            D.STRD_MT,
            C.CPR_DIV_NM,
    
            CASE
                WHEN S.SPNSR_BSNS_NM IN (
                    ''결식아동지원'',
                    ''국내아동권리보호사업(사단법인)'',
                    ''복지관후원'',
                    ''아동복지시설지원'',
                    ''아동학대예방'',
                    ''저소득가정지원''
                )
                    THEN ''국내(사단)''
                ELSE S.SPNSR_BSNS_NM
            END,
    
            D.NEW_OLD_DIV_CD,
    
            CASE
                WHEN D.NEW_OLD_DIV_CD = ''2''
                    THEN ''기존''
    
                WHEN D4.DEPT4_NM IN (''본부'', ''본부(사복)'')
                    THEN ''본부''
    
                ELSE ''지부''
            END
    ),
    
    /* ============================================================
       실제 존재하는 후원사업 그룹 목록
       ============================================================ */
    SPNSR_BSNS_LIST AS
    (
        SELECT DISTINCT
            STDR_MT,
            CPR_NM,
            SPNSR_BSNS_GRP_NM
        FROM FINAL_BASE
    ),
    
    /* ============================================================
       후원사업별 반드시 생성할 3개 행
       1. 기존 / 기존
       2. 신규 / 본부
       3. 신규 / 지부
       ============================================================ */
    ROW_TYPE AS
    (
        SELECT
            ''기존'' AS NEW_EXST_DIV_NM,
            ''기존'' AS HDQ_BRNCH_GRP_NM
    
        UNION ALL
    
        SELECT
            ''신규'' AS NEW_EXST_DIV_NM,
            ''본부'' AS HDQ_BRNCH_GRP_NM
    
        UNION ALL
    
        SELECT
            ''신규'' AS NEW_EXST_DIV_NM,
            ''지부'' AS HDQ_BRNCH_GRP_NM
    ),
    
    /* ============================================================
       후원사업별 무조건 3행 생성
       데이터가 없는 조합은 VALUE1 = 0
       ============================================================ */
    FINAL_RESULT AS
    (
        SELECT
            A.STDR_MT,
            A.CPR_NM,
            A.SPNSR_BSNS_GRP_NM,
            B.NEW_EXST_DIV_NM,
            B.HDQ_BRNCH_GRP_NM,
    
            NVL(C.VALUE1, 0) AS VALUE1
    
        FROM SPNSR_BSNS_LIST A
    
        CROSS JOIN ROW_TYPE B
    
        LEFT JOIN FINAL_BASE C
            ON C.STDR_MT = A.STDR_MT
           AND C.CPR_NM = A.CPR_NM
           AND C.SPNSR_BSNS_GRP_NM = A.SPNSR_BSNS_GRP_NM
           AND C.NEW_EXST_DIV_NM = B.NEW_EXST_DIV_NM
           AND C.HDQ_BRNCH_GRP_NM = B.HDQ_BRNCH_GRP_NM
    )
    
    /* ============================================================
       최종 결과
       ============================================================ */
    SELECT
        STDR_MT,
        :AGGR_TY_NM AS AGGR_TY_NM,
        CPR_NM,
        SPNSR_BSNS_GRP_NM,
        NEW_EXST_DIV_NM,
        HDQ_BRNCH_GRP_NM,
        VALUE1,
        NULL AS VALUE2
    FROM FINAL_RESULT
    
    ORDER BY
        CPR_NM,
        SPNSR_BSNS_GRP_NM,
        CASE
            WHEN NEW_EXST_DIV_NM = ''기존''
                THEN 1
            WHEN NEW_EXST_DIV_NM = ''신규''
             AND HDQ_BRNCH_GRP_NM = ''본부''
                THEN 2
            WHEN NEW_EXST_DIV_NM = ''신규''
             AND HDQ_BRNCH_GRP_NM = ''지부''
                THEN 3
        END;
    RETURN ''SUCCESS: '' || :STDR_MT;
END;
';
CREATE OR REPLACE PROCEDURE GN_DW.SILVER.SP_INSERT_MM_SPNSR_CLS_AGGR_DATA3("INPUT_YYYYMM" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS CALLER
AS '
DECLARE
    STDR_MT VARCHAR;
    FRST_MT VARCHAR;
    STDR_MT_01 VARCHAR;
    STDR_MT_31 VARCHAR;
    STDR_MT_END_DT VARCHAR;
    AGGR_TY_NM VARCHAR;
BEGIN
    -- 0. 파라미터
    IF (NOT REGEXP_LIKE(input_yyyymm, ''^[0-9]{6}$'')) THEN
        RETURN ''ERROR: input_yyyymm은 YYYYMM 형식이어야 합니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'') IS NULL) THEN
        RETURN ''ERROR: 유효하지 않은 년월입니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (
        TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'')
        > DATE_TRUNC(''MONTH'', CURRENT_DATE())
    ) THEN
        RETURN ''ERROR: 미래 년월은 입력할 수 없습니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    STDR_MT := input_yyyymm;
    FRST_MT := LEFT(:STDR_MT, 4) || ''01'';
    STDR_MT_01 := :STDR_MT || ''01'';
    STDR_MT_31 := :STDR_MT || ''31'';
    STDR_MT_END_DT := TO_CHAR(
        LAST_DAY(TO_DATE(:STDR_MT || ''01'', ''YYYYMMDD'')),
        ''YYYYMMDD''
    );
    AGGR_TY_NM := ''감액'';
    
    DELETE
    FROM GN_DW.SILVER.MM_SPNSR_CLS_AGGR_DATA
    WHERE STDR_MT = :STDR_MT
    AND AGGR_TY_NM = :AGGR_TY_NM;
    INSERT INTO GN_DW.SILVER.MM_SPNSR_CLS_AGGR_DATA
    WITH
    /* =========================================================
       1. 실적부서 → DEPT4
       ========================================================= */
    DEPT_MAP AS (
        SELECT
            E.DEPT_ID AS SRC_DEPT_ID,
            D.DEPT_ID AS DEPT2_ID,
            C.DEPT_ID AS DEPT3_ID,
            B.DEPT_ID AS DEPT4_ID
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO A
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO B
          ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO C
          ON C.ACMSLT_UPPER_DEPT_ID = B.DEPT_ID
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO D
          ON D.ACMSLT_UPPER_DEPT_ID = C.DEPT_ID
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO E
          ON E.ACMSLT_UPPER_DEPT_ID = D.DEPT_ID
        WHERE A.UPPER_DEPT_ID = ''ZV000000''
          AND C.DEPT_ID <> ''ZC000029''
    
        UNION ALL
    
        SELECT
            ''Z~'',
            ''Z~'',
            ''Z~'',
            ''Z~''
    ),
    
    /* =========================================================
       2. DEPT4 차원
       ========================================================= */
    DEPT4_DIM AS (
        SELECT
            B.DEPT_ID AS DEPT4_ID,
            B.DEPT_NM AS DEPT4_NM,
            B.SORT_ORDR
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO A
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO B
          ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
        WHERE A.UPPER_DEPT_ID = ''ZV000000''
          AND A.USE_YN = ''Y''
    
        UNION ALL
    
        SELECT
            ''Z~'',
            ''없음'',
            999
    ),
    
    /* =========================================================
       3. 법인 구분
       ========================================================= */
    CPR_DIM AS (
        SELECT DISTINCT
            D.DTL_CD_ID AS CPR_DIV_CD,
            D.DTL_CD_NM AS CPR_DIV_NM,
            D.SORT_ORDR
        FROM GN_DW.BRONZE_CRM.TC_CMMN_CD C
        JOIN GN_DW.BRONZE_CRM.TC_CMMN_DTL_CD D
          ON C.CD_ID = D.CD_ID
        WHERE D.CD_ID = ''CM019''
    ),
    
    /* =========================================================
       4. 후원사업
       ========================================================= */
    BUSINESS_DIM AS (
        SELECT
            S.SPNSR_BSNS_ID,
            S.SPNSR_BSNS_NM,
            S.SPNSR_BSNS_ABRV_CD,
            S.SORT_ORDR,
            CASE
                WHEN S.CPR_DIV_CD = ''1'' THEN ''I''
                WHEN S.CPR_DIV_CD = ''2'' THEN ''S''
                ELSE S.CPR_DIV_CD
            END AS CPR_DIV_CD
        FROM GN_DW.BRONZE_CRM.TM_CM_SPNSR_BSNS_INFO S
    
        UNION ALL
    
        SELECT
            ''99'',
            ''없음'',
            ''99'',
            999,
            ''Z''
        WHERE NOT EXISTS (
            SELECT 1
            FROM GN_DW.BRONZE_CRM.TM_CM_SPNSR_BSNS_INFO
            WHERE SPNSR_BSNS_ID = ''99''
        )
    ),
    
    /* =========================================================
       5. 회원
       ========================================================= */
    MEMBER_MONTH AS (
        SELECT
            M.MBER_NO,
            M.FRST_REGIST_DT
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_INFO M
        WHERE TO_CHAR(M.FRST_REGIST_DT, ''YYYYMM'') <= :STDR_MT
    ),
    
    /* =========================================================
       6. 결제정보
       ========================================================= */
    SETLE_MONTH AS (
        SELECT
            MBER_NO,
            CPR_DIV_CD
        FROM (
            SELECT
                U.MBER_NO,
                U.CPR_DIV_CD,
                ROW_NUMBER() OVER (
                    PARTITION BY
                        U.MBER_NO,
                        U.CPR_DIV_CD
                    ORDER BY U.SETLE_KEY DESC
                ) AS RNUM
            FROM (
                SELECT
                    SETLE_KEY,
                    MBER_NO,
                    CPR_DIV_CD,
                    FRST_REGIST_DT
                FROM GN_DW.BRONZE_CRM.TM_PM_SETLE_INFO
    
                UNION ALL
    
                SELECT
                    SETLE_KEY,
                    MBER_NO,
                    CPR_DIV_CD,
                    REGIST_DT
                FROM GN_DW.BRONZE_CRM.TH_PM_SETLE_INFO_HIST
            ) U
            WHERE U.FRST_REGIST_DT <= DATEADD(
                DAY,
                1,
                DATEADD(
                    MONTH,
                    1,
                    TO_DATE(:STDR_MT_01, ''YYYYMMDD'')
                )
            )
        )
        WHERE RNUM = 1
    ),
    
    /* =========================================================
       7. 활동회원
       ========================================================= */
    LAST_DSCNTC AS (
        SELECT
            D.MBER_NO,
            D.SPNSR_DSCNTC_DE,
            ROW_NUMBER() OVER (
                PARTITION BY D.MBER_NO
                ORDER BY D.SPNSR_DSCNTC_DE DESC
            ) AS RNUM
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR_DSCNTC D
        WHERE D.SPNSR_DSCNTC_DE <= :STDR_MT_31
    ),
    
    LAST_RE_SPNSR AS (
        SELECT
            R.MBER_NO,
            R.RE_SPNSR_DE,
            ROW_NUMBER() OVER (
                PARTITION BY R.MBER_NO
                ORDER BY R.RE_SPNSR_DE DESC
            ) AS RNUM
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_RE_SPNSR R
        WHERE R.RE_SPNSR_DE <= :STDR_MT_31
    ),
    
    LAST_ACTIVITY_DATE AS (
        SELECT
            D.MBER_NO,
            CASE
                WHEN R.RE_SPNSR_DE IS NULL
                    THEN DATEADD(
                        DAY,
                        -1,
                        TO_DATE(D.SPNSR_DSCNTC_DE, ''YYYYMMDD'')
                    )
    
                WHEN D.SPNSR_DSCNTC_DE > R.RE_SPNSR_DE
                    THEN DATEADD(
                        DAY,
                        -1,
                        TO_DATE(D.SPNSR_DSCNTC_DE, ''YYYYMMDD'')
                    )
    
                WHEN R.RE_SPNSR_DE < :STDR_MT_END_DT
                    THEN TO_DATE(:STDR_MT_END_DT, ''YYYYMMDD'')
    
                ELSE TO_DATE(R.RE_SPNSR_DE, ''YYYYMMDD'')
            END AS ACTUAL_DT
    
        FROM LAST_DSCNTC D
    
        LEFT JOIN LAST_RE_SPNSR R
          ON D.MBER_NO = R.MBER_NO
         AND R.RNUM = 1
    
        WHERE D.RNUM = 1
    ),
    
    HAS_LIVE_SPONSOR AS (
        SELECT DISTINCT
            S.MBER_NO
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR S
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR_BSNS B
          ON S.SPNSR_NO = B.SPNSR_NO
        WHERE TO_CHAR(S.FRST_REGIST_DT, ''YYYYMMDD'') <= :STDR_MT_31
          AND COALESCE(B.SPNSR_DSCNTC_DE, ''99991231'') > :STDR_MT_31
    ),
    
    ACTIVE_MEMBER AS (
        SELECT
            M.MBER_NO
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_INFO M
        JOIN HAS_LIVE_SPONSOR L
          ON M.MBER_NO = L.MBER_NO
        LEFT JOIN LAST_ACTIVITY_DATE A
          ON M.MBER_NO = A.MBER_NO
        WHERE TO_DATE(:STDR_MT_END_DT, ''YYYYMMDD'')
              BETWEEN TO_DATE(M.FRST_REGIST_DT)
              AND COALESCE(
                    A.ACTUAL_DT,
                    TO_DATE(''9999-12-31'')
                  )
    ),
    
    /* =========================================================
       8. 감액 원천
       ========================================================= */
    DECREASE_SOURCE AS (
        SELECT
            LEFT(A.OCCRRNC_DE, 6) AS STRD_MT,
            A.OCCRRNC_DE,
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.SER_NO,
            A.MBER_NO,
            A.ACMSLT_DEPT_CD,
            A.SPNSR_BSNS_ID,
    
            SUM(A.SPNSR_AMT) OVER (
                PARTITION BY
                    A.MBER_NO,
                    LEFT(A.OCCRRNC_DE, 6)
            ) AS MAMT,
    
            ROW_NUMBER() OVER (
                PARTITION BY
                    A.MBER_NO,
                    LEFT(A.OCCRRNC_DE, 6)
                ORDER BY
                    A.SPNSR_NO DESC,
                    A.OCCRRNC_DE DESC,
                    A.SER_NO DESC,
                    A.SPNSR_BSNS_NO DESC
            ) AS SNUM
    
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_DVLP_AMT A
    
        WHERE A.DVLP_DIV_CD IN (''2'', ''3'')
          AND LEFT(A.OCCRRNC_DE, 6)
              BETWEEN :FRST_MT AND :STDR_MT
    ),
    
    /* =========================================================
       9. 감액 팩트
       ========================================================= */
    DECREASE_FACT AS (
        SELECT
            D.STRD_MT,
            D.SPNSR_NO,
            D.SPNSR_BSNS_NO,
            D.MBER_NO,
            D.SPNSR_BSNS_ID,
            B.CPR_DIV_CD,
            MAP.DEPT4_ID,
    
            CASE
                WHEN TO_CHAR(M.FRST_REGIST_DT, ''YYYY'')
                        = LEFT(:STDR_MT, 4)
                 AND TO_CHAR(S.FRST_REGIST_DT, ''YYYY'')
                        = LEFT(:STDR_MT, 4)
                    THEN ''1''
                ELSE ''2''
            END AS NEW_OLD_DIV_CD,
    
            D.MAMT AS SPNSR_AMT,
            D.MAMT / 10000.0 AS SPNSR_AMT_CNT
    
        FROM DECREASE_SOURCE D
    
        JOIN MEMBER_MONTH M
          ON D.MBER_NO = M.MBER_NO
    
        JOIN BUSINESS_DIM B
          ON D.SPNSR_BSNS_ID = B.SPNSR_BSNS_ID
    
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR S
          ON D.MBER_NO = S.MBER_NO
         AND D.SPNSR_NO = S.SPNSR_NO
    
        LEFT JOIN DEPT_MAP MAP
          ON COALESCE(D.ACMSLT_DEPT_CD, ''Z~'')
           = MAP.SRC_DEPT_ID
    
        WHERE D.MAMT < 0
          AND D.SNUM = 1
    ),
    
    /* =========================================================
       10. 활동 팩트
       ========================================================= */
    ACTIVE_HISTORY AS (
        SELECT
            A.OCCRRNC_DE,
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.SER_NO,
            A.MBER_NO,
            A.SPNSR_BSNS_ID,
    
            SUM(A.SPNSR_AMT) OVER (
                PARTITION BY
                    A.SPNSR_NO,
                    A.SPNSR_BSNS_NO
            ) AS SUM_AMT,
    
            ROW_NUMBER() OVER (
                PARTITION BY
                    A.SPNSR_NO,
                    A.SPNSR_BSNS_NO
                ORDER BY
                    A.OCCRRNC_DE DESC,
                    A.SER_NO DESC
            ) AS RNUM
    
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_DVLP_AMT A
    
        WHERE A.OCCRRNC_DE <= :STDR_MT_31
    ),
    
    ACTIVE_FACT AS (
        SELECT
            :STDR_MT AS STRD_MT,
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.MBER_NO,
            A.SPNSR_BSNS_ID,
            COALESCE(P.CPR_DIV_CD, ''I'')
                AS CPR_DIV_CD,
            MAP.DEPT4_ID,
    
            CASE
                WHEN TO_CHAR(M.FRST_REGIST_DT, ''YYYY'')
                        = LEFT(:STDR_MT, 4)
                 AND TO_CHAR(S.FRST_REGIST_DT, ''YYYY'')
                        = LEFT(:STDR_MT, 4)
                    THEN ''1''
                ELSE ''2''
            END AS NEW_OLD_DIV_CD,
    
            A.SUM_AMT AS SPNSR_AMT,
            A.SUM_AMT / 10000.0 AS SPNSR_AMT_CNT
    
        FROM ACTIVE_HISTORY A
    
        JOIN ACTIVE_MEMBER AM
          ON A.MBER_NO = AM.MBER_NO
    
        JOIN MEMBER_MONTH M
          ON A.MBER_NO = M.MBER_NO
    
        JOIN BUSINESS_DIM B
          ON A.SPNSR_BSNS_ID = B.SPNSR_BSNS_ID
    
        LEFT JOIN SETLE_MONTH P
          ON A.MBER_NO = P.MBER_NO
         AND B.CPR_DIV_CD = P.CPR_DIV_CD
    
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR S
          ON A.MBER_NO = S.MBER_NO
         AND A.SPNSR_NO = S.SPNSR_NO
    
        LEFT JOIN DEPT_MAP MAP
          ON COALESCE(S.ACMSLT_DEPT_CD, ''Z~'')
           = MAP.SRC_DEPT_ID
    
        WHERE A.RNUM = 1
          AND A.SUM_AMT > 0
    ),
    
    /* =========================================================
       11. 당월 감액
       ========================================================= */
    MONTH_DECREASE AS (
        SELECT
            SPNSR_BSNS_ID,
            NEW_OLD_DIV_CD,
            DEPT4_ID,
            CPR_DIV_CD,
            STRD_MT,
    
            COUNT(DISTINCT MBER_NO) AS WJXBFS1,
            SUM(ABS(SPNSR_AMT_CNT)) AS WJXBFS2
    
        FROM DECREASE_FACT
    
        WHERE STRD_MT = :STDR_MT
    
        GROUP BY
            SPNSR_BSNS_ID,
            NEW_OLD_DIV_CD,
            DEPT4_ID,
            CPR_DIV_CD,
            STRD_MT
    ),
    
    /* =========================================================
       12. YTD 감액
       ========================================================= */
    YTD_DECREASE AS (
        SELECT
            SPNSR_BSNS_ID,
            NEW_OLD_DIV_CD,
            DEPT4_ID,
            CPR_DIV_CD,
            :STDR_MT AS STRD_MT,
    
            COUNT(DISTINCT MBER_NO) AS WJXBFS1,
            SUM(ABS(SPNSR_AMT_CNT)) AS WJXBFS2
    
        FROM DECREASE_FACT
    
        WHERE STRD_MT
              BETWEEN :FRST_MT AND :STDR_MT
    
        GROUP BY
            SPNSR_BSNS_ID,
            NEW_OLD_DIV_CD,
            DEPT4_ID,
            CPR_DIV_CD
    ),
    
    /* =========================================================
       13. 기준월 활동
       ========================================================= */
    MONTH_ACTIVE AS (
        SELECT
            SPNSR_BSNS_ID,
            NEW_OLD_DIV_CD,
            DEPT4_ID,
            CPR_DIV_CD,
            STRD_MT,
    
            COUNT(DISTINCT MBER_NO) AS WJXBFS1,
            SUM(SPNSR_AMT_CNT) AS WJXBFS2
    
        FROM ACTIVE_FACT
    
        GROUP BY
            SPNSR_BSNS_ID,
            NEW_OLD_DIV_CD,
            DEPT4_ID,
            CPR_DIV_CD,
            STRD_MT
    ),
    
    /* =========================================================
       14. 기존 RST 생성
       ========================================================= */
    RST AS (
        SELECT
    
            COALESCE(
                MD.STRD_MT,
                YD.STRD_MT,
                MA.STRD_MT
            ) AS STRD_MT,
    
            CPR.CPR_DIV_NM,
    
            BSNS.SPNSR_BSNS_NM,
    
            CASE
                WHEN COALESCE(
                    MD.NEW_OLD_DIV_CD,
                    YD.NEW_OLD_DIV_CD,
                    MA.NEW_OLD_DIV_CD
                ) = ''1''
                    THEN ''신규''
    
                WHEN COALESCE(
                    MD.NEW_OLD_DIV_CD,
                    YD.NEW_OLD_DIV_CD,
                    MA.NEW_OLD_DIV_CD
                ) = ''2''
                    THEN ''기존''
    
                ELSE ''없음''
            END AS NEW_OLD_DIV_NM,
    
            D4.DEPT4_NM,
    
            MD.WJXBFS1 AS WJXBFS1,
            MD.WJXBFS2 AS WJXBFS2,
            YD.WJXBFS1 AS WJXBFS3,
            YD.WJXBFS2 AS WJXBFS4,
            MA.WJXBFS1 AS WJXBFS5,
            MA.WJXBFS2 AS WJXBFS6
    
        FROM MONTH_DECREASE MD
    
        FULL OUTER JOIN YTD_DECREASE YD
          ON MD.CPR_DIV_CD = YD.CPR_DIV_CD
         AND MD.DEPT4_ID = YD.DEPT4_ID
         AND MD.NEW_OLD_DIV_CD = YD.NEW_OLD_DIV_CD
         AND MD.SPNSR_BSNS_ID = YD.SPNSR_BSNS_ID
         AND MD.STRD_MT = YD.STRD_MT
    
        FULL OUTER JOIN MONTH_ACTIVE MA
          ON COALESCE(
                MD.CPR_DIV_CD,
                YD.CPR_DIV_CD
             ) = MA.CPR_DIV_CD
    
         AND COALESCE(
                MD.DEPT4_ID,
                YD.DEPT4_ID
             ) = MA.DEPT4_ID
    
         AND COALESCE(
                MD.NEW_OLD_DIV_CD,
                YD.NEW_OLD_DIV_CD
             ) = MA.NEW_OLD_DIV_CD
    
         AND COALESCE(
                MD.SPNSR_BSNS_ID,
                YD.SPNSR_BSNS_ID
             ) = MA.SPNSR_BSNS_ID
    
         AND COALESCE(
                MD.STRD_MT,
                YD.STRD_MT
             ) = MA.STRD_MT
    
        LEFT JOIN CPR_DIM CPR
          ON COALESCE(
                MD.CPR_DIV_CD,
                YD.CPR_DIV_CD,
                MA.CPR_DIV_CD
             ) = CPR.CPR_DIV_CD
    
        LEFT JOIN BUSINESS_DIM BSNS
          ON COALESCE(
                MD.SPNSR_BSNS_ID,
                YD.SPNSR_BSNS_ID,
                MA.SPNSR_BSNS_ID
             ) = BSNS.SPNSR_BSNS_ID
    
        LEFT JOIN DEPT4_DIM D4
          ON COALESCE(
                MD.DEPT4_ID,
                YD.DEPT4_ID,
                MA.DEPT4_ID
             ) = D4.DEPT4_ID
    
        WHERE COALESCE(
                MD.CPR_DIV_CD,
                YD.CPR_DIV_CD,
                MA.CPR_DIV_CD
              ) = ''I''
    ),
    
    /* =========================================================
       15. 후원사업 그룹
       후원사업별 실제 존재 데이터 기준
       ========================================================= */
    BUSINESS_GROUP AS (
        SELECT DISTINCT
            STRD_MT,
            CPR_DIV_NM,
            CASE
                WHEN SPNSR_BSNS_NM IN (
                    ''결식아동지원'',
                    ''국내아동권리보호사업(사단법인)'',
                    ''복지관후원'',
                    ''아동복지시설지원'',
                    ''아동학대예방'',
                    ''저소득가정지원''
                )
                    THEN ''국내(사단)''
                ELSE SPNSR_BSNS_NM
            END AS SPNSR_BSNS_GRP_NM
        FROM RST
    ),
    
    /* =========================================================
       16. 원하는 3개 구분 생성
       기존      → 기존
       신규+본부 → 신규 / 본부
       신규+지부 → 신규 / 지부
       ========================================================= */
    ROW_TYPE AS (
        SELECT
            ''기존'' AS NEW_EXST_DIV_NM,
            ''기존'' AS HDQ_BRNCH_GRP_NM
    
        UNION ALL
    
        SELECT
            ''신규'' AS NEW_EXST_DIV_NM,
            ''본부'' AS HDQ_BRNCH_GRP_NM
    
        UNION ALL
    
        SELECT
            ''신규'' AS NEW_EXST_DIV_NM,
            ''지부'' AS HDQ_BRNCH_GRP_NM
    ),
    
    /* =========================================================
       17. 후원사업 그룹 × 3개 구분
       → 사업그룹별 무조건 3행 생성
       ========================================================= */
    TARGET_ROWS AS (
        SELECT
            B.STRD_MT,
            B.CPR_DIV_NM,
            B.SPNSR_BSNS_GRP_NM,
            R.NEW_EXST_DIV_NM,
            R.HDQ_BRNCH_GRP_NM
        FROM BUSINESS_GROUP B
        CROSS JOIN ROW_TYPE R
    ),
    
    /* =========================================================
       18. 실제 데이터 집계
       기존은 본부/지부를 합산
       신규는 본부/지부를 각각 집계
       ========================================================= */
    FINAL_AGGR AS (
        SELECT
            STRD_MT,
            CPR_DIV_NM,
    
            CASE
                WHEN SPNSR_BSNS_NM IN (
                    ''결식아동지원'',
                    ''국내아동권리보호사업(사단법인)'',
                    ''복지관후원'',
                    ''아동복지시설지원'',
                    ''아동학대예방'',
                    ''저소득가정지원''
                )
                    THEN ''국내(사단)''
                ELSE SPNSR_BSNS_NM
            END AS SPNSR_BSNS_GRP_NM,
    
            /* 기존은 본부/지부 무관하게 하나로 통합 */
            CASE
                WHEN NEW_OLD_DIV_NM = ''기존''
                    THEN ''기존''
                ELSE ''신규''
            END AS NEW_EXST_DIV_NM,
    
            /* 기존은 ''기존'', 신규는 실제 본부/지부 */
            CASE
                WHEN NEW_OLD_DIV_NM = ''기존''
                    THEN ''기존''
    
                WHEN NEW_OLD_DIV_NM = ''신규''
                 AND DEPT4_NM IN (''본부'', ''본부(사복)'')
                    THEN ''본부''
    
                WHEN NEW_OLD_DIV_NM = ''신규''
                    THEN ''지부''
    
                ELSE ''기타''
            END AS HDQ_BRNCH_GRP_NM,
    
            SUM(WJXBFS2) AS VALUE1
    
        FROM RST
    
        GROUP BY
            STRD_MT,
            CPR_DIV_NM,
    
            CASE
                WHEN SPNSR_BSNS_NM IN (
                    ''결식아동지원'',
                    ''국내아동권리보호사업(사단법인)'',
                    ''복지관후원'',
                    ''아동복지시설지원'',
                    ''아동학대예방'',
                    ''저소득가정지원''
                )
                    THEN ''국내(사단)''
                ELSE SPNSR_BSNS_NM
            END,
    
            CASE
                WHEN NEW_OLD_DIV_NM = ''기존''
                    THEN ''기존''
                ELSE ''신규''
            END,
    
            CASE
                WHEN NEW_OLD_DIV_NM = ''기존''
                    THEN ''기존''
    
                WHEN NEW_OLD_DIV_NM = ''신규''
                 AND DEPT4_NM IN (''본부'', ''본부(사복)'')
                    THEN ''본부''
    
                WHEN NEW_OLD_DIV_NM = ''신규''
                    THEN ''지부''
    
                ELSE ''기타''
            END
    )
    
    /* =========================================================
       19. 최종 결과
       사업그룹별 반드시 3행
       ========================================================= */
    SELECT
        T.STRD_MT,
        :AGGR_TY_NM AS AGGR_TY_NM,
        T.CPR_DIV_NM,
        T.SPNSR_BSNS_GRP_NM,
        T.NEW_EXST_DIV_NM,
        T.HDQ_BRNCH_GRP_NM,
        NVL(F.VALUE1, 0) AS VALUE1,
        NULL AS VALUE2
    
    FROM TARGET_ROWS T
    
    LEFT JOIN FINAL_AGGR F
      ON T.STRD_MT = F.STRD_MT
     AND T.CPR_DIV_NM = F.CPR_DIV_NM
     AND T.SPNSR_BSNS_GRP_NM = F.SPNSR_BSNS_GRP_NM
     AND T.NEW_EXST_DIV_NM = F.NEW_EXST_DIV_NM
     AND T.HDQ_BRNCH_GRP_NM = F.HDQ_BRNCH_GRP_NM
    
    ORDER BY
        T.STRD_MT,
        T.CPR_DIV_NM,
        T.SPNSR_BSNS_GRP_NM,
        CASE
            WHEN T.NEW_EXST_DIV_NM = ''기존'' THEN 1
            WHEN T.NEW_EXST_DIV_NM = ''신규''
             AND T.HDQ_BRNCH_GRP_NM = ''본부'' THEN 2
            WHEN T.NEW_EXST_DIV_NM = ''신규''
             AND T.HDQ_BRNCH_GRP_NM = ''지부'' THEN 3
            ELSE 9
        END;
    
    RETURN ''SUCCESS: '' || :STDR_MT;
END;
';
CREATE OR REPLACE PROCEDURE GN_DW.SILVER.SP_INSERT_MM_SPNSR_CLS_AGGR_DATA4("INPUT_YYYYMM" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS CALLER
AS '
DECLARE
    STDR_MT VARCHAR;
    AGGR_TY_NM VARCHAR;
BEGIN
    -- 0. 파라미터
    IF (NOT REGEXP_LIKE(input_yyyymm, ''^[0-9]{6}$'')) THEN
        RETURN ''ERROR: input_yyyymm은 YYYYMM 형식이어야 합니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'') IS NULL) THEN
        RETURN ''ERROR: 유효하지 않은 년월입니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (
        TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'')
        > DATE_TRUNC(''MONTH'', CURRENT_DATE())
    ) THEN
        RETURN ''ERROR: 미래 년월은 입력할 수 없습니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    STDR_MT := input_yyyymm;
    AGGR_TY_NM := ''활동'';
    /* ============================================================
       1. 전체 데이터 구성
    ============================================================ */
    
    DELETE
    FROM GN_DW.SILVER.MM_SPNSR_CLS_AGGR_DATA
    WHERE STDR_MT = :STDR_MT
    AND AGGR_TY_NM = :AGGR_TY_NM;
    INSERT INTO GN_DW.SILVER.MM_SPNSR_CLS_AGGR_DATA
    WITH
    /* =========================================================================
       0. 파라미터
       ========================================================================= */
    PARAMS AS
    (
        SELECT
            :STDR_MT AS STRD_MT,
            ''I''::VARCHAR AS CPR_DIV_CD
    ),
    
    PARAM_DATES AS
    (
        SELECT
            STRD_MT,
            CPR_DIV_CD,
    
            STRD_MT || ''31'' AS MONTH_31,
    
            LAST_DAY(
                TO_DATE(STRD_MT || ''01'', ''YYYYMMDD'')
            ) AS MONTH_END,
    
            DATEADD(
                ''DAY'',
                1,
                DATEADD(
                    ''MONTH'',
                    1,
                    TO_DATE(STRD_MT || ''01'', ''YYYYMMDD'')
                )
            ) AS SETLE_CUTOFF
    
        FROM PARAMS
    ),
    
    /* =========================================================================
       1. 실적부서 -> 본부/지부(DEPT4) 매핑
       ========================================================================= */
    DEPT_MAP_BASE AS
    (
        SELECT
            E.DEPT_ID AS SRC_DEPT_ID,
            B.DEPT_ID AS DEPT4_ID
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO A
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO B
          ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO C
          ON C.ACMSLT_UPPER_DEPT_ID = B.DEPT_ID
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO D
          ON D.ACMSLT_UPPER_DEPT_ID = C.DEPT_ID
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO E
          ON E.ACMSLT_UPPER_DEPT_ID = D.DEPT_ID
        WHERE A.UPPER_DEPT_ID = ''ZV000000''
          AND C.DEPT_ID <> ''ZC000029''
    ),
    
    DEPT_MAP AS
    (
        SELECT
            SRC_DEPT_ID,
            DEPT4_ID
        FROM DEPT_MAP_BASE
    
        UNION ALL
    
        SELECT
            ''Z~'' AS SRC_DEPT_ID,
            ''Z~'' AS DEPT4_ID
    ),
    
    /* =========================================================================
       2. DEPT4 차원
       ========================================================================= */
    DEPT4_DIM_BASE AS
    (
        SELECT
            B.DEPT_ID AS DEPT4_ID,
            B.DEPT_NM AS DEPT4_NM,
            B.SORT_ORDR
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO A
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO B
          ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
        WHERE A.UPPER_DEPT_ID = ''ZV000000''
          AND A.USE_YN = ''Y''
    ),
    
    DEPT4_DIM AS
    (
        SELECT
            DEPT4_ID,
            DEPT4_NM,
            SORT_ORDR
        FROM DEPT4_DIM_BASE
    
        UNION ALL
    
        SELECT
            ''Z~'' AS DEPT4_ID,
            ''없음'' AS DEPT4_NM,
            999 AS SORT_ORDR
    ),
    
    /* =========================================================================
       3. 법인 차원
       ========================================================================= */
    CPR_DIM AS
    (
        SELECT DISTINCT
            D.DTL_CD_ID AS CPR_DIV_CD,
            D.DTL_CD_NM AS CPR_DIV_NM,
            D.SORT_ORDR
        FROM GN_DW.BRONZE_CRM.TC_CMMN_CD C
        JOIN GN_DW.BRONZE_CRM.TC_CMMN_DTL_CD D
          ON C.CD_ID = D.CD_ID
        WHERE D.CD_ID = ''CM019''
    ),
    
    /* =========================================================================
       4. 후원사업 차원
       ========================================================================= */
    BUSINESS_DIM_BASE AS
    (
        SELECT
            S.SPNSR_BSNS_ID,
            S.SPNSR_BSNS_NM,
            S.SORT_ORDR,
    
            CASE
                WHEN S.CPR_DIV_CD = ''1'' THEN ''I''
                WHEN S.CPR_DIV_CD = ''2'' THEN ''S''
                ELSE S.CPR_DIV_CD
            END AS CPR_DIV_CD
    
        FROM GN_DW.BRONZE_CRM.TM_CM_SPNSR_BSNS_INFO S
    ),
    
    BUSINESS_DIM AS
    (
        SELECT
            SPNSR_BSNS_ID,
            SPNSR_BSNS_NM,
            SORT_ORDR,
            CPR_DIV_CD
        FROM BUSINESS_DIM_BASE
    
        UNION ALL
    
        SELECT
            ''99'' AS SPNSR_BSNS_ID,
            ''없음'' AS SPNSR_BSNS_NM,
            999 AS SORT_ORDR,
            ''Z'' AS CPR_DIV_CD
    
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM BUSINESS_DIM_BASE
            WHERE SPNSR_BSNS_ID = ''99''
        )
    ),
    
    /* =========================================================================
       5. 회원+후원사업법인별 기준월 최신 결제정보
       ========================================================================= */
    SETLE_RANKED AS
    (
        SELECT
            U.MBER_NO,
            U.CPR_DIV_CD,
    
            ROW_NUMBER() OVER
            (
                PARTITION BY
                    U.MBER_NO,
                    U.CPR_DIV_CD
                ORDER BY
                    U.SETLE_KEY DESC
            ) AS RNUM
    
        FROM
        (
            SELECT
                1 AS SETLE_DIV_CD,
                SETLE_KEY,
                MBER_NO,
                CPR_DIV_CD,
                FRST_REGIST_DT
            FROM GN_DW.BRONZE_CRM.TM_PM_SETLE_INFO
    
            UNION ALL
    
            SELECT
                2 AS SETLE_DIV_CD,
                SETLE_KEY,
                MBER_NO,
                CPR_DIV_CD,
                REGIST_DT
            FROM GN_DW.BRONZE_CRM.TH_PM_SETLE_INFO_HIST
        ) U
    
        CROSS JOIN PARAM_DATES P
    
        WHERE U.FRST_REGIST_DT <= P.SETLE_CUTOFF
    ),
    
    SETLE_MONTH AS
    (
        SELECT
            MBER_NO,
            CPR_DIV_CD
        FROM SETLE_RANKED
        WHERE RNUM = 1
    ),
    
    /* =========================================================================
       6. 기준월 말 활동회원
       ========================================================================= */
    
    LAST_DSCNTC AS
    (
        SELECT
            D.MBER_NO,
            D.SPNSR_DSCNTC_DE,
    
            ROW_NUMBER() OVER
            (
                PARTITION BY D.MBER_NO
                ORDER BY D.SPNSR_DSCNTC_DE DESC
            ) AS RNUM
    
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR_DSCNTC D
        CROSS JOIN PARAM_DATES P
    
        WHERE D.SPNSR_DSCNTC_DE <= P.MONTH_31
    ),
    
    LAST_RE_SPNSR AS
    (
        SELECT
            R.MBER_NO,
            R.RE_SPNSR_DE,
    
            ROW_NUMBER() OVER
            (
                PARTITION BY R.MBER_NO
                ORDER BY R.RE_SPNSR_DE DESC
            ) AS RNUM
    
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_RE_SPNSR R
        CROSS JOIN PARAM_DATES P
    
        WHERE R.RE_SPNSR_DE <= P.MONTH_31
    ),
    
    LAST_ACTIVITY_DATE AS
    (
        SELECT
            D.MBER_NO,
    
            CASE
                WHEN R.RE_SPNSR_DE IS NULL
                    THEN DATEADD(
                        ''DAY'',
                        -1,
                        TO_DATE(D.SPNSR_DSCNTC_DE, ''YYYYMMDD'')
                    )
    
                WHEN D.SPNSR_DSCNTC_DE > R.RE_SPNSR_DE
                    THEN DATEADD(
                        ''DAY'',
                        -1,
                        TO_DATE(D.SPNSR_DSCNTC_DE, ''YYYYMMDD'')
                    )
    
                WHEN R.RE_SPNSR_DE < TO_CHAR(P.MONTH_END, ''YYYYMMDD'')
                    THEN P.MONTH_END
    
                ELSE TO_DATE(R.RE_SPNSR_DE, ''YYYYMMDD'')
    
            END AS ACTUAL_DT
    
        FROM LAST_DSCNTC D
    
        LEFT JOIN LAST_RE_SPNSR R
          ON D.MBER_NO = R.MBER_NO
         AND R.RNUM = 1
    
        CROSS JOIN PARAM_DATES P
    
        WHERE D.RNUM = 1
    ),
    
    HAS_LIVE_SPONSOR AS
    (
        SELECT DISTINCT
            S.MBER_NO
    
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR S
    
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR_BSNS B
          ON S.SPNSR_NO = B.SPNSR_NO
    
        CROSS JOIN PARAM_DATES P
    
        WHERE TO_CHAR(S.FRST_REGIST_DT, ''YYYYMMDD'') <= P.MONTH_31
          AND COALESCE(
                B.SPNSR_DSCNTC_DE,
                ''99991231''
              ) > P.MONTH_31
    ),
    
    ACTIVE_MEMBER AS
    (
        SELECT
            M.MBER_NO
    
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_INFO M
    
        JOIN HAS_LIVE_SPONSOR L
          ON M.MBER_NO = L.MBER_NO
    
        LEFT JOIN LAST_ACTIVITY_DATE A
          ON M.MBER_NO = A.MBER_NO
    
        CROSS JOIN PARAM_DATES P
    
        WHERE P.MONTH_END
              BETWEEN TO_DATE(M.FRST_REGIST_DT)
                  AND COALESCE(
                        A.ACTUAL_DT,
                        ''9999-12-31''::DATE
                      )
    ),
    
    /* =========================================================================
       7. 활동 이력
       ========================================================================= */
    ACTIVE_HISTORY AS
    (
        SELECT
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.OCCRRNC_DE,
            A.SER_NO,
            A.MBER_NO,
            A.SPNSR_BSNS_ID,
    
            SUM(
                A.SPNSR_AMT::NUMBER(38,4)
            ) OVER
            (
                PARTITION BY
                    A.SPNSR_NO,
                    A.SPNSR_BSNS_NO
            ) AS SUM_AMT,
    
            ROW_NUMBER() OVER
            (
                PARTITION BY
                    A.SPNSR_NO,
                    A.SPNSR_BSNS_NO
                ORDER BY
                    A.OCCRRNC_DE DESC,
                    A.SER_NO DESC
            ) AS RNUM
    
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_DVLP_AMT A
        CROSS JOIN PARAM_DATES P
    
        WHERE A.OCCRRNC_DE <= P.MONTH_31
    ),
    
    /* =========================================================================
       8. 활동회원 기준 데이터
       ========================================================================= */
    ACTIVE_BASE AS
    (
        SELECT
            P.STRD_MT AS STRD_MT,
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.MBER_NO,
            A.SPNSR_BSNS_ID,
    
            CASE
                WHEN TO_CHAR(M.FRST_REGIST_DT, ''YYYY'')
                     = LEFT(P.STRD_MT, 4)
                 AND TO_CHAR(S.FRST_REGIST_DT, ''YYYY'')
                     = LEFT(P.STRD_MT, 4)
                    THEN ''1''
                ELSE ''2''
            END AS NEW_OLD_DIV_CD,
    
            MAP.DEPT4_ID,
    
            COALESCE(
                SETLE.CPR_DIV_CD,
                ''I''
            ) AS CPR_DIV_CD,
    
            (
                A.SUM_AMT::NUMBER(38,10)
                / 10000.0
            ) AS SPNSR_AMT_CNT
    
        FROM ACTIVE_HISTORY A
    
        JOIN ACTIVE_MEMBER AM
          ON A.MBER_NO = AM.MBER_NO
    
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_INFO M
          ON A.MBER_NO = M.MBER_NO
    
        JOIN BUSINESS_DIM B
          ON A.SPNSR_BSNS_ID = B.SPNSR_BSNS_ID
    
        LEFT JOIN SETLE_MONTH SETLE
          ON A.MBER_NO = SETLE.MBER_NO
         AND B.CPR_DIV_CD = SETLE.CPR_DIV_CD
    
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR S
          ON A.MBER_NO = S.MBER_NO
         AND A.SPNSR_NO = S.SPNSR_NO
    
        LEFT JOIN DEPT_MAP MAP
          ON COALESCE(
                S.ACMSLT_DEPT_CD,
                ''Z~''
             ) = MAP.SRC_DEPT_ID
    
        CROSS JOIN PARAM_DATES P
    
        WHERE A.RNUM = 1
          AND A.SUM_AMT > 0
    ),
    
    /* =========================================================================
       9. 기존 / 신규 + 본부 / 지부 기준으로 1차 집계
          ----------------------------------------------------------------------
          기존:
            본부 + 지부를 모두 합쳐서 "기존 / 기존" 1행
    
          신규:
            신규 + 본부 -> 1행
            신규 + 지부 -> 1행
       ========================================================================= */
    FINAL_AGG AS
    (
        SELECT
            A.STRD_MT,
    
            CPR.CPR_DIV_NM,
    
            CASE
                WHEN BSNS.SPNSR_BSNS_NM IN
                (
                    ''결식아동지원'',
                    ''국내아동권리보호사업(사단법인)'',
                    ''복지관후원'',
                    ''아동복지시설지원'',
                    ''아동학대예방'',
                    ''저소득가정지원''
                )
                    THEN ''국내(사단)''
                ELSE BSNS.SPNSR_BSNS_NM
            END AS SPNSR_BSNS_GRP_NM,
    
            /* 기존 / 신규 */
            CASE
                WHEN A.NEW_OLD_DIV_CD = ''1''
                    THEN ''신규''
                WHEN A.NEW_OLD_DIV_CD = ''2''
                    THEN ''기존''
                ELSE ''없음''
            END AS NEW_EXST_DIV_NM,
    
            /* 기존은 무조건 "기존"
               신규만 본부 / 지부 구분 */
            CASE
                WHEN A.NEW_OLD_DIV_CD = ''2''
                    THEN ''기존''
    
                WHEN A.NEW_OLD_DIV_CD = ''1''
                 AND D4.DEPT4_NM IN (''본부'', ''본부(사복)'')
                    THEN ''본부''
    
                WHEN A.NEW_OLD_DIV_CD = ''1''
                    THEN ''지부''
    
                ELSE ''기존''
            END AS HDQ_BRNCH_GRP_NM,
    
            SUM(
                A.SPNSR_AMT_CNT::NUMBER(38,10)
            )::NUMBER(38,10) AS VALUE1
    
        FROM ACTIVE_BASE A
    
        LEFT JOIN CPR_DIM CPR
          ON A.CPR_DIV_CD = CPR.CPR_DIV_CD
    
        LEFT JOIN DEPT4_DIM D4
          ON A.DEPT4_ID = D4.DEPT4_ID
    
        LEFT JOIN BUSINESS_DIM BSNS
          ON A.SPNSR_BSNS_ID = BSNS.SPNSR_BSNS_ID
    
        CROSS JOIN PARAM_DATES P
    
        WHERE P.CPR_DIV_CD IS NULL
           OR A.CPR_DIV_CD = P.CPR_DIV_CD
    
        GROUP BY
            A.STRD_MT,
            CPR.CPR_DIV_NM,
    
            CASE
                WHEN BSNS.SPNSR_BSNS_NM IN
                (
                    ''결식아동지원'',
                    ''국내아동권리보호사업(사단법인)'',
                    ''복지관후원'',
                    ''아동복지시설지원'',
                    ''아동학대예방'',
                    ''저소득가정지원''
                )
                    THEN ''국내(사단)''
                ELSE BSNS.SPNSR_BSNS_NM
            END,
    
            CASE
                WHEN A.NEW_OLD_DIV_CD = ''1''
                    THEN ''신규''
                WHEN A.NEW_OLD_DIV_CD = ''2''
                    THEN ''기존''
                ELSE ''없음''
            END,
    
            CASE
                WHEN A.NEW_OLD_DIV_CD = ''2''
                    THEN ''기존''
    
                WHEN A.NEW_OLD_DIV_CD = ''1''
                 AND D4.DEPT4_NM IN (''본부'', ''본부(사복)'')
                    THEN ''본부''
    
                WHEN A.NEW_OLD_DIV_CD = ''1''
                    THEN ''지부''
    
                ELSE ''기존''
            END
    ),
    
    /* =========================================================================
       10. 반드시 출력해야 하는 3개 유형
       ========================================================================= */
    GROUP_TYPE AS
    (
        SELECT
            ''기존'' AS NEW_EXST_DIV_NM,
            ''기존'' AS HDQ_BRNCH_GRP_NM
    
        UNION ALL
    
        SELECT
            ''신규'' AS NEW_EXST_DIV_NM,
            ''본부'' AS HDQ_BRNCH_GRP_NM
    
        UNION ALL
    
        SELECT
            ''신규'' AS NEW_EXST_DIV_NM,
            ''지부'' AS HDQ_BRNCH_GRP_NM
    ),
    
    /* =========================================================================
       11. SPNSR_BSNS_GRP_NM별 기준 목록
       ========================================================================= */
    GROUP_BASE AS
    (
        SELECT DISTINCT
            STRD_MT,
            CPR_DIV_NM,
            SPNSR_BSNS_GRP_NM
        FROM FINAL_AGG
    )
    
    /* =========================================================================
       12. 최종 결과
          SPNSR_BSNS_GRP_NM별 무조건 3행 생성
       ========================================================================= */
    SELECT
        G.STRD_MT,
    
        :AGGR_TY_NM AS AGGR_TY_NM,
    
        G.CPR_DIV_NM,
    
        G.SPNSR_BSNS_GRP_NM,
    
        T.NEW_EXST_DIV_NM,
    
        T.HDQ_BRNCH_GRP_NM,
    
        COALESCE(
            A.VALUE1,
            0
        )::NUMBER(38,10) AS "활동건수",
    
        NULL AS VALUE2
    
    FROM GROUP_BASE G
    
    CROSS JOIN GROUP_TYPE T
    
    LEFT JOIN FINAL_AGG A
      ON  G.STRD_MT = A.STRD_MT
      AND G.CPR_DIV_NM = A.CPR_DIV_NM
      AND G.SPNSR_BSNS_GRP_NM = A.SPNSR_BSNS_GRP_NM
      AND T.NEW_EXST_DIV_NM = A.NEW_EXST_DIV_NM
      AND T.HDQ_BRNCH_GRP_NM = A.HDQ_BRNCH_GRP_NM
    
    ORDER BY
        G.STRD_MT,
        G.CPR_DIV_NM,
        G.SPNSR_BSNS_GRP_NM,
    
        CASE
            WHEN T.NEW_EXST_DIV_NM = ''기존''
                THEN 1
    
            WHEN T.NEW_EXST_DIV_NM = ''신규''
             AND T.HDQ_BRNCH_GRP_NM = ''본부''
                THEN 2
    
            WHEN T.NEW_EXST_DIV_NM = ''신규''
             AND T.HDQ_BRNCH_GRP_NM = ''지부''
                THEN 3
    
            ELSE 9
        END
    ;
    
    RETURN ''SUCCESS: '' || :STDR_MT;
END;
';
CREATE OR REPLACE PROCEDURE GN_DW.SILVER.SP_INSERT_MM_SPNSR_CLS_AGGR_DATA5("INPUT_YYYYMM" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS CALLER
AS '
DECLARE
    STDR_MT VARCHAR;
    CPR_DIV_CD VARCHAR;
    AGGR_TY_NM VARCHAR;
BEGIN
    -- 0. 파라미터
    IF (NOT REGEXP_LIKE(input_yyyymm, ''^[0-9]{6}$'')) THEN
        RETURN ''ERROR: input_yyyymm은 YYYYMM 형식이어야 합니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'') IS NULL) THEN
        RETURN ''ERROR: 유효하지 않은 년월입니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    IF (
        TRY_TO_DATE(input_yyyymm || ''01'', ''YYYYMMDD'')
        > DATE_TRUNC(''MONTH'', CURRENT_DATE())
    ) THEN
        RETURN ''ERROR: 미래 년월은 입력할 수 없습니다. 입력값=[''
               || input_yyyymm || '']'';
    END IF;
    STDR_MT := input_yyyymm;
    CPR_DIV_CD := ''I'';
    AGGR_TY_NM := ''회비'';
    /* ============================================================
       1. 전체 데이터 구성
    ============================================================ */
    DELETE
    FROM GN_DW.SILVER.MM_SPNSR_CLS_AGGR_DATA
    WHERE STDR_MT = :STDR_MT
    AND AGGR_TY_NM = :AGGR_TY_NM;
    INSERT INTO GN_DW.SILVER.MM_SPNSR_CLS_AGGR_DATA
    WITH
    /* ------------------------------------------------------------
       실행 파라미터
    ------------------------------------------------------------ */
    PARAMS AS
    (
        SELECT
            :STDR_MT AS STDR_MT,
            :CPR_DIV_CD AS CPR_DIV_CD,
    
            TO_DATE(:STDR_MT || ''01'', ''YYYYMMDD'') AS STDR_MONTH_START,
    
            LAST_DAY(
                TO_DATE(:STDR_MT || ''01'', ''YYYYMMDD'')
            ) AS STDR_MONTH_END
    ),
    /* ------------------------------------------------------------
       기준연도 1월 ~ 기준월
       MSSQL WHILE 대체
    ------------------------------------------------------------ */
    MONTHS AS
    (
        SELECT
            TO_CHAR(
                DATEADD(
                    MONTH,
                    SEQ4(),
                    DATE_TRUNC(''YEAR'', P.STDR_MONTH_START)
                ),
                ''YYYYMM''
            ) AS RUN_MT,
    
            DATEADD(
                MONTH,
                SEQ4(),
                DATE_TRUNC(''YEAR'', P.STDR_MONTH_START)
            ) AS RUN_MONTH_START,
    
            LAST_DAY(
                DATEADD(
                    MONTH,
                    SEQ4(),
                    DATE_TRUNC(''YEAR'', P.STDR_MONTH_START)
                )
            ) AS RUN_MONTH_END,
    
            DATEADD(
                DAY,
                1,
                DATEADD(
                    MONTH,
                    1,
                    DATEADD(
                        MONTH,
                        SEQ4(),
                        DATE_TRUNC(''YEAR'', P.STDR_MONTH_START)
                    )
                )
            ) AS RUN_SETLE_CUTOFF
    
        FROM PARAMS P,
             TABLE(GENERATOR(ROWCOUNT => 12))
    
        WHERE SEQ4() <= MONTH(P.STDR_MONTH_START) - 1
    ),
    
    /* ============================================================
       2. 차원
    ============================================================ */
    
    
    /* ------------------------------------------------------------
       2-1. 부서 매핑
       #DEPT_MAP
    ------------------------------------------------------------ */
    DEPT_MAP AS
    (
        SELECT
            E.DEPT_ID AS SRC_DEPT_ID,
            D.DEPT_ID AS DEPT2_ID,
            C.DEPT_ID AS DEPT3_ID,
            B.DEPT_ID AS DEPT4_ID
    
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO A
    
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO B
          ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
    
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO C
          ON C.ACMSLT_UPPER_DEPT_ID = B.DEPT_ID
    
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO D
          ON D.ACMSLT_UPPER_DEPT_ID = C.DEPT_ID
    
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO E
          ON E.ACMSLT_UPPER_DEPT_ID = D.DEPT_ID
    
        WHERE A.UPPER_DEPT_ID = ''ZV000000''
          AND C.DEPT_ID <> ''ZC000029''
    
        UNION ALL
    
        SELECT
            ''Z~'',
            ''Z~'',
            ''Z~'',
            ''Z~''
    ),
    
    
    /* ------------------------------------------------------------
       2-2. DEPT4
       #DEPT4_DIM
    ------------------------------------------------------------ */
    DEPT4_DIM AS
    (
        SELECT
            B.DEPT_ID AS DEPT4_ID,
            B.DEPT_NM AS DEPT4_NM,
            B.SORT_ORDR
    
        FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO A
    
        JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO B
          ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
    
        WHERE A.UPPER_DEPT_ID = ''ZV000000''
          AND A.USE_YN = ''Y''
    
        UNION ALL
    
        SELECT
            ''Z~'',
            ''없음'',
            999
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO A
            JOIN GN_DW.BRONZE_CRM.TM_CM_DEPT_INFO B
              ON B.ACMSLT_UPPER_DEPT_ID = A.DEPT_ID
            WHERE A.UPPER_DEPT_ID = ''ZV000000''
              AND A.USE_YN = ''Y''
              AND B.DEPT_ID = ''Z~''
        )
    ),
    
    
    /* ------------------------------------------------------------
       2-3. 법인구분
       #CPR_DIM
    ------------------------------------------------------------ */
    CPR_DIM AS
    (
        SELECT DISTINCT
            D.DTL_CD_ID AS CPR_DIV_CD,
            D.DTL_CD_NM AS CPR_DIV_NM,
            D.SORT_ORDR
    
        FROM GN_DW.BRONZE_CRM.TC_CMMN_DTL_CD D
    
        WHERE D.CD_ID = ''CM019''
    ),
    
    
    /* ------------------------------------------------------------
       2-4. 후원사업
       #BUSINESS_DIM
    ------------------------------------------------------------ */
    BUSINESS_DIM AS
    (
        SELECT
            S.SPNSR_BSNS_ID,
            S.SPNSR_BSNS_NM,
            S.SPNSR_BSNS_ABRV_CD,
            S.SORT_ORDR,
    
            CASE
                WHEN S.CPR_DIV_CD = ''1'' THEN ''I''
                WHEN S.CPR_DIV_CD = ''2'' THEN ''S''
                ELSE S.CPR_DIV_CD
            END AS CPR_DIV_CD
    
        FROM GN_DW.BRONZE_CRM.TM_CM_SPNSR_BSNS_INFO S
    
        UNION ALL
    
        SELECT
            ''99'',
            ''없음'',
            ''99'',
            999,
            ''Z''
    
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM GN_DW.BRONZE_CRM.TM_CM_SPNSR_BSNS_INFO
            WHERE SPNSR_BSNS_ID = ''99''
        )
    ),
    
    
    /* ------------------------------------------------------------
       2-5. 회비구분
       #FEE_DIM
    ------------------------------------------------------------ */
    FEE_DIM AS
    (
        SELECT DISTINCT
            D.DTL_CD_ID AS MBRFEE_DIV_CD,
            D.DTL_CD_NM AS MBRFEE_DIV_NM,
            D.SORT_ORDR
    
        FROM GN_DW.BRONZE_CRM.TC_CMMN_DTL_CD D
    
        WHERE D.CD_ID = ''PM010''
    ),
    
    
    /* ============================================================
       3. 월별 최신 결제정보
       #RUN_SETLE_MONTH
    ============================================================ */
    
    SETLE_SOURCE AS
    (
        SELECT
            M.RUN_MT,
            C.SETLE_KEY,
            C.MBER_NO,
            C.CPR_DIV_CD,
            C.SETLE_CD,
            C.FRST_REGIST_DT
    
        FROM MONTHS M
    
        JOIN GN_DW.BRONZE_CRM.TM_PM_SETLE_INFO C
          ON C.FRST_REGIST_DT <= M.RUN_SETLE_CUTOFF
    
        UNION ALL
    
        SELECT
            M.RUN_MT,
            H.SETLE_KEY,
            H.MBER_NO,
            H.CPR_DIV_CD,
            H.SETLE_CD,
            H.REGIST_DT AS FRST_REGIST_DT
    
        FROM MONTHS M
    
        JOIN GN_DW.BRONZE_CRM.TH_PM_SETLE_INFO_HIST H
          ON H.REGIST_DT <= M.RUN_SETLE_CUTOFF
    ),
    
    
    SETLE_RANKED AS
    (
        SELECT
            RUN_MT,
            MBER_NO,
    
            CASE
                WHEN CPR_DIV_CD = ''1'' THEN ''I''
                WHEN CPR_DIV_CD = ''2'' THEN ''S''
                ELSE CPR_DIV_CD
            END AS CPR_DIV_CD,
    
            SETLE_CD,
    
            ROW_NUMBER() OVER
            (
                PARTITION BY
                    RUN_MT,
                    MBER_NO,
                    CASE
                        WHEN CPR_DIV_CD = ''1'' THEN ''I''
                        WHEN CPR_DIV_CD = ''2'' THEN ''S''
                        ELSE CPR_DIV_CD
                    END
    
                ORDER BY SETLE_KEY DESC
            ) AS RNUM
    
        FROM SETLE_SOURCE
    ),
    RUN_SETLE_MONTH AS
    (
        SELECT
            RUN_MT,
            MBER_NO,
            CPR_DIV_CD,
            COALESCE(SETLE_CD, ''4'') AS SETLE_CD
    
        FROM SETLE_RANKED
    
        WHERE RNUM = 1
    ),
    
    
    /* ============================================================
       4. 월별 활동회원
    ============================================================ */
    
    
    /* ------------------------------------------------------------
       4-1. 마지막 중단일
    ------------------------------------------------------------ */
    LAST_DSCNTC AS
    (
        SELECT
            M.RUN_MT,
            D.MBER_NO,
            D.SPNSR_DSCNTC_DE,
    
            ROW_NUMBER() OVER
            (
                PARTITION BY
                    M.RUN_MT,
                    D.MBER_NO
    
                ORDER BY D.SPNSR_DSCNTC_DE DESC
            ) AS RNUM
    
        FROM MONTHS M
        
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR_DSCNTC D
          ON D.SPNSR_DSCNTC_DE <=
             TO_CHAR(M.RUN_MONTH_END, ''YYYYMMDD'')
    ),
    
    
    /* ------------------------------------------------------------
       4-2. 마지막 재후원일
    ------------------------------------------------------------ */
    LAST_RE_SPNSR AS
    (
        SELECT
            M.RUN_MT,
            R.MBER_NO,
            R.RE_SPNSR_DE,
    
            ROW_NUMBER() OVER
            (
                PARTITION BY
                    M.RUN_MT,
                    R.MBER_NO
    
                ORDER BY R.RE_SPNSR_DE DESC
            ) AS RNUM
    
        FROM MONTHS M
        
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_RE_SPNSR R
          ON R.RE_SPNSR_DE <=
             TO_CHAR(M.RUN_MONTH_END, ''YYYYMMDD'')
    ),
    
    
    /* ------------------------------------------------------------
       4-3. 실제 활동 종료일
    ------------------------------------------------------------ */
    LAST_ACTIVITY_DATE AS
    (
        SELECT
            D.RUN_MT,
            D.MBER_NO,
    
            CASE
    
                WHEN R.RE_SPNSR_DE IS NULL
                    THEN DATEADD(
                        DAY,
                        -1,
                        TO_DATE(D.SPNSR_DSCNTC_DE, ''YYYYMMDD'')
                    )
    
                WHEN D.SPNSR_DSCNTC_DE > R.RE_SPNSR_DE
                    THEN DATEADD(
                        DAY,
                        -1,
                        TO_DATE(D.SPNSR_DSCNTC_DE, ''YYYYMMDD'')
                    )
    
                WHEN R.RE_SPNSR_DE <
                     TO_CHAR(
                         M.RUN_MONTH_END,
                         ''YYYYMMDD''
                     )
                    THEN M.RUN_MONTH_END
    
                ELSE TO_DATE(
                    R.RE_SPNSR_DE,
                    ''YYYYMMDD''
                )
    
            END AS ACTUAL_DT
    
        FROM LAST_DSCNTC D
    
        JOIN MONTHS M
          ON D.RUN_MT = M.RUN_MT
    
        LEFT JOIN LAST_RE_SPNSR R
          ON D.RUN_MT = R.RUN_MT
         AND D.MBER_NO = R.MBER_NO
         AND R.RNUM = 1
    
        WHERE D.RNUM = 1
    ),
    
    
    /* ------------------------------------------------------------
       4-4. 활동 중인 후원 존재 여부
    ------------------------------------------------------------ */
    HAS_LIVE_SPONSOR AS
    (
        SELECT DISTINCT
            M.RUN_MT,
            S.MBER_NO
    
        FROM MONTHS M
    
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR S
          ON TO_DATE(
                 TO_CHAR(S.FRST_REGIST_DT, ''YYYYMMDD''),
                 ''YYYYMMDD''
             )
             <= M.RUN_MONTH_END
        
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR_BSNS B
          ON S.SPNSR_NO = B.SPNSR_NO
    
        WHERE COALESCE(
                  B.SPNSR_DSCNTC_DE,
                  ''99991231''
              ) >
              TO_CHAR(
                  M.RUN_MONTH_END,
                  ''YYYYMMDD''
              )
    ),
    
    
    /* ------------------------------------------------------------
       4-5. 실행월 활동회원
       #RUN_ACTIVE_MEMBER
    ------------------------------------------------------------ */
    RUN_ACTIVE_MEMBER AS
    (
        SELECT DISTINCT
            RM.RUN_MT,
            M.MBER_NO
    
        FROM MONTHS RM
    
        JOIN HAS_LIVE_SPONSOR L
          ON RM.RUN_MT = L.RUN_MT
    
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_INFO M
          ON L.MBER_NO = M.MBER_NO
    
        LEFT JOIN LAST_ACTIVITY_DATE A
          ON RM.RUN_MT = A.RUN_MT
         AND M.MBER_NO = A.MBER_NO
    
        WHERE RM.RUN_MONTH_END
              BETWEEN TO_DATE(M.FRST_REGIST_DT)
                  AND COALESCE(
                        A.ACTUAL_DT,
                        TO_DATE(''9999-12-31'')
                      )
    ),
    /* ============================================================
       5. 월별 활동행 재현
    ============================================================ */
    
    ACTIVE_HISTORY AS
    (
        SELECT
            M.RUN_MT,
    
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.OCCRRNC_DE,
            A.SER_NO,
            A.MBER_NO,
            A.SPNSR_BSNS_ID,
    
            SUM(
                TO_DECIMAL(
                    A.SPNSR_AMT,
                    38,
                    4
                )
            ) OVER
            (
                PARTITION BY
                    M.RUN_MT,
                    A.SPNSR_NO,
                    A.SPNSR_BSNS_NO
            ) AS SUM_AMT,
    
            ROW_NUMBER() OVER
            (
                PARTITION BY
                    M.RUN_MT,
                    A.SPNSR_NO,
                    A.SPNSR_BSNS_NO
    
                ORDER BY
                    A.OCCRRNC_DE DESC,
                    A.SER_NO DESC
            ) AS RNUM
    
        FROM MONTHS M
    
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_DVLP_AMT A
          ON A.OCCRRNC_DE <=
             TO_CHAR(
                 M.RUN_MONTH_END,
                 ''YYYYMMDD''
             )
    ),
    
    
    RUN_ACTIVE_DETAIL AS
    (
        SELECT
            A.RUN_MT AS STRD_MT,
    
            A.SPNSR_NO,
            A.SPNSR_BSNS_NO,
            A.MBER_NO,
    
            CASE
                WHEN TO_CHAR(M.FRST_REGIST_DT, ''YYYY'') =
                     LEFT(A.RUN_MT, 4)
    
                 AND TO_CHAR(S.FRST_REGIST_DT, ''YYYY'') =
                     LEFT(A.RUN_MT, 4)
    
                    THEN ''1''
    
                ELSE ''2''
    
            END AS NEW_OLD_DIV_CD,
    
            COALESCE(
                S.ACMSLT_DEPT_CD,
                ''Z~''
            ) AS ACMSLT_DEPT_CD,
    
            COALESCE(
                MAP.DEPT2_ID,
                ''Z~''
            ) AS ACMSLT_DEPT2_CD,
    
            COALESCE(
                MAP.DEPT3_ID,
                ''Z~''
            ) AS ACMSLT_DEPT3_CD,
    
            COALESCE(
                MAP.DEPT4_ID,
                ''Z~''
            ) AS ACMSLT_DEPT4_CD,
    
            COALESCE(
                A.SPNSR_BSNS_ID,
                ''99''
            ) AS SPNSR_BSNS_ID,
    
            COALESCE(
                ST.CPR_DIV_CD,
                ''I''
            ) AS CPR_DIV_CD,
    
            COALESCE(
                ST.SETLE_CD,
                ''4''
            ) AS SETLE_CD
    
        FROM ACTIVE_HISTORY A
    
        JOIN RUN_ACTIVE_MEMBER AM
          ON A.RUN_MT = AM.RUN_MT
         AND A.MBER_NO = AM.MBER_NO
    
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_INFO M
          ON A.MBER_NO = M.MBER_NO
    
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR S
          ON A.SPNSR_NO = S.SPNSR_NO
         AND A.MBER_NO = S.MBER_NO
    
        LEFT JOIN BUSINESS_DIM B
          ON A.SPNSR_BSNS_ID = B.SPNSR_BSNS_ID
    
        LEFT JOIN RUN_SETLE_MONTH ST
          ON A.RUN_MT = ST.RUN_MT
         AND A.MBER_NO = ST.MBER_NO
         AND B.CPR_DIV_CD = ST.CPR_DIV_CD
    
        LEFT JOIN DEPT_MAP MAP
          ON COALESCE(
                 S.ACMSLT_DEPT_CD,
                 ''Z~''
             ) = MAP.SRC_DEPT_ID
    
        WHERE A.RNUM = 1
          AND A.SUM_AMT > 0
    ), 
    
    
    
    /* ------------------------------------------------------------
       원 적재 Grain → 회원 집계
    ------------------------------------------------------------ */
    ACTIVITY_PROC_GRAIN AS
    (
        SELECT
            D.STRD_MT,
            D.CPR_DIV_CD,
            D.NEW_OLD_DIV_CD,
            D.ACMSLT_DEPT_CD,
            D.ACMSLT_DEPT2_CD,
            D.ACMSLT_DEPT3_CD,
            D.ACMSLT_DEPT4_CD,
            D.SPNSR_BSNS_ID,
            D.SETLE_CD,
    
            COUNT(
                DISTINCT D.MBER_NO
            ) AS ACT_MBR_CNT
    
        FROM RUN_ACTIVE_DETAIL D
    
        GROUP BY
            D.STRD_MT,
            D.CPR_DIV_CD,
            D.NEW_OLD_DIV_CD,
            D.ACMSLT_DEPT_CD,
            D.ACMSLT_DEPT2_CD,
            D.ACMSLT_DEPT3_CD,
            D.ACMSLT_DEPT4_CD,
            D.SPNSR_BSNS_ID,
            D.SETLE_CD
    ),
    
    
    /* ============================================================
       6. 활동회원 Fact
    ============================================================ */
    
    ACTIVITY_FACT AS
    (
        SELECT
            G.STRD_MT AS SOURCE_MT,
    
            ''E'' AS MBRFEE_DIV_CD,
    
            COALESCE(
                G.NEW_OLD_DIV_CD,
                ''2''
            ) AS NEW_OLD_DIV_CD,
    
            COALESCE(
                G.ACMSLT_DEPT4_CD,
                ''Z~''
            ) AS DEPT4_ID,
    
            COALESCE(
                G.SPNSR_BSNS_ID,
                ''99''
            ) AS SPNSR_BSNS_ID,
    
            COALESCE(
                G.CPR_DIV_CD,
                ''Z''
            ) AS CPR_DIV_CD,
    
            SUM(
                G.ACT_MBR_CNT
            ) AS ACT_MBR_CNT,
    
            TO_DECIMAL(
                0,
                38,
                0
            ) AS PAY_AMT
    
        FROM ACTIVITY_PROC_GRAIN G
    
        CROSS JOIN PARAMS P
    
        WHERE P.CPR_DIV_CD IS NULL
           OR COALESCE(
                  G.CPR_DIV_CD,
                  ''Z''
              ) = P.CPR_DIV_CD
    
        GROUP BY
            G.STRD_MT,
            COALESCE(G.NEW_OLD_DIV_CD, ''2''),
            COALESCE(G.ACMSLT_DEPT4_CD, ''Z~''),
            COALESCE(G.SPNSR_BSNS_ID, ''99''),
            COALESCE(G.CPR_DIV_CD, ''Z'')
    ),
    
    /* ============================================================
       7. 활동회원의 신규/기존 구분
    ============================================================ */
    
    RUN_ACTIVE_NEW_OLD AS
    (
        SELECT DISTINCT
            D.STRD_MT,
            D.MBER_NO,
            D.NEW_OLD_DIV_CD
    
        FROM RUN_ACTIVE_DETAIL D
    ),
    
    
    /* ============================================================
       8. 납입정보 재현
    ============================================================ */
    
    
    /* ------------------------------------------------------------
       8-1. 후원사업 정보
    ------------------------------------------------------------ */
    SPNSR_BSNS_SOURCE AS
    (
        SELECT
            S.SPNSR_NO,
            B.SPNSR_BSNS_NO,
            S.ACMSLT_DEPT_CD
    
        FROM GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR S
    
        JOIN GN_DW.BRONZE_CRM.TM_MM_FDRM_MBER_SPNSR_BSNS B
          ON S.SPNSR_NO = B.SPNSR_NO
    ),
    
    
    /* ------------------------------------------------------------
       8-2. 계좌 정보
       MSSQL TOP(1) 대체
    ------------------------------------------------------------ */
    INSTT_ACNUT_BASE AS
    (
        SELECT
            A.ACNUT_SER_NO,
            A.CHRG_DEPT_CD
        FROM GN_DW.BRONZE_CRM.TM_PM_INSTT_ACNUT A
    ),
    INSTT_ACNUT_SOURCE AS
    (
        SELECT
            ACNUT_SER_NO,
            CHRG_DEPT_CD
        FROM INSTT_ACNUT_BASE
    
        UNION ALL
    
        SELECT
            ''9999'' AS ACNUT_SER_NO,
            ''Z~'' AS CHRG_DEPT_CD
        FROM INSTT_ACNUT_BASE
        QUALIFY ROW_NUMBER() OVER (ORDER BY ACNUT_SER_NO) = 1
    ),
    /* ------------------------------------------------------------
       8-3. 납입 원천
    ------------------------------------------------------------ */
    PAY_SOURCE AS
    (
        SELECT
            P.MBER_NO,
    
            COALESCE(
                P.SPNSR_BSNS_ID,
                ''99''
            ) AS SPNSR_BSNS_ID,
    
            COALESCE(
                P.CPR_DIV_CD,
                ''Z''
            ) AS CPR_DIV_CD,
    
            COALESCE(
                P.MBRFEE_DIV_CD,
                ''Z''
            ) AS MBRFEE_DIV_CD,
    
            CASE
                WHEN P.SETLE_CD IN
                     (''3'', ''6'', ''10'', ''13'')
                    THEN ''10''
    
                ELSE COALESCE(
                    P.SETLE_CD,
                    ''999''
                )
            END AS SETLE_CD,
    
            COALESCE(
                S.ACMSLT_DEPT_CD,
                ''Z~''
            ) AS SPNSR_ACMSLT_DEPT_CD,
    
            IA4.CHRG_DEPT_CD AS INSTT_CHRG_DEPT_CD,
    
            IA10.CHRG_DEPT_CD AS CMPNY_CHRG_DEPT_CD,
    
            TO_DECIMAL(
                P.PAY_AMT,
                38,
                0
            ) AS PAY_AMT,
    
            TO_CHAR(
                P.PAY_DE,
                ''YYYYMM''
            ) AS RUN_MT
    
        FROM GN_DW.BRONZE_CRM.TM_PM_MBRFEE_ACMSLT P
        LEFT JOIN SPNSR_BSNS_SOURCE S
          ON P.SPNSR_NO = S.SPNSR_NO
         AND P.SPNSR_BSNS_NO = S.SPNSR_BSNS_NO
    
        LEFT JOIN INSTT_ACNUT_SOURCE IA4
          ON P.ACNUT_SER_NO = IA4.ACNUT_SER_NO
    
        LEFT JOIN GN_DW.BRONZE_CRM.TM_PM_SETLE_CMPNY_ACNT CA
          ON P.SETLE_CMPNY_ACNT_NO =
             CA.SETLE_CMPNY_ACNT_NO
    
        LEFT JOIN INSTT_ACNUT_SOURCE IA10
          ON CA.ACNUT_SER_NO =
             IA10.ACNUT_SER_NO
        WHERE P.USE_YN = ''Y''
          AND P.PRCS_STAT_CD = ''S''
          AND P.PAY_STAT_CD = ''S''
          AND P.RETUN_REQUST_KEY IS NULL
    
          AND EXISTS
          (
              SELECT 1
              FROM MONTHS M
              WHERE P.PAY_DE >= M.RUN_MONTH_START
                AND P.PAY_DE <
                    DATEADD(
                        DAY,
                        1,
                        M.RUN_MONTH_END
                    )
                AND
                (
                    :CPR_DIV_CD IS NULL
                    OR COALESCE(
                           P.CPR_DIV_CD,
                           ''Z''
                       ) = :CPR_DIV_CD
                )
          )
    ),
    
    /* ------------------------------------------------------------
       8-4. 실제 청구 부서
    ------------------------------------------------------------ */
    PAY_CHARGE AS
    (
        SELECT
            P.*,
    
            CASE
                WHEN P.SETLE_CD = ''4''
                    THEN P.INSTT_CHRG_DEPT_CD
    
                WHEN P.SETLE_CD IN
                     (''3'', ''6'', ''10'', ''13'')
                    THEN P.CMPNY_CHRG_DEPT_CD
    
                ELSE ''D000011''
            END AS CHRG_DEPT_CD
    
        FROM PAY_SOURCE P
    ),
    
    
    /* ------------------------------------------------------------
       8-5. 납입 최종 대상
    ------------------------------------------------------------ */
    PAY_FN AS
    (
        SELECT
            P.RUN_MT,
            P.MBER_NO,
            P.SPNSR_BSNS_ID,
            P.CPR_DIV_CD,
            P.MBRFEE_DIV_CD,
    
            CASE
    
                WHEN P.MBRFEE_DIV_CD = ''E''
                    THEN P.SPNSR_ACMSLT_DEPT_CD
    
                WHEN P.MBRFEE_DIV_CD IN (''I'', ''U'')
                    THEN P.CHRG_DEPT_CD
    
                WHEN P.MBRFEE_DIV_CD = ''G''
                    THEN ''D000011''
    
                ELSE NULL
    
            END AS ACMSLT_DEPT_CD,
    
            P.PAY_AMT
    
        FROM PAY_CHARGE P
    
        WHERE P.CHRG_DEPT_CD = ''D000011''
    ),
    
    
    /* ============================================================
       9. 납입 Fact
    ============================================================ */
    
    PAYMENT_FACT AS
    (
        SELECT
            P.RUN_MT AS SOURCE_MT,
    
            P.MBRFEE_DIV_CD,
    
            COALESCE(
                N.NEW_OLD_DIV_CD,
                ''2''
            ) AS NEW_OLD_DIV_CD,
    
            COALESCE(
                MAP.DEPT4_ID,
                ''Z~''
            ) AS DEPT4_ID,
    
            COALESCE(
                P.SPNSR_BSNS_ID,
                ''99''
            ) AS SPNSR_BSNS_ID,
    
            COALESCE(
                P.CPR_DIV_CD,
                ''Z''
            ) AS CPR_DIV_CD,
    
            TO_NUMBER(0) AS ACT_MBR_CNT,
    
            SUM(
                P.PAY_AMT
            ) AS PAY_AMT
    
        FROM PAY_FN P
    
        LEFT JOIN RUN_ACTIVE_NEW_OLD N
          ON P.RUN_MT = N.STRD_MT
         AND P.MBER_NO = N.MBER_NO
    
        LEFT JOIN DEPT_MAP MAP
          ON COALESCE(
                 P.ACMSLT_DEPT_CD,
                 ''Z~''
             ) = MAP.SRC_DEPT_ID
    
        GROUP BY
            P.RUN_MT,
            P.MBRFEE_DIV_CD,
            COALESCE(N.NEW_OLD_DIV_CD, ''2''),
            COALESCE(MAP.DEPT4_ID, ''Z~''),
            COALESCE(P.SPNSR_BSNS_ID, ''99''),
            COALESCE(P.CPR_DIV_CD, ''Z'')
    ),
    
    /* ============================================================
       10. 월별 Fact
       #MONTHLY_FACT 대체
    ============================================================ */
    
    MONTHLY_FACT AS
    (
        SELECT
            SOURCE_MT,
            MBRFEE_DIV_CD,
            NEW_OLD_DIV_CD,
            DEPT4_ID,
            SPNSR_BSNS_ID,
            CPR_DIV_CD,
            ACT_MBR_CNT,
            PAY_AMT
    
        FROM ACTIVITY_FACT
    
        UNION ALL
    
        SELECT
            SOURCE_MT,
            MBRFEE_DIV_CD,
            NEW_OLD_DIV_CD,
            DEPT4_ID,
            SPNSR_BSNS_ID,
            CPR_DIV_CD,
            ACT_MBR_CNT,
            PAY_AMT
    
        FROM PAYMENT_FACT
    ),
    /* ============================================================
       11. 기준월 결과
       #CURRENT_FACT 대체
    ============================================================ */
    
    CURRENT_FACT AS
    (
        SELECT
            P.STDR_MT AS STRD_MT,
    
            F.MBRFEE_DIV_CD,
            F.NEW_OLD_DIV_CD,
            F.DEPT4_ID,
            F.SPNSR_BSNS_ID,
            F.CPR_DIV_CD,
    
            SUM(
                F.ACT_MBR_CNT
            ) AS WJXBFS1,
    
            SUM(
                F.PAY_AMT
            ) AS WJXBFS2
    
        FROM MONTHLY_FACT F
    
        CROSS JOIN PARAMS P
    
        WHERE F.SOURCE_MT = P.STDR_MT
    
        GROUP BY
            P.STDR_MT,
            F.MBRFEE_DIV_CD,
            F.NEW_OLD_DIV_CD,
            F.DEPT4_ID,
            F.SPNSR_BSNS_ID,
            F.CPR_DIV_CD
    ),
    
    
    /* ============================================================
       12. YTD
       #YTD_FACT 대체
    ============================================================ */
    
    YTD_FACT AS
    (
        SELECT
            P.STDR_MT AS STRD_MT,
    
            F.MBRFEE_DIV_CD,
            F.NEW_OLD_DIV_CD,
            F.DEPT4_ID,
            F.SPNSR_BSNS_ID,
            F.CPR_DIV_CD,
    
            SUM(
                F.PAY_AMT
            ) AS WJXBFS3
    
        FROM MONTHLY_FACT F
    
        CROSS JOIN PARAMS P
    
        GROUP BY
            P.STDR_MT,
            F.MBRFEE_DIV_CD,
            F.NEW_OLD_DIV_CD,
            F.DEPT4_ID,
            F.SPNSR_BSNS_ID,
            F.CPR_DIV_CD
    ),
    /* ============================================================
       13. 출력 기준 행 생성
       - STRD_MT
       - CPR_DIV_NM
       - SPNSR_BSNS_NM
       별로 신규본부 / 신규지부 / 기존 행을 항상 보장
    ============================================================ */
    /* ============================================================
       13. 출력 기준 행 생성
       - STRD_MT
       - CPR_DIV_NM
       - SPNSR_BSNS_NM
       별로 신규/본부
            신규/지부
            기존/기존
       3개 행을 항상 보장
    ============================================================ */
    RESULT_BASE AS
    (
        SELECT
            P.STDR_MT AS STRD_MT,
            CP.CPR_DIV_CD,
            CP.CPR_DIV_NM,
    
            CASE
                WHEN COALESCE(B.SPNSR_BSNS_NM, ''없음'') IN
                (
                    ''결식아동지원'',
                    ''국내아동권리보호사업(사단법인)'',
                    ''복지관후원'',
                    ''아동복지시설지원'',
                    ''아동학대예방'',
                    ''저소득가정지원''
                )
                THEN ''국내(사단)''
    
                ELSE COALESCE(
                    B.SPNSR_BSNS_NM,
                    ''없음''
                )
            END AS SPNSR_BSNS_GRP_NM,
    
            X.NEW_EXST_DIV_NM,
            X.HDQ_BRNCH_GRP_NM
    
        FROM PARAMS P
    
        CROSS JOIN CPR_DIM CP
    
        JOIN BUSINESS_DIM B
          ON B.CPR_DIV_CD = CP.CPR_DIV_CD
    
        CROSS JOIN
        (
            SELECT
                ''신규'' AS NEW_EXST_DIV_NM,
                ''본부'' AS HDQ_BRNCH_GRP_NM
    
            UNION ALL
    
            SELECT
                ''신규'',
                ''지부''
    
            UNION ALL
    
            SELECT
                ''기존'',
                ''기존''
        ) X
    
        WHERE P.CPR_DIV_CD IS NULL
           OR CP.CPR_DIV_CD = P.CPR_DIV_CD
    
        GROUP BY
            P.STDR_MT,
            CP.CPR_DIV_CD,
            CP.CPR_DIV_NM,
    
            CASE
                WHEN COALESCE(B.SPNSR_BSNS_NM, ''없음'') IN
                (
                    ''결식아동지원'',
                    ''국내아동권리보호사업(사단법인)'',
                    ''복지관후원'',
                    ''아동복지시설지원'',
                    ''아동학대예방'',
                    ''저소득가정지원''
                )
                THEN ''국내(사단)''
    
                ELSE COALESCE(
                    B.SPNSR_BSNS_NM,
                    ''없음''
                )
            END,
    
            X.NEW_EXST_DIV_NM,
            X.HDQ_BRNCH_GRP_NM
    ),
    
    /* ============================================================
       14. 실제 집계 결과
    ============================================================ */
    RESULT_AGGR AS
    (
        SELECT
            STRD_MT,
            CPR_DIV_CD,
            CPR_DIV_NM,
            SPNSR_BSNS_GRP_NM,
            NEW_EXST_DIV_NM,
            HDQ_BRNCH_GRP_NM,
    
            SUM(VALUE1) AS VALUE1,
            SUM(VALUE2) AS VALUE2
    
        FROM
        (
            /* ====================================================
               기준월 납입금액
            ==================================================== */
            SELECT
                C.STRD_MT,
                C.CPR_DIV_CD,
                CP.CPR_DIV_NM,
    
                CASE
                    WHEN COALESCE(B.SPNSR_BSNS_NM, ''없음'') IN
                    (
                        ''결식아동지원'',
                        ''국내아동권리보호사업(사단법인)'',
                        ''복지관후원'',
                        ''아동복지시설지원'',
                        ''아동학대예방'',
                        ''저소득가정지원''
                    )
                    THEN ''국내(사단)''
    
                    ELSE COALESCE(
                        B.SPNSR_BSNS_NM,
                        ''없음''
                    )
                END AS SPNSR_BSNS_GRP_NM,
    
                CASE
                    WHEN C.NEW_OLD_DIV_CD = ''1''
                        THEN ''신규''
                    ELSE ''기존''
                END AS NEW_EXST_DIV_NM,
    
                CASE
                    WHEN C.NEW_OLD_DIV_CD = ''1''
                     AND COALESCE(
                            D4.DEPT4_NM,
                            ''없음''
                         ) IN (
                            ''본부'',
                            ''본부(사복)''
                         )
                        THEN ''본부''
    
                    WHEN C.NEW_OLD_DIV_CD = ''1''
                        THEN ''지부''
    
                    WHEN COALESCE(
                            D4.DEPT4_NM,
                            ''없음''
                         ) = ''없음''
                        THEN ''본부''
    
                    ELSE ''기존''
                END AS HDQ_BRNCH_GRP_NM,
    
                C.WJXBFS2 AS VALUE1,
    
                TO_DECIMAL(
                    0,
                    38,
                    0
                ) AS VALUE2
    
            FROM CURRENT_FACT C
    
            LEFT JOIN CPR_DIM CP
              ON C.CPR_DIV_CD = CP.CPR_DIV_CD
    
            LEFT JOIN BUSINESS_DIM B
              ON C.SPNSR_BSNS_ID = B.SPNSR_BSNS_ID
    
            LEFT JOIN DEPT4_DIM D4
              ON C.DEPT4_ID = D4.DEPT4_ID
    
    
            UNION ALL
    
    
            /* ====================================================
               기준연도 1월 ~ 기준월 누계 납입금액
            ==================================================== */
            SELECT
                Y.STRD_MT,
                Y.CPR_DIV_CD,
                CP.CPR_DIV_NM,
    
                CASE
                    WHEN COALESCE(B.SPNSR_BSNS_NM, ''없음'') IN
                    (
                        ''결식아동지원'',
                        ''국내아동권리보호사업(사단법인)'',
                        ''복지관후원'',
                        ''아동복지시설지원'',
                        ''아동학대예방'',
                        ''저소득가정지원''
                    )
                    THEN ''국내(사단)''
    
                    ELSE COALESCE(
                        B.SPNSR_BSNS_NM,
                        ''없음''
                    )
                END AS SPNSR_BSNS_GRP_NM,
    
                CASE
                    WHEN Y.NEW_OLD_DIV_CD = ''1''
                        THEN ''신규''
                    ELSE ''기존''
                END AS NEW_EXST_DIV_NM,
    
                CASE
                    WHEN Y.NEW_OLD_DIV_CD = ''1''
                     AND COALESCE(
                            D4.DEPT4_NM,
                            ''없음''
                         ) IN (
                            ''본부'',
                            ''본부(사복)''
                         )
                        THEN ''본부''
    
                    WHEN Y.NEW_OLD_DIV_CD = ''1''
                        THEN ''지부''
    
                    WHEN COALESCE(
                            D4.DEPT4_NM,
                            ''없음''
                         ) = ''없음''
                        THEN ''본부''
    
                    ELSE ''기존''
                END AS HDQ_BRNCH_GRP_NM,
    
                TO_DECIMAL(
                    0,
                    38,
                    0
                ) AS VALUE1,
    
                Y.WJXBFS3 AS VALUE2
    
            FROM YTD_FACT Y
    
            LEFT JOIN CPR_DIM CP
              ON Y.CPR_DIV_CD = CP.CPR_DIV_CD
    
            LEFT JOIN BUSINESS_DIM B
              ON Y.SPNSR_BSNS_ID = B.SPNSR_BSNS_ID
    
            LEFT JOIN DEPT4_DIM D4
              ON Y.DEPT4_ID = D4.DEPT4_ID
        ) A
    
        GROUP BY
            STRD_MT,
            CPR_DIV_CD,
            CPR_DIV_NM,
            SPNSR_BSNS_GRP_NM,
            NEW_EXST_DIV_NM,
            HDQ_BRNCH_GRP_NM
    )
    SELECT
        R.STRD_MT,
        :AGGR_TY_NM AS AGGR_TY_NM,
        R.CPR_DIV_NM,
        R.SPNSR_BSNS_GRP_NM,
        R.NEW_EXST_DIV_NM,
        R.HDQ_BRNCH_GRP_NM,
    
        COALESCE(
            A.VALUE1,
            0
        ) AS VALUE1,
    
        COALESCE(
            A.VALUE2,
            0
        ) AS VALUE2
    
    FROM RESULT_BASE R
    
    LEFT JOIN RESULT_AGGR A
      ON R.STRD_MT = A.STRD_MT
     AND R.CPR_DIV_CD = A.CPR_DIV_CD
     AND R.CPR_DIV_NM = A.CPR_DIV_NM
     AND R.SPNSR_BSNS_GRP_NM = A.SPNSR_BSNS_GRP_NM
     AND R.NEW_EXST_DIV_NM = A.NEW_EXST_DIV_NM
     AND R.HDQ_BRNCH_GRP_NM = A.HDQ_BRNCH_GRP_NM
    WHERE R.SPNSR_BSNS_GRP_NM IN (
        ''국내(사단)'',
        ''대북지원사업'',
        ''보건의료지원사업'',
        ''식수위생지원사업'',
        ''재난구호지원사업'',
        ''전체사업지원'',
        ''좋은이웃'',
        ''해외교육지원사업'',
        ''해외아동결연'',
        ''해외지역개발사업'',
        ''희망학교지원사업''
    )
    ORDER BY
        R.STRD_MT,
        R.CPR_DIV_NM,
        R.SPNSR_BSNS_GRP_NM,
    
        CASE
            WHEN R.NEW_EXST_DIV_NM = ''신규''
             AND R.HDQ_BRNCH_GRP_NM = ''본부''
                THEN 1
    
            WHEN R.NEW_EXST_DIV_NM = ''신규''
             AND R.HDQ_BRNCH_GRP_NM = ''지부''
                THEN 2
    
            WHEN R.NEW_EXST_DIV_NM = ''기존''
             AND R.HDQ_BRNCH_GRP_NM = ''기존''
                THEN 3
    
            ELSE 9
        END;
    
    RETURN ''SUCCESS: '' || :STDR_MT;
END;
';